/* =========================================================
   ROOT VARIABLES
========================================================= */

:root {
    --sowkar-navy: #35124F;
    --sowkar-navy-2: #4A1F68;
    --sowkar-deep: #24102F;

    --sowkar-teal: #9B3F8F;
    --sowkar-teal-dark: #762D70;

    --sowkar-soft: #F8EEF7;

    /* RED ACCENT */
    --sowkar-gold: #C94B5C;

    --sowkar-purple: #9B3F8F;
    --sowkar-purple-light: #C98BC2;
    --sowkar-purple-dark: #762D70;

    --sowkar-deep: #160B20;
    --sowkar-deep-2: #211027;
    --sowkar-plum: #2D1238;
    --sowkar-wine: #35132D;

    --sowkar-red: #C94B5C;
    --sowkar-red-light: #E77A88;
    --sowkar-red-dark: #8F2E42;

    --sowkar-lavender: #D8B9E2;
    --sowkar-lavender-light: #EBDDF0;



    --sowkar-cream: #FBF8F5;

    --sowkar-white: #FFFFFF;

    --sowkar-text: #38283D;
    --sowkar-muted: #817485;

    --sowkar-border: rgba(53, 18, 79, 0.10);
}


html {
    scroll-behavior: smooth;
}

/* =========================================================
   BODY
========================================================= */

body {
    margin: 0;
    padding: 0;
    font-family: "Montserrat", sans-serif;

    color:
        var(--sowkar-text);

    background:
        #ffffff;
    overflow-x: hidden;
}

@media(max-width:993px) {
    body {
        text-align: center;
    }
}

a {
    text-decoration: none;
}

img {
    display: block;
    max-width: 100%;
}

figure {
    margin: 0;
}

.cr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    font-family: "Urbanist", sans-serif;
    font-weight: 500;

    margin: 0;
}

ul {
    margin: 0;
    padding: 0;
    list-style: none;
}

.container {
    width: 80%;
    max-width: 100%;
}

@media (max-width: 1401px) {
    .container {
        width: 80%;
    }
}

@media (max-width: 1204px) {
    .container {
        width: 95%;
    }
}

figcaption,
figure {
    margin: 0;
    padding: 0;
    height: 100%;
    width: 100%;
}

button {
    font-family:
        "Poppins",
        sans-serif;
}

.cr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}




/* =====================================================
           MAIN HEADER
        ====================================================== */

.sowkar-main-header {

    position:
        relative;

    z-index:
        1050;

    width:
        100%;

    background:
        #ffffff;

}


/* =====================================================
           NAVBAR
        ====================================================== */

.sowkar-navbar {

    position:
        relative;

    min-height:
        96px;

    padding:
        0;

    background:
        rgba(255, 255, 255, .98);

    border-bottom:
        1px solid var(--sowkar-border);

    transition:
        min-height .55s cubic-bezier(.22, 1, .36, 1),
        box-shadow .5s ease,
        background-color .5s ease,
        border-color .5s ease;

}


.sowkar-navbar-container {

    width:
        100%;

    max-width:
        1480px;

    padding-left:
        30px;

    padding-right:
        30px;

}


/* =====================================================
           LOGO
        ====================================================== */

.sowkar-brand {

    display:
        flex;

    align-items:
        center;

    flex-shrink:
        0;

    margin-right:
        auto;

    padding:
        0;

    transition:
        transform .55s cubic-bezier(.22, 1, .36, 1);

}


.sowkar-brand-logo {

    display:
        block;

    width:
        100%;

    height:
        auto;

    transition:
        width .6s cubic-bezier(.22, 1, .36, 1),
        transform .6s cubic-bezier(.22, 1, .36, 1);

}


/* =====================================================
           MAIN MENU
        ====================================================== */

.sowkar-main-menu {

    display:
        flex;

    align-items:
        center;

    flex-wrap:
        nowrap;

    gap:
        3px;

}


.sowkar-menu-item {

    position:
        static;

}


/* =====================================================
           MENU LINK
        ====================================================== */

.sowkar-menu-link {

    position:
        relative;

    z-index:
        1;

    display:
        flex !important;

    align-items:
        center;

    justify-content:
        center;

    gap:
        7px;

    white-space:
        nowrap;

    padding:
        35px 12px !important;

    color:
        var(--sowkar-navy) !important;

    font-size:
        13px;

    font-weight:
        600;

    line-height:
        1;

    letter-spacing:
        .25px;

    text-transform:
        uppercase;

    text-decoration:
        none;

    border-radius:
        9px;

    transition:
        color .3s ease,
        padding .55s cubic-bezier(.22, 1, .36, 1);

}


/* =====================================================
           MENU CAPSULE
        ====================================================== */

.sowkar-menu-link::before {

    content:
        "";

    position:
        absolute;

    z-index:
        -1;

    top:
        50%;

    left:
        5px;

    right:
        5px;

    height:
        32px;

    border-radius:
        8px;

    background:
        linear-gradient(135deg,
            rgba(155, 63, 143, 0.13),
            rgba(248, 238, 247, 0.55));

    opacity:
        0;

    transform:
        translateY(-50%) scale(.90);

    transform-origin:
        center;

    transition:
        opacity .3s ease,
        transform .4s cubic-bezier(.22, 1, .36, 1);

    pointer-events:
        none;

}


/* =====================================================
           NORMAL MENU BOTTOM LINE
        ====================================================== */

.sowkar-menu-link::after {

    content:
        "";

    position:
        absolute;

    z-index:
        5;

    left:
        50%;

    bottom:
        18px;

    display:
        block !important;

    width:
        0;

    height:
        2px;

    border:
        0 !important;

    border-radius:
        20px;

    background: #6e3278 !important;

    transform:
        translateX(-50%);

    transition:
        width .4s cubic-bezier(.22, 1, .36, 1),
        bottom .55s cubic-bezier(.22, 1, .36, 1);

    pointer-events:
        none;

}


/* =====================================================
           MENU HOVER
        ====================================================== */

.sowkar-menu-link:hover,
.sowkar-menu-link.active {

    color: #C94B5C !important;

}


.sowkar-menu-link:hover::before,
.sowkar-menu-link.active::before {

    opacity:
        1;

    transform:
        translateY(-50%) scale(1);

}


.sowkar-menu-link:hover::after,
.sowkar-menu-link.active::after {

    width:
        24px !important;

}


/* =====================================================
           PRODUCTS CUSTOM LINE
        ====================================================== */



.sowkar-products-toggle.dropdown-toggle::after {

    display:
        block !important;

    position:
        absolute;

    z-index:
        5;

    left:
        50%;

    bottom:
        18px;

    width:
        0;

    height:
        2px;

    margin:
        0;

    vertical-align:
        unset;

    content:
        "";

    border:
        0 !important;

    border-top:
        0 !important;

    border-right:
        0 !important;

    border-bottom:
        0 !important;

    border-left:
        0 !important;

    border-radius:
        20px;

    background:
        #6e3278 !important;

    transform:
        translateX(-50%);

    transition:
        width .4s cubic-bezier(.22, 1, .36, 1),
        bottom .55s cubic-bezier(.22, 1, .36, 1);

    pointer-events:
        none;

}


.sowkar-products-toggle:hover::after {

    width:
        24px !important;

}


.sowkar-products-menu.show>.sowkar-products-toggle {

    color:
        #C94B5C !important;

}


.sowkar-products-menu.show>.sowkar-products-toggle::before {

    opacity:
        1;

    transform:
        translateY(-50%) scale(1);

}


.sowkar-products-menu.show>.sowkar-products-toggle::after {

    width:
        24px !important;

}

.sowkar-products-toggle.dropdown-toggle:hover,
.sowkar-products-toggle.dropdown-toggle.active {
    color: #C94B5C !important;
}


/* =====================================================
           PRODUCTS ARROW
        ====================================================== */

.sowkar-products-arrow {

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    width:
        16px;

    height:
        16px;

    flex-shrink:
        0;

    transition:
        transform .4s cubic-bezier(.22, 1, .36, 1);

}


.sowkar-products-arrow i {

    font-size:
        9px;

}


.sowkar-products-menu.show .sowkar-products-arrow {

    transform:
        rotate(180deg);

}


/* =====================================================
           CREATIVE TOGGLER
        ====================================================== */

.sowkar-menu-toggler {

    display:
        none;

    width:
        48px;

    height:
        48px;

    align-items:
        center;

    justify-content:
        center;

    padding:
        0;

    border:
        1px solid rgba(6, 43, 63, .13);

    border-radius:
        12px;

    background:
        #ffffff;

    box-shadow:
        none !important;

    transition:
        background-color .3s ease,
        border-color .3s ease,
        transform .3s ease;

}


.sowkar-menu-toggler:hover {

    background:
        var(--sowkar-soft);

    border-color:
        rgba(8, 127, 135, .30);

    transform:
        translateY(-2px);

}


.sowkar-toggler-icon {

    display:
        grid;

    grid-template-columns:
        repeat(2, 7px);

    gap:
        5px;

    transform:
        rotate(45deg);

    transition:
        transform .45s cubic-bezier(.22, 1, .36, 1);

}


.sowkar-toggler-icon span {

    display:
        block;

    width:
        7px;

    height:
        7px;

    border-radius:
        2px;

    background:
        var(--sowkar-navy);

    transition:
        background-color .3s ease,
        transform .35s ease;

}


.sowkar-toggler-icon span:nth-child(2),
.sowkar-toggler-icon span:nth-child(3) {

    background:
        var(--sowkar-teal);

}


.sowkar-menu-toggler:hover .sowkar-toggler-icon {

    transform:
        rotate(0deg) scale(1.1);

}


.sowkar-menu-toggler:hover .sowkar-toggler-icon span {

    background:
        var(--sowkar-teal);

}


/* =====================================================
           ENQUIRY BUTTON
        ====================================================== */

.sowkar-enquiry-item {

    margin-left:
        8px;

    flex-shrink:
        0;

}


.sowkar-enquiry-button {

    position:
        relative;

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    gap:
        12px;

    min-width:
        130px;

    padding:
        13px 17px;

    color:
        #ffffff;

    background:
        var(--sowkar-gold);

    border:
        1px solid var(--sowkar-gold);

    border-radius:
        7px;

    font-size:
        10px;

    font-weight:
        700;

    letter-spacing:
        .5px;

    text-transform:
        uppercase;

    text-decoration:
        none;

    overflow:
        hidden;

    isolation:
        isolate;

    transition:
        transform .35s cubic-bezier(.22, 1, .36, 1),
        box-shadow .35s ease,
        border-color .35s ease;

}


.sowkar-enquiry-button::before {

    content:
        "";

    position:
        absolute;

    inset:
        0;

    background:
        var(--sowkar-teal);

    transform:
        translateX(-102%);

    transition:
        transform .45s cubic-bezier(.22, 1, .36, 1);

    z-index:
        -1;

}


.sowkar-enquiry-button::after {

    content:
        "";

    position:
        absolute;

    top:
        0;

    left:
        -80%;

    width:
        45%;

    height:
        100%;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, .22),
            transparent);

    transform:
        skewX(-20deg);

    transition:
        left .7s ease;

    z-index:
        1;

}


.sowkar-enquiry-button span,
.sowkar-enquiry-button i {

    position:
        relative;

    z-index:
        3;

}


.sowkar-enquiry-button i {

    font-size:
        12px;

    transition:
        transform .35s cubic-bezier(.22, 1, .36, 1);

}


.sowkar-enquiry-button:hover {

    color:
        #ffffff;

    border-color:
        var(--sowkar-teal);

    transform:
        translateY(-3px);

    box-shadow:
        0 12px 28px rgba(6, 43, 63, .18);

}


.sowkar-enquiry-button:hover::before {

    transform:
        translateX(0);

}


.sowkar-enquiry-button:hover::after {

    left:
        130%;

}


.sowkar-enquiry-button:hover i {

    transform:
        translate(4px, -4px) rotate(3deg);

}


/* =====================================================
           PRODUCTS MEGA MENU
        ====================================================== */

.sowkar-products-mega-menu {

    position:
        fixed !important;

    top:
        96px !important;

    left:
        50% !important;

    width:
        min(1180px,
            calc(100vw - 40px)) !important;

    margin:
        0 !important;

    padding:
        0 !important;

    border:
        1px solid rgba(6, 43, 63, .10);

    border-radius:
        0 0 20px 20px;

    background:
        #ffffff;

    box-shadow:
        0 30px 70px rgba(3, 29, 43, .20);

    overflow:
        hidden;

    opacity:
        0;

    visibility:
        hidden;

    transform:
        translate(-50%, -14px) scale(.985);

    transform-origin:
        top center;

    transition:
        opacity .25s ease,
        visibility .25s ease,
        transform .4s cubic-bezier(.22, 1, .36, 1);

}


.sowkar-products-mega-menu.show {

    opacity:
        1;

    visibility:
        visible;

    transform:
        translate(-50%, 0) scale(1);

}


/* =====================================================
           MEGA MENU
        ====================================================== */

.sowkar-mega-inner {

    display:
        grid;

    grid-template-columns:
        235px minmax(0, 1fr) 270px;

    min-height:
        375px;

}


/* =====================================================
           HEALTH CARE FEATURE
        ====================================================== */

.sowkar-healthcare-feature {

    position:
        relative;

    padding:
        32px 26px;

    color:
        #ffffff;

    background:
        radial-gradient(circle at 100% 0%,
            rgba(201, 75, 92, .42),
            transparent 46%),
        linear-gradient(145deg,
            #24102F,
            #4A1F68);

    overflow:
        hidden;

}


.sowkar-healthcare-feature::before {

    content:
        "";

    position:
        absolute;

    width:
        190px;

    height:
        190px;

    right:
        -105px;

    bottom:
        -105px;

    border:
        1px solid rgba(255, 255, 255, .15);

    border-radius:
        50%;

}


.sowkar-healthcare-feature::after {

    content:
        "";

    position:
        absolute;

    width:
        110px;

    height:
        110px;

    right:
        -65px;

    bottom:
        -65px;

    border:
        1px solid rgba(255, 255, 255, .10);

    border-radius:
        50%;

}


.sowkar-feature-top {

    display:
        flex;

    align-items:
        center;

    gap:
        12px;

    margin-bottom:
        20px;

}


.sowkar-feature-icon {

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    width:
        44px;

    height:
        44px;

    flex-shrink:
        0;

    color:
        var(--sowkar-navy);

    background:
        #ffffff;

    border-radius:
        12px;

    font-size:
        19px;

}


.sowkar-feature-label {

    display:
        block;

    margin-bottom:
        3px;

    color: #D8B9E2;

    font-size:
        8px;

    font-weight:
        700;

    letter-spacing:
        1.5px;

}


.sowkar-feature-top h3 {

    margin:
        0;

    font-family:
        "Playfair Display",
        serif;

    font-size:
        22px;

    font-weight:
        700;

}


.sowkar-healthcare-feature p {

    position:
        relative;

    z-index:
        2;

    margin:
        0 0 28px;

    color:
        rgba(255, 255, 255, .72);

    font-size:
        11px;

    line-height:
        1.8;

}


.sowkar-healthcare-view {

    position:
        relative;

    z-index:
        3;

    display:
        inline-flex;

    align-items:
        center;

    gap:
        10px;

    color:
        #ffffff;

    font-size:
        12px;

    font-weight:
        700;

    text-decoration:
        none;

}


.sowkar-healthcare-view:hover {

    color:
        #ffffff;

}


.sowkar-healthcare-view span {

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    width:
        28px;

    height:
        28px;

    color:
        var(--sowkar-navy);

    background:
        #ffffff;

    border-radius:
        50%;

    transition:
        transform .3s ease;

}


.sowkar-healthcare-view:hover span {

    transform:
        translate(3px, -3px);

}


/* =====================================================
           HEALTH CARE PRODUCTS
        ====================================================== */

.sowkar-healthcare-list {

    padding:
        29px 25px;

    background:
        #ffffff;

}


.sowkar-mega-heading {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    margin-bottom:
        13px;

    color:
        var(--sowkar-red);

    font-size:
        9px;

    font-weight:
        800;

    letter-spacing:
        1.6px;

    text-transform:
        uppercase;

}


.sowkar-mega-heading i {

    color:
        var(--sowkar-teal);

    font-size:
        15px;

}


.sowkar-healthcare-grid {

    display:
        grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap:
        4px 10px;

}


.sowkar-healthcare-grid a {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    min-width:
        0;

    padding:
        9px 7px;

    color:
        var(--sowkar-navy);

    border-radius:
        8px;

    text-decoration:
        none;

    transition:
        background-color .25s ease,
        color .25s ease,
        transform .25s ease;

}


.sowkar-healthcare-grid a:hover {

    color:
        var(--sowkar-teal);

    background:
        var(--sowkar-soft);

    transform:
        translateX(4px);

}

.sowkar-healthcare-grid .active {

    color:
        var(--sowkar-teal);

    background:
        var(--sowkar-soft);

    transform:
        translateX(4px);

}


.sowkar-healthcare-grid a span {

    display:
        flex;

    align-items:
        center;

    gap:
        9px;

    min-width:
        0;

    font-size:
        12px;

    font-weight:
        600;

}


.sowkar-healthcare-grid a span i {

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    width:
        29px;

    height:
        29px;

    flex-shrink:
        0;

    color:
        var(--sowkar-teal);

    background:
        #f0f8f8;

    border-radius:
        7px;

    font-size:
        13px;

}


.sowkar-healthcare-grid a>i {

    color:
        var(--sowkar-teal);

    font-size:
        10px;

    opacity:
        0;

    transform:
        translateX(-5px);

    transition:
        opacity .25s ease,
        transform .25s ease;

}


.sowkar-healthcare-grid a:hover>i {

    opacity:
        1;

    transform:
        translateX(0);

}


/* =====================================================
           OTHER SOLUTIONS
        ====================================================== */

.sowkar-other-solutions {

    padding:
        29px 21px;

    background:
        #f5f9f9;

    border-left:
        1px solid rgba(6, 43, 63, .07);

}


.sowkar-other-product {

    display:
        grid;

    grid-template-columns:
        27px minmax(0, 1fr) 13px;

    align-items:
        center;

    gap:
        8px;

    padding:
        9px 4px;

    color:
        var(--sowkar-navy);

    border-bottom:
        1px solid rgba(6, 43, 63, .07);

    text-decoration:
        none;

    transition:
        color .25s ease,
        transform .25s ease;

}


.sowkar-other-product:hover {

    color:
        var(--sowkar-teal);

    transform:
        translateX(4px);

}

.sowkar-other-solutions .active {

    color:
        var(--sowkar-teal);

    transform:
        translateX(4px);

}


.sowkar-other-number {

    color:
        #9aabad;

    font-size:
        9px;

    font-weight:
        700;

}


.sowkar-other-content strong {

    display:
        block;

    font-size:
        12px;

    font-weight:
        700;

}


.sowkar-other-content small {

    display:
        block;

    margin-top:
        2px;

    color:
        #84969b;

    font-size:
        11px;

}


.sowkar-other-product>i {

    font-size:
        10px;

}


/* =====================================================
           OFFCANVAS
        ====================================================== */

.sowkar-navigation-offcanvas {

    background:
        #ffffff;

}


.sowkar-navigation-body {

    display:
        flex;

    align-items:
        center;

}


.sowkar-offcanvas-header {

    display:
        none;

}


.sowkar-mobile-brand img {

    display:
        block;

    width:
        205px;

    height:
        auto;

}


/* =====================================================
           OFFCANVAS CLOSE
        ====================================================== */

.sowkar-offcanvas-close {

    position:
        relative;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    width:
        40px;

    height:
        40px;

    padding:
        0;

    margin-left:
        auto;

    border:
        0;

    border-radius:
        50%;

    background:
        var(--sowkar-soft);

    opacity:
        1;

    transition:
        transform .35s ease,
        background-color .35s ease;

}


.sowkar-offcanvas-close:hover {

    background:
        #dceeee;

    transform:
        rotate(90deg);

}


.sowkar-offcanvas-close::before,
.sowkar-offcanvas-close::after {

    content:
        "";

    position:
        absolute;

    width:
        17px;

    height:
        2px;

    background:
        var(--sowkar-navy);

    border-radius:
        10px;

}


.sowkar-offcanvas-close::before {

    transform:
        rotate(45deg);

}


.sowkar-offcanvas-close::after {

    transform:
        rotate(-45deg);

}


