}


/* =====================================================
           FIXED HEADER BOTTOM ANIMATION
           
           IMPORTANT:
           This is the line that travels from
           LEFT -> RIGHT when header becomes fixed.
        ====================================================== */

.sowkar-main-header.sowkar-header-scrolled .sowkar-navbar::after {

    content:
        "";

    position:
        absolute;

    left:
        0;

    bottom:
        -1px;

    width:
        100%;

    height:
        2px;

    background:
        linear-gradient(90deg,
            var(--sowkar-teal),
            var(--sowkar-teal),
            var(--sowkar-gold));

    transform:
        scaleX(0);

    transform-origin:
        left center;

    animation:
        sowkarHeaderBottomLine .8s cubic-bezier(.22, 1, .36, 1) .15s forwards;

}


@keyframes sowkarHeaderBottomLine {

    0% {

        transform:
            scaleX(0);

    }

    100% {

