/* =========================================================
   HERO / CAROUSEL FOUNDATION
========================================================= */

.sowkar-hc-hero {
    position: relative;
    width: 100%;
    height: 760px;
    overflow: hidden;
    isolation: isolate;
    background:
        radial-gradient(circle at 76% 50%, rgba(155, 63, 143, .16), transparent 30%),
        radial-gradient(circle at 90% 12%, rgba(201, 75, 92, .10), transparent 24%),
        linear-gradient(125deg, #0e0714 0%, #1b0c23 48%, #25102d 100%);
}

.sowkar-hc-carousel,
.sowkar-hc-carousel .carousel-inner,
.sowkar-hc-carousel .carousel-item {
    position: relative;
    width: 100%;
    height: 100%;
}

/*
   IMPORTANT:
   The carousel itself does NOT fade.
   Each slide appears once, and the image/content have their
   own entrance animation. This avoids the "normal + animation"
   feeling and prevents the image from jumping or zooming.
*/
.sowkar-hc-carousel .carousel-item {
    transform: none !important;
    opacity: 0;
    transition: none !important;
}

.sowkar-hc-carousel .carousel-item.active {
    opacity: 1;
    transform: none !important;
}

.sowkar-hc-carousel .carousel-item-next,
.sowkar-hc-carousel .carousel-item-prev,
.sowkar-hc-carousel .carousel-item.active.carousel-item-start,
.sowkar-hc-carousel .carousel-item.active.carousel-item-end,
.sowkar-hc-carousel .carousel-item-next.carousel-item-start,
.sowkar-hc-carousel .carousel-item-prev.carousel-item-end {
    transform: none !important;
}

/* =========================================================
   SIX DISTINCT SLIDE ATMOSPHERES
========================================================= */

.sowkar-hc-carousel .carousel-item:nth-child(1) {
    background:
        radial-gradient(circle at 78% 28%, rgba(177, 88, 170, .34), transparent 28%),
        radial-gradient(circle at 18% 80%, rgba(86, 37, 111, .26), transparent 32%),
        linear-gradient(120deg, #12081a 0%, #351544 56%, #170a22 100%);
}

.sowkar-hc-carousel .carousel-item:nth-child(2) {
    background:
        radial-gradient(circle at 82% 35%, rgba(221, 86, 105, .34), transparent 28%),
        radial-gradient(circle at 20% 22%, rgba(115, 37, 69, .28), transparent 30%),
        linear-gradient(120deg, #170810 0%, #4a172d 56%, #1b0a18 100%);
}

.sowkar-hc-carousel .carousel-item:nth-child(3) {
    background:
        radial-gradient(circle at 76% 64%, rgba(116, 96, 180, .34), transparent 30%),
        radial-gradient(circle at 16% 20%, rgba(205, 157, 219, .18), transparent 28%),
        linear-gradient(120deg, #0e0a1c 0%, #29204c 58%, #120d24 100%);
}

.sowkar-hc-carousel .carousel-item:nth-child(4) {
    background:
        radial-gradient(circle at 82% 24%, rgba(210, 121, 74, .28), transparent 28%),
        radial-gradient(circle at 22% 76%, rgba(116, 50, 90, .28), transparent 32%),
        linear-gradient(120deg, #160b13 0%, #442035 58%, #1a0d16 100%);
}

.sowkar-hc-carousel .carousel-item:nth-child(5) {
    background:
        radial-gradient(circle at 78% 42%, rgba(201, 75, 92, .22), transparent 30%),
        radial-gradient(circle at 18% 25%, rgba(216, 185, 226, .18), transparent 32%),
        linear-gradient(120deg, #24102F 0%, #4A1F68 52%, #35124F 100%);
}

.sowkar-hc-carousel .carousel-item:nth-child(6) {
    background:
        radial-gradient(circle at 82% 28%,
            rgba(201, 75, 92, .30),
            transparent 31%),
        radial-gradient(circle at 12% 82%,
            rgba(216, 185, 226, .20),
            transparent 34%),
        linear-gradient(120deg,
            #210A20 0%,
            #4A1638 52%,
            #2D102C 100%);
}

/* Each slide gets its own subtle content-side tint */
.sowkar-hc-carousel .carousel-item:nth-child(1) .sowkar-hc-left {
    background: linear-gradient(90deg, rgba(13, 6, 19, .99), rgba(28, 11, 35, .93), rgba(28, 11, 35, .12));
}

.sowkar-hc-carousel .carousel-item:nth-child(2) .sowkar-hc-left {
    background: linear-gradient(90deg, rgba(20, 7, 12, .99), rgba(46, 13, 27, .93), rgba(46, 13, 27, .12));
}

.sowkar-hc-carousel .carousel-item:nth-child(3) .sowkar-hc-left {
    background: linear-gradient(90deg, rgba(9, 8, 21, .99), rgba(31, 24, 55, .93), rgba(31, 24, 55, .12));
}

.sowkar-hc-carousel .carousel-item:nth-child(4) .sowkar-hc-left {
    background: linear-gradient(90deg, rgba(18, 8, 13, .99), rgba(48, 21, 36, .93), rgba(48, 21, 36, .12));
}

.sowkar-hc-carousel .carousel-item:nth-child(5) .sowkar-hc-left {
    background:
        linear-gradient(90deg,
            rgba(36, 16, 47, .99),
            rgba(74, 31, 104, .94),
            rgba(74, 31, 104, .12));
}

.sowkar-hc-carousel .carousel-item:nth-child(6) .sowkar-hc-left {
    background:
        linear-gradient(90deg,
            rgba(33, 10, 32, .99),
            rgba(74, 22, 56, .94),
            rgba(74, 22, 56, .10));
}

/* =========================================================
   LEFT CONTENT PANEL
========================================================= */

.sowkar-hc-left {
    position: absolute;
    left: 0;
    top: 0;
    width: 50%;
    height: 100%;
    z-index: 10;
    padding-left: 7%;
    padding-right: 4%;
    display: flex;
    align-items: center;
    overflow: hidden;
    background:
        linear-gradient(90deg, rgba(11, 5, 16, .98) 0%, rgba(17, 7, 22, .94) 65%, rgba(17, 7, 22, .18) 100%);
}

/* Architectural vertical rails — static, not animated */
.sowkar-hc-left::before {
    content: "";
    position: absolute;
    top: 0;
    right: 15%;
    width: 1px;
    height: 100%;
    background: linear-gradient(to bottom,
            transparent,
            rgba(234, 220, 240, .12) 20%,
            rgba(201, 75, 92, .24) 50%,
            rgba(234, 220, 240, .08) 80%,
            transparent);
    pointer-events: none;
}

.sowkar-hc-left::after {
    content: "";
    position: absolute;
    left: -130px;
    bottom: -180px;
    width: 420px;
    height: 420px;
    border: 1px solid rgba(214, 165, 208, .10);
    border-radius: 50%;
    box-shadow:
        0 0 0 35px rgba(155, 63, 143, .025),
        0 0 0 90px rgba(201, 75, 92, .018);
    pointer-events: none;
}

