/* =========================================================
   CTA — CLEAN EDITORIAL BUTTON
========================================================= */

.sowkar-hc-cta {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 265px;
    height: 57px;
    margin-top: 27px;
    padding: 0 9px 0 22px;
    overflow: hidden;

    color: #fff;
    text-decoration: none;

    background: linear-gradient(100deg,
            #8f376f,
            #b74358);

    border: 1px solid rgba(255, 255, 255, .13);

    box-shadow:
        0 18px 45px rgba(0, 0, 0, .22);

    transition:
        transform .35s ease,
        box-shadow .35s ease,
        background .35s ease;
}

.sowkar-hc-cta span:first-child {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.8px;

    transition:
        transform .35s ease;
}

.sowkar-hc-cta-arrow {
    display: flex;
    align-items: center;
    justify-content: center;

    width: 39px;
    height: 39px;

    color: var(--sowkar-deep);
    background: rgba(255, 255, 255, .88);

    font-size: 16px;

    transition:
        transform .4s cubic-bezier(.16, 1, .3, 1),
        background .35s ease,
        color .35s ease;
}


/* =========================
   PREMIUM HOVER
   ========================= */

.sowkar-hc-cta:hover {
    color: #fff;

    transform: translateY(-3px);

    background: linear-gradient(100deg,
            #9b3f8f,
            #c94b5c);

    box-shadow:
        0 22px 48px rgba(0, 0, 0, .28);
}

.sowkar-hc-cta:hover span:first-child {
    transform: translateX(3px);
}

.sowkar-hc-cta:hover .sowkar-hc-cta-arrow {
    transform: translateX(4px);

    background: #fff;
    color: #35124F;
}

/* =========================================================
   RIGHT IMAGE — EDITORIAL REVEAL
========================================================= */

.sowkar-hc-image {
    position: absolute;
    top: 5%;
    right: 2.5%;
    width: 56%;
    height: 90%;
    z-index: 5;
    overflow: hidden;
    border-radius: 110px 0 0 12px;
    background: #1b0b22;
    box-shadow:
        -30px 0 70px rgba(0, 0, 0, .24),
        0 25px 60px rgba(0, 0, 0, .30);
    clip-path: inset(0 0 0 0 round 110px 0 0 12px);
}

.sowkar-hc-image img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transform: none !important;
    animation: none !important;
    transition: none !important;
    backface-visibility: hidden;
    will-change: auto;
}

/* The image container itself enters once from the right.
   The actual image remains perfectly still inside it. */
.sowkar-hc-carousel .carousel-item.active .sowkar-hc-image {
    animation: sowkarHCImageReveal .95s cubic-bezier(.16, 1, .3, 1) both;
}

@keyframes sowkarHCImageReveal {
    from {
        opacity: 0;
        transform: translate3d(58px, 0, 0);
        clip-path: inset(0 0 0 12% round 110px 0 0 12px);
    }

    to {
        opacity: 1;
        transform: translate3d(0, 0, 0);
        clip-path: inset(0 0 0 0 round 110px 0 0 12px);
    }
}

.sowkar-hc-image::after {
    content: "";
    position: absolute;
    inset: 0;
    background:
        linear-gradient(90deg, rgba(17, 7, 22, .30), transparent 25%),
        linear-gradient(180deg, rgba(10, 4, 14, .04), transparent 48%, rgba(10, 4, 14, .26));
    pointer-events: none;
}

.sowkar-hc-image::before {
    content: "";
    position: absolute;
    left: 0;
    top: 13%;
    width: 1px;
    height: 74%;
    z-index: 12;
    background: linear-gradient(to bottom,
            transparent,
            rgba(234, 220, 240, .42),
            rgba(201, 75, 92, .72),
            transparent);
    pointer-events: none;
}

/* =========================================================
   IMAGE ACCENTS — REFINED, NO TRIANGLE
========================================================= */

.sowkar-hc-image-accent {
    position: absolute;
    top: 0;
    right: 0;
    width: 120px;
    height: 120px;
    z-index: 20;
    border-top: 1px solid rgba(234, 220, 240, .75);
    border-right: 1px solid rgba(201, 75, 92, .80);
    border-radius: 0 0 0 42px;
    background: linear-gradient(135deg, rgba(255, 255, 255, .05), transparent 55%);
}

.sowkar-hc-image-accent::after {
    content: "";
    position: absolute;
    top: 18px;
    right: 18px;
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--sowkar-red-light);
    box-shadow: 0 0 0 6px rgba(201, 75, 92, .10);
}

.sowkar-hc-image-bottom {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 230px;
    height: 78px;
    z-index: 20;
    background: transparent;
    border-right: 1px solid rgba(234, 220, 240, .45);
    border-bottom: 1px solid rgba(201, 75, 92, .70);
}

.sowkar-hc-image-bottom::before {
    content: "";
    position: absolute;
    right: 18px;
    bottom: 18px;
    width: 115px;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--sowkar-purple-light), var(--sowkar-red));
}

/* =========================================================
   PRODUCT BADGE
========================================================= */

.sowkar-hc-product-badge {
    position: absolute;
    top: 50%;
    right: 24px;
    z-index: 25;
    width: 82px;
    min-height: 82px;
    padding: 16px 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: rgba(255, 255, 255, .92);
    background: rgba(18, 7, 24, .62);
    border: 1px solid rgba(234, 220, 240, .24);
    border-radius: 50%;
    backdrop-filter: blur(10px);
    box-shadow: 0 12px 30px rgba(0, 0, 0, .20);
    font-size: 7px;
    font-weight: 700;
    line-height: 1.55;
    letter-spacing: 1.2px;
}

/* =========================================================
   DECORATIVE DOT GRID
========================================================= */

.sowkar-hc-grid {
    position: absolute;
    right: 3.5%;
    bottom: 11%;
    z-index: 28;
    width: 88px;
    height: 58px;
    opacity: .45;
    background-image: radial-gradient(circle, rgba(234, 220, 240, .72) 1px, transparent 1px);
    background-size: 10px 10px;
    mask-image: linear-gradient(90deg, transparent, #000 30%, #000);
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 30%, #000);
    pointer-events: none;
}


/* =========================================================
   SLIDE-SPECIFIC ACCENTS
========================================================= */

.sowkar-hc-carousel .carousel-item:nth-child(1) .sowkar-hc-title span,
.sowkar-hc-carousel .carousel-item:nth-child(1) .sowkar-hc-tagline span {
    color: #d6a5d0;
}

.sowkar-hc-carousel .carousel-item:nth-child(2) .sowkar-hc-title span,
.sowkar-hc-carousel .carousel-item:nth-child(2) .sowkar-hc-tagline span {
    color: #e47b88;
}

.sowkar-hc-carousel .carousel-item:nth-child(3) .sowkar-hc-title span,
.sowkar-hc-carousel .carousel-item:nth-child(3) .sowkar-hc-tagline span {
