.sowkar-hc-carousel .carousel-item:nth-child(6) .sowkar-hc-title span,
.sowkar-hc-carousel .carousel-item:nth-child(6) .sowkar-hc-tagline span {
    color: #a97498;
}

/* =========================================================
   COUNTER
========================================================= */

.sowkar-hc-counter {
    position: absolute;
    left: 7%;
    bottom: 34px;
    z-index: 35;
    display: flex;
    align-items: flex-end;
    gap: 7px;
