    letter-spacing: 2px;
}

/* =========================================================
   INDICATORS — MINIMAL EDITORIAL RAIL
========================================================= */

.sowkar-hc-indicators {
    position: absolute;
    left: 15.5% !important;
    right: auto !important;
    bottom: 37px !important;
    z-index: 40;
    width: auto;
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 8px;
}

.sowkar-hc-indicators button {
    width: 7px !important;
    height: 7px !important;
    margin: 0 !important;
    padding: 0;
    border: 0 !important;
    border-radius: 50%;
    opacity: .32;
    background: rgba(255, 255, 255, .75) !important;
}

.sowkar-hc-indicators button.active {
    width: 30px !important;
    border-radius: 20px;
    opacity: 1;
    background: linear-gradient(90deg, var(--sowkar-purple-light), var(--sowkar-red)) !important;
}

/* =========================================================
   ARROWS — SQUARE LUXURY CONTROLS
========================================================= */

.sowkar-hc-control {
    position: absolute;
    top: auto;
    bottom: 28px;
    z-index: 50;
    width: 52px;
    height: 52px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(234, 220, 240, .20);
    border-radius: 0;
    background: rgba(15, 6, 20, .68);
    backdrop-filter: blur(8px);
    opacity: 1;
}

.sowkar-hc-control i {
    color: rgba(255, 255, 255, .88);
    font-size: 17px;
}

.sowkar-hc-control:hover {
    background: rgba(201, 75, 92, .18);
    border-color: rgba(201, 75, 92, .55);
}

.sowkar-hc-prev {
    left: 1.5%;
}

.sowkar-hc-next {
    right: 1.5%;
}

/* =========================================================
   TOP RIGHT CORNER — STATIC BRAND DETAIL
========================================================= */

.sowkar-hc-corner {
    position: absolute;
    top: 28px;
    right: 3%;
    z-index: 30;
    width: 105px;
    height: 105px;
    border-top: 1px solid rgba(234, 220, 240, .42);
    border-right: 1px solid rgba(201, 75, 92, .60);
    pointer-events: none;
}

.sowkar-hc-corner::before {
    content: "";
    position: absolute;
    top: 15px;
    right: 15px;
    width: 44px;
    height: 44px;
    border-top: 1px solid rgba(201, 75, 92, .42);
    border-right: 1px solid rgba(234, 220, 240, .25);
}

/* =========================================================
   DESKTOP IMAGE SEAM
========================================================= */

.sowkar-hc-image+.sowkar-hc-left {
    box-shadow: 24px 0 60px rgba(0, 0, 0, .18);
}

/* =========================================================
   CONTENT ENTRANCE — DIRECTIONAL, NOT FADE-ONLY
========================================================= */

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-content>* {
    opacity: 0;
    animation: sowkarHCTextIn .72s cubic-bezier(.16, 1, .3, 1) both;
}

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-label {
    animation-delay: .08s;
}

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-premium {
    animation-delay: .15s;
}

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-title {
    animation-delay: .22s;
}

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-tagline {
    animation-delay: .29s;
}

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-line {
    animation-delay: .35s;
}

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-description {
    animation-delay: .41s;
}

.sowkar-hc-carousel .carousel-item.active .sowkar-hc-cta {
    animation-delay: .48s;
}

@keyframes sowkarHCTextIn {
    from {
        opacity: 0;
        transform: translate3d(-34px, 0, 0);
    }

    to {
        opacity: 1;
        transform: translate3d(0, 0, 0);
    }
}



/* =========================================================
   SOWKAR HC — CLEAN CREATIVE LEFT PANEL
   ========================================================= */

.sowkar-hc-left {
    position: relative;
    overflow: hidden;
    isolation: isolate;
}

/* Soft oversized ambient glow */
.sowkar-hc-left::before {
    content: "";
    position: absolute;

    width: 480px;
    height: 480px;

    left: -250px;
    top: 50%;

    transform: translateY(-50%);

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(216, 185, 226, .20) 0%,
            rgba(201, 75, 92, .10) 38%,
            transparent 72%);

    filter: blur(10px);

    pointer-events: none;
    z-index: -1;

    animation:
        sowkarHCSoftGlow 8s ease-in-out infinite;
}


/* Small blurred floating glow */
.sowkar-hc-left {
    background-image:
        radial-gradient(circle at 18% 18%,
            rgba(255, 255, 255, .07) 0,
            rgba(255, 255, 255, .035) 80px,
            transparent 150px),
        radial-gradient(circle at 8% 82%,
            rgba(201, 75, 92, .10) 0,
            transparent 180px);
}


/* =========================================================
   SOFT GLOW ANIMATION
   ========================================================= */

@keyframes sowkarHCSoftGlow {

    0%,
    100% {
        transform: translateY(-50%) scale(1);
        opacity: .65;
    }

    50% {
        transform: translateY(-50%) scale(1.12);
        opacity: 1;
    }
}


/* =========================================================
   SLIDE 5 — PURPLE GLOW
   ========================================================= */

.sowkar-hc-carousel .carousel-item:nth-child(5) .sowkar-hc-left::before {

    background:
        radial-gradient(circle,
            rgba(216, 185, 226, .24) 0%,
