/* =========================================================
   V4 CREATIVE PRODUCT BADGE
   - No font-family change
   - Designed as a premium editorial seal
========================================================= */
.sowkar-hc-product-badge {
    position: absolute;
    top: 10%;
    right: 4.5%;
    z-index: 35;
    width: 104px;
    height: 104px;
    min-height: 104px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 18px;
    color: rgba(255, 255, 255, .94);
    font-size: 7px;
    font-weight: 700;
    line-height: 1.65;
    letter-spacing: 1.8px;
    background:
        radial-gradient(circle at 50% 45%, rgba(255, 255, 255, .10), transparent 45%),
        linear-gradient(145deg, rgba(155, 63, 143, .92), rgba(201, 75, 92, .86));
    border: 1px solid rgba(255, 255, 255, .42);
    border-radius: 50%;
    box-shadow:
        0 18px 45px rgba(0, 0, 0, .30),
        inset 0 0 0 5px rgba(255, 255, 255, .055),
        inset 0 0 0 8px rgba(255, 255, 255, .035);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transform: rotate(-7deg);
    overflow: visible;
}

.sowkar-hc-product-badge::before {
    content: "";
    position: absolute;
    inset: 7px;
    border: 1px dashed rgba(255, 255, 255, .48);
    border-radius: 50%;
    opacity: .85;
}

.sowkar-hc-product-badge::after {
    content: "✦";
    position: absolute;
    top: -8px;
    right: 11px;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 10px;
    background: var(--sowkar-deep);
    border: 1px solid rgba(255, 255, 255, .30);
    border-radius: 50%;
    box-shadow: 0 7px 18px rgba(0, 0, 0, .25);
}

.sowkar-hc-product-badge {
    animation: sowkarHCBadgeFloat 5s ease-in-out infinite;
}

@keyframes sowkarHCBadgeFloat {

    0%,
