/* =========================================================
   CREATIVE PREMIUM PRODUCT BADGE
   ========================================================= */

.sowkar-hc-product-badge {
    position: absolute;
    top: 48px;
    left: 47%;
    z-index: 20;

    width: 112px;
    height: 112px;
    padding: 18px;

    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;

    color: #ffffff;
    background:
        radial-gradient(circle at 35% 28%,
            rgba(255, 255, 255, .24) 0 3%,
            transparent 4%),
        linear-gradient(145deg,
            rgba(216, 185, 226, .96),
            rgba(155, 63, 143, .96) 48%,
            rgba(201, 75, 92, .96));

    border: 1px solid rgba(255, 255, 255, .55);
    border-radius: 50%;

    box-shadow:
        0 18px 42px rgba(0, 0, 0, .30),
        0 0 0 7px rgba(255, 255, 255, .055),
        0 0 0 8px rgba(201, 75, 92, .10);

    font-size: 8px;
    font-weight: 800;
    line-height: 1.55;
    letter-spacing: 1.5px;
    text-transform: uppercase;

    isolation: isolate;
    overflow: hidden;

    transform: translateZ(0) rotate(-7deg);
    animation:
        sowkarBadgeFloat 4.8s ease-in-out infinite,
        sowkarBadgeEnter .9s cubic-bezier(.16, 1, .3, 1) both;

    transition:
        transform .45s cubic-bezier(.16, 1, .3, 1),
        box-shadow .45s ease;
}

/* Inner luxury ring */
.sowkar-hc-product-badge::before {
    content: "";
    position: absolute;
    inset: 7px;

    border: 1px dashed rgba(255, 255, 255, .58);
    border-radius: 50%;

    opacity: .9;
    animation: sowkarBadgeRing 12s linear infinite;
}

/* Moving light sweep */
.sowkar-hc-product-badge::after {
    content: "";
    position: absolute;
    top: -35%;
    left: -75%;

    width: 45%;
    height: 170%;

    background: linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, .34),
            transparent);

    transform: rotate(24deg);
    animation: sowkarBadgeShine 4.5s ease-in-out infinite;
    pointer-events: none;
}

.sowkar-hc-product-badge:hover {
    transform: translateZ(0) rotate(0deg) scale(1.08);
    box-shadow:
        0 24px 55px rgba(0, 0, 0, .38),
        0 0 0 8px rgba(255, 255, 255, .07),
        0 0 34px rgba(201, 75, 92, .24);
}

@keyframes sowkarBadgeFloat {

    0%,
    100% {
        margin-top: 0;
    }

    50% {
        margin-top: -8px;
    }
}

@keyframes sowkarBadgeEnter {
    from {
        opacity: 0;
        transform: translate3d(24px, -12px, 0) rotate(18deg) scale(.72);
    }

    to {
        opacity: 1;
        transform: translateZ(0) rotate(-7deg) scale(1);
    }
}

@keyframes sowkarBadgeRing {
    to {
        transform: rotate(360deg);
    }
}

@keyframes sowkarBadgeShine {

    0%,
    52% {
        left: -75%;
    }

    78%,
    100% {
        left: 145%;
    }
}


/* =========================================================
   DESCRIPTION — ALWAYS READABLE
   ========================================================= */

.sowkar-hc-description {
    position: relative;
    z-index: 3;

    max-width: 560px;
    padding: 15px 18px;

