.sowkar-about-btn:hover::before {

    transform:
        translateX(0);

}


.sowkar-about-btn:hover i {

    transform:
        rotate(45deg);

}


/* =========================================================
   RIGHT VISUAL
========================================================= */

.sowkar-about-visual {

    position: relative;

    min-height: 720px;

    height: 100%;

}


/* =========================================================
   SOFT ORBIT
========================================================= */

.sowkar-about-orbit {

    position: absolute;

    z-index: 1;

    top: 80px;

    right: 4%;

    width: 530px;

    height: 530px;

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(201, 139, 194, .20),
            rgba(201, 139, 194, .07) 48%,
            transparent 70%);

}


/* =========================================================
   MAIN IMAGE
========================================================= */

.sowkar-about-image {

    position: absolute;

    z-index: 4;

    top: 65px;

    right: 10%;

    width: 67%;

    height: 570px;

    overflow: hidden;

    border-radius:
        170px 20px 20px 20px;

    box-shadow:
        0 30px 65px rgba(22, 11, 32, .18);

}


.sowkar-about-image::after {

    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(180deg,
            transparent 65%,
            rgba(22, 11, 32, .16));

}


.sowkar-about-image img {

    width: 100%;

    height: 100%;

    display: block;

    object-fit: cover;

    transition:
        transform 1s cubic-bezier(.16, 1, .3, 1);

}


.sowkar-about-image:hover img {

    transform:
        scale(1.035);

}


/* =========================================================
   SMALL IMAGE
========================================================= */

.sowkar-about-mini-image {

    position: absolute;

    z-index: 7;

    left: 3%;

    bottom: 70px;

    width: 185px;

    height: 225px;

    overflow: hidden;

    border:
        9px solid #fff;

    border-radius:
        8px;

    box-shadow:
        0 22px 45px rgba(22, 11, 32, .18);

}


.sowkar-about-mini-image img {

    width: 100%;

    height: 100%;

    display: block;

    object-fit: cover;

}


/* =========================================================
   FLOATING LABEL
========================================================= */

.sowkar-about-label {

    position: absolute;

    z-index: 10;

    right: 2%;

    bottom: 38px;

    width: 210px;

    min-height: 120px;

    padding:
        22px 23px;

    background:
        #fff;

    box-shadow:
        0 20px 45px rgba(22, 11, 32, .15);

    border-radius:
        6px;

}


.sowkar-label-small {

    display: block;

    margin-bottom: 6px;

    font-family: "Montserrat", sans-serif;

    font-size: 8px;

    font-weight: 700;

    letter-spacing: 2.5px;

    color:
        var(--sowkar-red);

}


.sowkar-about-label strong {

    display: block;

    max-width: 130px;

    font-family: "Montserrat", sans-serif;

    font-size: 17px;

    line-height: 1.1;

    color:
        var(--sowkar-deep);

}


.sowkar-label-arrow {

    position: absolute;

    right: 17px;

    bottom: 17px;

    width: 34px;

    height: 34px;

    display: flex;

    align-items: center;

    justify-content: center;

    color: #fff;

    background:
        var(--sowkar-red);

    border-radius: 50%;

}


/* =========================================================
   VERTICAL SIDE TEXT
========================================================= */

.sowkar-about-side-text {

    position: absolute;

    z-index: 8;

    top: 270px;

    right: -6px;

    writing-mode: vertical-rl;

    transform:
        rotate(180deg);

    font-family: "Montserrat", sans-serif;

    font-size: 8px;

    font-weight: 700;

    letter-spacing: 4px;

    color:
        rgba(118, 45, 112, .50);

}


/* =========================================================
   DOT GRID
========================================================= */

.sowkar-about-dots {

    position: absolute;

    z-index: 8;

    top: 105px;

    left: 2%;

    display: grid;

    grid-template-columns:
        repeat(3, 5px);

    gap: 10px 12px;

}


.sowkar-about-dots span {

    width: 5px;

    height: 5px;

    border-radius: 50%;

    background:
        var(--sowkar-red);

    opacity: .65;

}


/* =========================================================
   ANIMATIONS
========================================================= */

.sowkar-about-content {

    animation:
        sowkarAboutContentIn .9s cubic-bezier(.16, 1, .3, 1) both;

}


.sowkar-about-visual {

    animation:
        sowkarAboutVisualIn 1s cubic-bezier(.16, 1, .3, 1) .1s both;

}


@keyframes sowkarAboutContentIn {

    from {

        opacity: 0;

        transform:
            translateX(-35px);

    }

    to {

        opacity: 1;

        transform:
            translateX(0);

    }

}


@keyframes sowkarAboutVisualIn {

    from {

        opacity: 0;

        transform:
            translateX(35px);

    }

    to {

        opacity: 1;

        transform:
            translateX(0);

    }

}


