/* =========================================================
   PRODUCTS SECTION
   ========================================================= */

.sowkar-products-section {
    position: relative;
    width: 100%;
    overflow: hidden;

    padding: 90px 0 70px;

    background: var(--sowkar-deep);
}


/* =========================================================
   PRODUCTS BACKGROUND
   ========================================================= */

.sowkar-products-bg {
    position: absolute;
    inset: 0;

    width: 100%;
    height: 100%;

    background-image:
        url("../images/sowkar-textiles-products-bg1.jpg");



    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    z-index: 0;
}


/* =========================================================
   CONTAINER
   ========================================================= */

.sowkar-products-section .container {
    position: relative;
    z-index: 2;
}


/* =========================================================
   HEADING
   ========================================================= */

.sowkar-products-heading {
    text-align: center;
    margin-bottom: 40px;
}


.sowkar-products-eyebrow {
    display: block;

    margin-bottom: 13px;

    font-family: "Montserrat", sans-serif;

    font-size: 12px;
    line-height: 1;

    font-weight: 600;
    letter-spacing: 4px;

    text-transform: uppercase;

    color: var(--sowkar-gold);
}


/* =========================================================
   HEADING MARK
   ========================================================= */

.sowkar-products-heading-mark {
    display: flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    margin-bottom: 17px;
}


.sowkar-products-heading-mark span {
    display: block;

    width: 26px;
    height: 1px;

    background: rgba(220, 166, 106, 0.65);
}


.sowkar-products-heading-mark i {
    display: block;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: var(--sowkar-gold);
}


/* =========================================================
   MAIN HEADING
   ========================================================= */

.sowkar-products-heading h2 {
    margin: 0;

    font-family: "Montserrat", sans-serif;

    font-size: clamp(38px, 5vw, 64px);

    line-height: 0.98;

    font-weight: 300;

    letter-spacing: -2px;

    text-transform: uppercase;

    color: #ffffff;
}


/* =========================================================
   HEADING SECOND LINE
   ========================================================= */

.sowkar-products-heading h2 span {
    display: block;

    margin-top: 6px;

    font-family: "Montserrat", sans-serif;

    font-weight: 500;

    color: var(--sowkar-gold-light);

    background: none;

    -webkit-background-clip: initial;
    background-clip: initial;

    -webkit-text-fill-color: var(--sowkar-gold-light);
}


/* =========================================================
   HEADING DESCRIPTION
   ========================================================= */

.sowkar-products-heading p {
    margin: 18px 0 0;

    font-family: "Montserrat", sans-serif;

    font-size: 13px;

    line-height: 1.6;

    font-weight: 400;

    letter-spacing: 0.3px;

    color: rgba(255, 255, 255, 0.68);
}


/* =========================================================
   PRODUCT GRID
   ========================================================= */

.sowkar-products-grid {
    --bs-gutter-x: 0px;
    --bs-gutter-y: 0px;

    margin-left: 0;
    margin-right: 0;
    row-gap: 15px;
}


/* =========================================================
   PRODUCT COLUMN
   ========================================================= */

.sowkar-product-col {
    display: flex;

    justify-content: center;

    padding-left: 0;
    padding-right: 0;
}


/* =========================================================
   COMPLETE PRODUCT CARD
   ========================================================= */

.sowkar-product-card {
    position: relative;

    display: block;

    width: 100%;
    max-width: none;

    text-decoration: none;

    /*
       GOLD IS THE CARD BORDER.

       The entire image + title is clipped
       together as ONE continuous shape.
    */

    background: var(--sowkar-gold);

    padding: 1px;

    clip-path: polygon(7% 0,
            100% 0,
            93% 100%,
            0 100%);

    transition:
        transform 0.35s ease;
}


/* =========================================================
   PRODUCT CARD INNER AREA
   ========================================================= */

.sowkar-product-card>* {
    position: relative;
}


/* =========================================================
   PRODUCT IMAGE
   ========================================================= */

.sowkar-product-image {
    position: relative;

    width: 100%;
    /* height: 255px; */

    overflow: hidden;

    background: var(--sowkar-deep-2);

    /*
       NO CLIP-PATH
       NO OVERLAY
       NO BORDER

       Parent card controls the complete shape.
    */

    z-index: 2;
}


/* =========================================================
   PRODUCT IMAGE
   ========================================================= */

.sowkar-product-image img {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    object-position: center;

    transform: scale(1.01);

    transition:
        transform 0.8s cubic-bezier(0.22,
            1,
            0.36,
            1);
}


/* =========================================================
   REMOVE ALL IMAGE OVERLAYS / BORDERS
   ========================================================= */

.sowkar-product-image::before {
    display: none !important;

    content: none;
}


.sowkar-product-image::after {
    display: none !important;

    content: none;
}


/* =========================================================
   PRODUCT TITLE
   ========================================================= */

.sowkar-product-title {
    position: relative;

    width: 100%;
    height: 57px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 10px;
    padding: 0 8%;
    margin: 0;

    background: linear-gradient(90deg,
            rgba(30, 12, 40, 1),
            rgba(54, 19, 64, 1),
            rgba(118, 45, 112, 1),
            rgba(54, 19, 64, 1),
            rgba(30, 12, 40, 1));

    background-size: 250% 100%;
    background-position: 0% 50%;

    z-index: 5;

    border-top: 2px solid #C94B5C;
}


/* =========================================================
   TITLE TEXT
   ========================================================= */

.sowkar-product-title span {
    position: relative;

    z-index: 5;

    display: block;

    font-family: "Montserrat", sans-serif;

    font-size: 12px;

    line-height: 1.25;

    font-weight: 600;

    letter-spacing: 0.3px;

    text-transform: uppercase;

    color: #ffffff;

    white-space: nowrap;
}


/* =========================================================
   ARROW
   ========================================================= */

.sowkar-product-title i {
    position: relative;

    z-index: 5;

    width: 32px;
    height: 32px;

    min-width: 32px;

    display: flex;

    align-items: center;
    justify-content: center;

    border: 1px solid var(--sowkar-gold);

    border-radius: 50%;

    color: var(--sowkar-gold);

    font-size: 12px;

    line-height: 1;

    transition:
        transform 0.35s ease,
        background 0.35s ease,
        color 0.35s ease;
}


