/* =========================================
   SOWKAR HIGHLIGHT SECTION
========================================= */

.sowkar-highlight {
    position: relative;
    overflow: hidden;

    padding-top: 85px;

    background: #F8F4EE;
}


/* =========================================
   HEADING
========================================= */

.sowkar-highlight-label {
    display: inline-block;

    margin-bottom: 18px;

    font-family: "Montserrat", sans-serif;
    font-size: 12px;
    font-weight: 600;

    letter-spacing: 5px;

    color: var(--sowkar-red-dark);
}


.sowkar-highlight-heading {
    margin: 0;

    font-family: "Montserrat", sans-serif;
    font-size: clamp(38px, 4.5vw, 64px);
    font-weight: 400;

    line-height: 1.08;

    letter-spacing: -1px;

    color: #2D1238;
}


.sowkar-highlight-heading span {
    display: block;

    margin-top: 3px;

    color: var(--sowkar-red);
}


/* =========================================
   HEADING DIVIDER
========================================= */

.sowkar-highlight-divider {
    display: flex;

    align-items: center;
    justify-content: center;

    gap: 10px;

    margin-top: 24px;
    margin-bottom: 48px;
}


.sowkar-highlight-divider span {
    width: 55px;
    height: 1px;

    background: var(--sowkar-red);
}


.sowkar-highlight-divider i {
    width: 7px;
    height: 7px;

    display: block;

    background: var(--sowkar-red);

    transform: rotate(45deg);
}


/* =========================================
   HIGHLIGHT ITEMS
========================================= */

.sowkar-highlight-items {
    border-top: 1px solid rgba(201, 75, 92, 0.25);
}


.sowkar-highlight-item {
    position: relative;

    min-height: 255px;

    padding: 35px 35px 30px;

    text-align: center;
}


/* vertical separators */

.sowkar-highlight-item::after {
    content: "";

    position: absolute;

    top: 28px;
    right: 0;

    width: 1px;
    height: 190px;

    background: rgba(45, 18, 56, 0.12);
}


.sowkar-highlight-item:last-child::after {
    display: none;
}


/* =========================================
   ICON
========================================= */

.sowkar-highlight-icon {
    width: 78px;
    height: 78px;

    margin: 0 auto 20px;

    display: flex;

    align-items: center;
    justify-content: center;

    border: 1.5px solid #2D1238;

    border-radius: 50%;

    color: #2D1238;

    font-size: 31px;

    transition:
        background 0.35s ease,
        color 0.35s ease,
        transform 0.35s ease;
}


.sowkar-highlight-item:hover .sowkar-highlight-icon {
    background: #2D1238;

    color: var(--sowkar-red);

    transform: translateY(-5px);
}


/* =========================================
   TITLE
========================================= */

.sowkar-highlight-item h3 {
    margin: 0;

    font-family: "Montserrat", sans-serif;

    font-size: 17px;
    font-weight: 600;

    letter-spacing: 1px;

    color: #2D1238;
}


/* =========================================
   SMALL GOLD LINE
========================================= */

.sowkar-item-line {
    width: 36px;
    height: 3px;

    margin: 13px auto 17px;

    background: var(--sowkar-red);
}


/* =========================================
   DESCRIPTION
========================================= */

.sowkar-highlight-item p {
    max-width: 250px;

    margin: 0 auto;

    font-family: "Montserrat", sans-serif;

    font-size: 13px;

    line-height: 1.7;

    color: #514A54;
}


/* =========================================
   FABRIC IMAGE
========================================= */

.sowkar-highlight-fabric {
    position: relative;

    width: 100%;

    height: 310px;

    margin-top: 20px;

    overflow: hidden;

    border-top: 3px solid var(--sowkar-red-dark);
    border-bottom: 3px solid var(--sowkar-red-dark);
}


.sowkar-highlight-fabric img {
    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center;

    transition: transform 1.2s ease;
}


.sowkar-highlight-fabric:hover img {
    transform: scale(1.03);
}


/* =========================================
   BOTTOM STATEMENT
========================================= */

.sowkar-highlight-bottom {
    min-height: 75px;

    display: flex;

    align-items: center;
    justify-content: center;

    gap: 20px;
}


.sowkar-highlight-bottom span {
    width: 170px;
    height: 1px;

    background: var(--sowkar-purple-dark);
}


.sowkar-highlight-bottom i {
    font-size: 8px;

    color: var(--sowkar-purple-dark);

    transform: rotate(45deg);
}


.sowkar-highlight-bottom p {
    margin: 0;

    font-family: "Montserrat", sans-serif;

    font-size: 13px;
    font-weight: 500;

    letter-spacing: 3px;

    color: var(--sowkar-red);

    white-space: nowrap;
}


/* =========================================
   TABLET
========================================= */

@media (max-width: 991.98px) {

    .sowkar-highlight {
        padding-top: 70px;
    }

    .sowkar-highlight-heading {
        font-size: 45px;
    }

    .sowkar-highlight-item {
        min-height: 240px;

        padding: 30px 20px;
    }

    .sowkar-highlight-item::after {
        height: 175px;
    }

    .sowkar-highlight-fabric {
        height: 270px;
    }

    .sowkar-highlight-bottom span {
        width: 90px;
    }

}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 575.98px) {

    .sowkar-highlight {
        padding-top: 55px;
    }

    .sowkar-highlight-label {
        font-size: 10px;
        letter-spacing: 3px;
    }

    .sowkar-highlight-heading {
        font-size: 32px;
        letter-spacing: -0.5px;
    }

    .sowkar-highlight-divider {
        margin-bottom: 25px;
    }

    .sowkar-highlight-divider span {
        width: 35px;
    }


    .sowkar-highlight-item {
        min-height: 225px;

        padding: 25px 12px;
    }


    .sowkar-highlight-item::after {
        top: 25px;

        height: 170px;
    }


    /* remove separator from right side
       of even mobile items */

    .sowkar-highlight-item:nth-child(2)::after {
        display: none;
    }

    .sowkar-highlight-item:nth-child(3)::after {
        display: block;
    }

    .sowkar-highlight-icon {
        width: 62px;
        height: 62px;

        margin-bottom: 15px;

        font-size: 24px;
    }


    .sowkar-highlight-item h3 {
        font-size: 12px;
        letter-spacing: 0.5px;
    }


    .sowkar-highlight-item p {
        font-size: 10px;

        line-height: 1.6;
    }


    .sowkar-item-line {
        width: 28px;

        margin: 10px auto 12px;
    }


    .sowkar-highlight-fabric {
        height: 190px;

        margin-top: 10px;
    }


    .sowkar-highlight-bottom {
        gap: 10px;

        min-height: 65px;
    }


    .sowkar-highlight-bottom span {
        width: 25px;
    }


    .sowkar-highlight-bottom p {
        font-size: 8px;

        letter-spacing: 1.5px;

        text-align: center;
    }

}




/* =========================================
   SOWKAR HEALTHCARE SECTION
========================================= */

.sowkar-healthcare {
    position: relative;

