    overflow: hidden;

    background:
        radial-gradient(circle at 8% 15%,
            rgba(155, 63, 143, 0.16),
            transparent 30%),
        radial-gradient(circle at 92% 85%,
            rgba(201, 75, 92, 0.10),
            transparent 28%),
        #FBF8F5;
}


/* =========================
   TOP DECORATIVE SHAPE
========================= */

.sowkar-clients::before {
    content: "";

    position: absolute;

    width: 420px;
    height: 420px;

    top: -250px;
    right: -170px;

    border: 1px solid rgba(155, 63, 143, 0.10);

    transform: rotate(45deg);

    pointer-events: none;
}


/* =========================
   HEADING
========================= */

.sowkar-clients-heading {
    max-width: 850px;
    margin: 0 auto 60px;

    text-align: center;
}

.sowkar-clients-kicker {
    display: inline-block;

    margin-bottom: 16px;

    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 5px;

    color: var(--sowkar-red);
}

.sowkar-clients-heading h2 {
    margin: 0;

    font-family: "Montserrat", sans-serif;
    font-size: clamp(38px, 5vw, 65px);
    font-weight: 400;
    line-height: 1.05;
    letter-spacing: -1.5px;

    color: var(--sowkar-navy);
}

.sowkar-clients-heading h2 span {
    display: block;

    color: var(--sowkar-red);
}

.sowkar-clients-heading p {
    max-width: 620px;

    margin: 22px auto 0;

    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    line-height: 1.8;

    color: #665B69;
}


/* =========================
   CAROUSEL WRAPPER
========================= */

.sowkar-clients-slider-wrap {
    position: relative;

    max-width: 1250px;
    margin: 0 auto;
}


/* Owl outer */

.sowkar-clients-carousel .owl-stage-outer {
    overflow: visible !important;

    padding: 20px 0 25px;
    margin: -20px 0 -25px;
}


/* Stage */

.sowkar-clients-carousel .owl-stage {
    display: flex;
    align-items: center;
}


/* Items */

.sowkar-clients-carousel .owl-item {
    display: flex;

    padding: 0 8px;
}


/* =========================
   CLIENT LOGO AREA
========================= */

.sowkar-client-item {
    position: relative;

    width: 100%;
    height: 145px;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 25px 25px;

    background: rgba(255, 255, 255, 0.90);

    border: 1px solid rgba(53, 18, 79, 0.08);

    box-shadow:
        0 8px 28px rgba(53, 18, 79, 0.06);

    transition:
        transform 0.4s ease,
        box-shadow 0.4s ease,
        border-color 0.4s ease,
        background 0.4s ease;
}


/* Small red edge */

.sowkar-client-item::before {
    content: "";

    position: absolute;

    top: 0;
    left: 0;

    width: 0;
    height: 3px;

    background: var(--sowkar-red);

    transition: width 0.4s ease;
}


/* Logo */

.sowkar-client-item img {
    display: block;

    width: auto;
    max-width: 88%;
    height: auto;
    max-height: 70px;

    object-fit: contain;

    transition:
        transform 0.4s ease,
        opacity 0.4s ease;
}


/* Hover */

.sowkar-client-item:hover {
    background: #ffffff;

    border-color: rgba(155, 63, 143, 0.25);

    transform: translateY(-6px);

    box-shadow:
        0 18px 40px rgba(53, 18, 79, 0.13);
}

.sowkar-client-item:hover::before {
    width: 45px;
}

.sowkar-client-item:hover img {
    transform: scale(1.06);
}


/* =========================
   CONTROLS
========================= */

.sowkar-clients-controls {
    display: flex;

    align-items: center;
    justify-content: center;

    gap: 15px;

    margin-top: 28px;
}

.sowkar-client-prev,
.sowkar-client-next {
    width: 44px;
    height: 44px;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 0;

    border: 1px solid var(--sowkar-purple);
    border-radius: 50%;

    background: transparent;

    color: var(--sowkar-purple);

    font-size: 17px;

    cursor: pointer;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        transform 0.3s ease;
}

.sowkar-client-prev:hover,
.sowkar-client-next:hover {
    background: var(--sowkar-purple);

    color: #ffffff;

    transform: translateY(-2px);
}


.sowkar-client-line {
    width: 55px;
    height: 1px;

    background: var(--sowkar-red);
}


/* Hide Owl default navigation */

.sowkar-clients-carousel .owl-nav,
.sowkar-clients-carousel .owl-dots {
    display: none;
}


/* =========================
   LARGE DESKTOP
========================= */

@media (min-width: 1400px) {

    .sowkar-clients {
        padding: 125px 0 120px;
    }

    .sowkar-client-item {
        height: 155px;
    }

    .sowkar-client-item img {
        max-height: 75px;
    }

}


/* =========================
