    }

}


/* =========================
   MOBILE
========================= */

@media (max-width: 575.98px) {

    .sowkar-clients {
        padding: 70px 0 75px;
    }

    .sowkar-clients-heading {
        margin-bottom: 35px;
    }

    .sowkar-clients-kicker {
        font-size: 9px;
        letter-spacing: 3px;
    }

    .sowkar-clients-heading h2 {
        font-size: 34px;
        letter-spacing: -0.5px;
    }

    .sowkar-clients-heading p {
