    top: 50%;

    left: -65px;
    right: -65px;

    transform: translateY(-50%);

    display: flex;

    justify-content: space-between;

    pointer-events: none;

    margin: 0;

}


.sowkar-testimonial-carousel .owl-nav button.owl-prev,
.sowkar-testimonial-carousel .owl-nav button.owl-next {

    width: 56px;
    height: 56px;

    display: flex;

    align-items: center;
    justify-content: center;

    margin: 0;

    border: 2px solid var(--sowkar-purple) !important;

    border-radius: 50%;

    background: #ffffff !important;

    color: var(--sowkar-purple) !important;

    font-size: 30px !important;

    line-height: 1;

    pointer-events: auto;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        transform 0.3s ease;

}


.sowkar-testimonial-carousel .owl-nav button:hover {

    background: var(--sowkar-purple) !important;

    color: #ffffff !important;

    transform: scale(1.05);

}


