   OWL DOTS
========================================================= */

.sowkar-testimonial-carousel .owl-dots {

    position: relative;

    z-index: 100;

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 0px;

    margin-top: 12px;

    pointer-events: auto;
}


.sowkar-testimonial-carousel .owl-dots .owl-dot {

    position: relative;

    display: flex;
    align-items: center;
    justify-content: center;

    width: 28px;
    height: 28px;

    margin: 0;
    padding: 0;

    border: 0;
    background: transparent !important;

    cursor: pointer;

    pointer-events: auto;

    z-index: 101;
}


.sowkar-testimonial-carousel .owl-dots .owl-dot span {

    display: block;

    width: 9px;
    height: 9px;

    margin: 0;

    border-radius: 50%;

    background: #D5BFCB;

    pointer-events: none;

    transition:
        width 0.3s ease,
        background 0.3s ease;
}


.sowkar-testimonial-carousel .owl-dots .owl-dot.active span {

    width: 28px;

    border-radius: 20px;

    background: var(--sowkar-red);
}


