.sowkar-testimonial-carousel .owl-dots .owl-dot:hover span {

    background: var(--sowkar-red);
}


/* =========================================================
   BOTTOM CURVED DESIGN
========================================================= */

.sowkar-wave-bottom {

    position: absolute;

    left: -5%;
    bottom: -1px;

    width: 110%;

    height: 145px;

    background: var(--sowkar-purple-dark);

    clip-path:
        polygon(0 45%,
            10% 63%,
            22% 73%,
            35% 82%,
            49% 88%,
            63% 91%,
            76% 88%,
            88% 78%,
            100% 55%,
            100% 100%,
            0 100%);

    z-index: 1;

}


/* Red wave */

.sowkar-wave-bottom::before {

    content: "";

    position: absolute;

    left: 0;

    bottom: 0;

    width: 100%;

    height: 95px;

    background: var(--sowkar-red);

    clip-path:
        polygon(38% 30%,
            52% 40%,
            65% 43%,
            78% 38%,
            90% 25%,
            100% 8%,
            100% 100%,
            38% 100%);

}


/* White separator */

.sowkar-wave-bottom::after {

    content: "";

    position: absolute;

    left: 0;

    top: 53px;

    width: 100%;

    height: 3px;

    background: rgba(255, 255, 255, 0.95);

    transform: rotate(-1deg);

}


