/* =========================================================
   SOWKAR CTA SECTION
   ========================================================= */

.sowkar-cta {
    position: relative;
    padding: 105px 0 110px;
    background: #fbf8f5;
    overflow: hidden;
}

/* Subtle soft background */
.sowkar-cta::before {
    content: "";
    position: absolute;
    width: 520px;
    height: 520px;
    left: -260px;
    top: -260px;
    border-radius: 50%;
    background: rgba(155, 63, 143, 0.035);
    pointer-events: none;
}

.sowkar-cta::after {
    content: "";
    position: absolute;
    width: 430px;
    height: 430px;
    right: -220px;
    bottom: -250px;
    border-radius: 50%;
    background: rgba(201, 75, 92, 0.025);
    pointer-events: none;
}


/* Main content */
.sowkar-cta-content {
    position: relative;
    z-index: 2;
}


/* Small Label */
.sowkar-cta-label {
    display: inline-block;
    margin-bottom: 17px;

    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 6px;
    line-height: 1.4;

    color: #35124f;
}


/* Small Red Line */
.sowkar-cta-line {
    width: 108px;
    height: 4px;
    margin: 0 auto 36px;

