/* =========================================
   SOWKAR WHATSAPP BUTTON
========================================= */

.sowkar-whatsapp {
    position: fixed;

    right: 25px;
    bottom: 25px;

    width: 58px;
    height: 58px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #25D366;
    color: #ffffff;

    border-radius: 50%;

    font-size: 30px;
    text-decoration: none;

    z-index: 9999;

    box-shadow:
        0 8px 25px rgba(0, 0, 0, 0.20);

    animation:
        sowkarWhatsappFloat 3s ease-in-out infinite;

    transition:
        transform 0.3s ease,
        box-shadow 0.3s ease;
}


/* =========================================
   OUTER PULSE
========================================= */

.sowkar-whatsapp::before {
    content: "";

    position: absolute;

    inset: -4px;

    border-radius: 50%;

    border: 2px solid rgba(37, 211, 102, 0.55);

    animation:
        sowkarWhatsappPulse 2.2s ease-out infinite;

    pointer-events: none;
}


/* =========================================
   ICON
========================================= */

.sowkar-whatsapp i {
    position: relative;
    z-index: 2;

    line-height: 1;

    transition:
        transform 0.3s ease;
}


/* =========================================
   HOVER
========================================= */

.sowkar-whatsapp:hover {
    color: #ffffff;

    transform: scale(1.08);

    box-shadow:
        0 12px 32px rgba(0, 0, 0, 0.28);
}

.sowkar-whatsapp:hover i {
    transform: rotate(-8deg) scale(1.08);
}


/* =========================================
   FLOATING EFFECT
========================================= */

@keyframes sowkarWhatsappFloat {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-5px);
    }

}


/* =========================================
   PULSE EFFECT
========================================= */

@keyframes sowkarWhatsappPulse {

    0% {
        transform: scale(0.95);
        opacity: 0.75;
    }

    70% {
        transform: scale(1.35);
        opacity: 0;
    }

    100% {
        transform: scale(1.35);
        opacity: 0;
    }

}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 575.98px) {

    .sowkar-whatsapp {
        width: 52px;
        height: 52px;

        right: 18px;
        bottom: 18px;

        font-size: 27px;
    }

}


