/* =========================================================
   ABOUT US PAGE — BESPOKE SECTION STYLES
   (Hero, Who We Are, Leadership/Founders, Vision & Mission, Suppliers)
   Scoped to About Us sections to avoid affecting any other pages.
========================================================= */

/* =========================================================
   HERO CONTAINER (At most 75vh)
========================================================= */
.sowkar-about-hero {
    position: relative;
    width: 100%;
    height: clamp(520px, 75vh, 660px);
    min-height: 520px;
    max-height: 75vh;
    padding: 30px 0;
    display: flex;
    align-items: center;
    overflow: hidden;
    isolation: isolate;
    /* Atmospheric background synchronized with index.html hero */
    background:
        radial-gradient(circle at 78% 38%, rgba(155, 63, 143, 0.24), transparent 38%),
        radial-gradient(circle at 88% 15%, rgba(201, 75, 92, 0.18), transparent 28%),
        radial-gradient(circle at 14% 82%, rgba(104, 26, 102, 0.26), transparent 34%),
        linear-gradient(125deg, #0e0714 0%, #1b0c23 48%, #25102d 100%);
}

/* Subtle woven grid overlay */
.sowkar-about-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(to right, rgba(234, 220, 240, 0.035) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(234, 220, 240, 0.035) 1px, transparent 1px);
    background-size: 44px 44px;
    mask-image: radial-gradient(ellipse at 65% 50%, black 35%, transparent 80%);
    -webkit-mask-image: radial-gradient(ellipse at 65% 50%, black 35%, transparent 80%);
    pointer-events: none;
    z-index: 1;
}

/* Ambient floating light aura */
.sowkar-about-hero::after {
    content: "";
    position: absolute;
    top: -15%;
    right: 28%;
    width: 520px;
    height: 520px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.14) 0%, rgba(155, 63, 143, 0.06) 45%, transparent 70%);
    filter: blur(45px);
    pointer-events: none;
    z-index: 1;
    animation: sauAmbientShift 12s ease-in-out infinite alternate;
}

@keyframes sauAmbientShift {
    0% {
        transform: scale(1) translate(0, 0);
        opacity: 0.65;
    }

    100% {
        transform: scale(1.18) translate(-35px, 25px);
        opacity: 1;
    }
}

.sowkar-about-hero .container {
    position: relative;
    z-index: 10;
}

/* =========================================================
   LEFT CONTENT
========================================================= */
.sau-hero-left {
    display: flex;
    flex-direction: column;
    justify-content: center;
    max-width: 620px;
}

/* BREADCRUMB */
.sau-hero-breadcrumb {
    margin-bottom: 14px;
    opacity: 0;
    animation: sauHeroFadeDown 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.15s forwards;
}

.sau-crumb-list {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 5px 14px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 30px;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    list-style: none;
    margin: 0;
}

.sau-crumb-item {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2.2px;
    text-transform: uppercase;
}

.sau-crumb-item a {
    color: rgba(255, 255, 255, 0.75);
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    transition: color 0.3s ease;
}

.sau-crumb-item a:hover {
    color: #E77A88;
}

.sau-crumb-sep {
    color: rgba(201, 75, 92, 0.6);
    font-size: 11px;
}

.sau-crumb-item.active {
    color: #E77A88;
    font-weight: 700;
}

/* LABEL: ABOUT SOWKAR */
.sau-hero-label {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    opacity: 0;
    animation: sauHeroFadeDown 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.3s forwards;
}

.sau-label-pill {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #C94B5C;
    box-shadow: 0 0 10px #C94B5C;
    animation: sauDotGlow 2s infinite ease-in-out;
}

@keyframes sauDotGlow {

    0%,
    100% {
        transform: scale(1);
        opacity: 0.8;
        box-shadow: 0 0 6px #C94B5C;
    }

    50% {
        transform: scale(1.3);
        opacity: 1;
        box-shadow: 0 0 14px #E77A88;
    }
}

.sau-label-text {
    font-family: "Montserrat", sans-serif;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 3.2px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.70);
}

.sau-label-line {
    width: 45px;
    height: 1px;
    background: linear-gradient(90deg, #C94B5C, #C98BC2);
}

/* HEADING */
.sau-hero-heading {
    margin: 0 0 6px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(54px, 4.9vw, 82px);
    font-weight: 900;
    line-height: .91;
    letter-spacing: -3px;
    text-transform: uppercase;
    color: #FFFFFF;
}

.sau-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 3px;
}

.sau-heading-line>span {
    display: inline-block;
    transform: translateY(110%);
    animation: sauHeroTextReveal 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.sau-heading-line:nth-child(1)>span {
    animation-delay: 0.4s;
}

.sau-heading-line:nth-child(2)>span {
    animation-delay: 0.55s;
}

.sau-text-gradient {
    color: #C98BC2;
    background: linear-gradient(135deg, #FFFFFF 20%, #C98BC2 60%, #E77A88 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.sau-text-highlight {
    color: #E77A88;
    font-family: "Playfair Display", serif;
    font-style: italic;
    font-weight: 600;
    text-transform: capitalize;
    letter-spacing: -1px;
    -webkit-text-fill-color: initial;
}

/* TAGLINE */
.sau-hero-tagline {
    margin-top: 8px;
    font-family: "Montserrat", sans-serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.85);
    opacity: 0;
    animation: sauHeroFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.72s forwards;
}

.sau-hero-tagline span {
    color: #E77A88;
}

/* ACCENT LINE */
.sau-hero-accent-line {
    width: 78px;
    height: 2px;
    margin: 12px 0 14px;
    background: linear-gradient(90deg, #C94B5C, #C98BC2);
    transform-origin: left;
    transform: scaleX(0);
    animation: sauHeroLineDraw 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.88s forwards;
}

/* SUB-COPY */
.sau-hero-subcopy {
    max-width: 500px;
    margin: 0 0 20px;
    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    font-weight: 400;
    line-height: 1.75;
    color: #C9B8D0;
    opacity: 0;
    animation: sauHeroFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.98s forwards;
}

/* ACTION BUTTONS */
.sau-hero-actions {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
    opacity: 0;
    animation: sauHeroFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) 1.12s forwards;
}

.sau-hero-btn-primary {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 12px 24px;
    background: linear-gradient(100deg, #9B3F8F, #C94B5C);
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 4px;
    color: #FFFFFF;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    text-decoration: none;
    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.3);
    transition: transform 0.35s ease, box-shadow 0.35s ease, background 0.35s ease;
    overflow: hidden;
}

.sau-hero-btn-primary::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, #C94B5C, #E77A88);
    opacity: 0;
    transition: opacity 0.4s ease;
    z-index: 1;
}

.sau-hero-btn-primary span,
.sau-hero-btn-primary i {
    position: relative;
    z-index: 2;
    transition: transform 0.3s ease;
}

.sau-hero-btn-primary:hover {
    color: #FFFFFF;
    transform: translateY(-2px);
    box-shadow: 0 18px 40px rgba(201, 75, 92, 0.4);
}

.sau-hero-btn-primary:hover::before {
    opacity: 1;
}

.sau-hero-btn-primary:hover i {
    transform: translate(3px, 3px);
}

.sau-hero-btn-glass {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 20px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 4px;
    color: #FFFFFF;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    text-decoration: none;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: background 0.3s ease, border-color 0.3s ease, transform 0.3s ease;
}

.sau-hero-btn-glass:hover {
    color: #FFFFFF;
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(201, 75, 92, 0.4);
    transform: translateY(-2px);
}

/* =========================================================
   RIGHT SCULPTURAL VISUAL (Unique Bespoke Shape)
========================================================= */
.sau-hero-visual-container {
    position: relative;
    width: 100%;
    height: 100%;
    max-height: 380px;
    display: flex;
    align-items: center;
    justify-content: center;
    perspective: 1000px;
}

/* Outer Geometric Glass Halo */
.sau-visual-halo {
    position: absolute;
    width: 82%;
    height: 86%;
    border-radius: 46px 115px 46px 115px;
    border: 1.5px solid rgba(216, 185, 226, 0.22);
    background: linear-gradient(135deg, rgba(155, 63, 143, 0.12), rgba(201, 75, 92, 0.08));
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    transform: rotate(-3deg);
    transition: transform 0.7s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.4s ease;
    pointer-events: none;
    z-index: 1;
}

.sau-hero-visual-container:hover .sau-visual-halo {
    transform: rotate(-5deg) scale(1.02);
    border-color: rgba(201, 75, 92, 0.45);
}

/* Main Sculptural Visual Frame */
.sau-visual-frame {
    position: relative;
    width: 78%;
    height: 82%;
    max-height: 550px;
    border-radius: 38px 105px 38px 105px;
    overflow: hidden;
    z-index: 2;
    box-shadow:
        0 25px 50px rgba(0, 0, 0, 0.45),
        0 0 0 1px rgba(255, 255, 255, 0.12);
    transform: rotate(2deg);
    transition: transform 0.7s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.7s ease;
    opacity: 0;
    animation: sauVisualReveal 1.2s cubic-bezier(0.16, 1, 0.3, 1) 0.3s forwards;
}

.sau-hero-visual-container:hover .sau-visual-frame {
    transform: rotate(0deg) scale(1.02);
    box-shadow:
        0 35px 70px rgba(0, 0, 0, 0.6),
        0 0 0 1px rgba(231, 122, 136, 0.35);
}

.sau-visual-frame img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transform: scale(1.08);
    transition: transform 1.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.sau-hero-visual-container:hover .sau-visual-frame img {
    transform: scale(1.02);
}

/* Glass Reflection Sheen Overlay */
.sau-visual-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(140deg, rgba(255, 255, 255, 0.12) 0%, transparent 45%, rgba(201, 75, 92, 0.25) 100%);
    pointer-events: none;
    z-index: 3;
}

/* Corner Architectural Accent Notch */
.sau-visual-notch {
    position: absolute;
    top: 16px;
    right: 22px;
    width: 28px;
    height: 28px;
    border-top: 2px solid rgba(255, 255, 255, 0.65);
    border-right: 2px solid rgba(255, 255, 255, 0.65);
    z-index: 4;
    pointer-events: none;
}

/* Floating Badge 1: Rotating Seal */
.sau-floating-seal {
    position: absolute;
    top: -4px;
    right: 4px;
    width: 94px;
    height: 94px;
    z-index: 5;
    opacity: 0;
    animation: sauBadgePop 1s cubic-bezier(0.34, 1.56, 0.64, 1) 0.9s forwards;
}

.sau-seal-svg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    animation: sauSealSpin 18s linear infinite;
}

.sau-hero-visual-container:hover .sau-seal-svg {
    animation-duration: 9s;
}

.sau-seal-svg text {
    font-family: "Montserrat", sans-serif;
    font-size: 8.5px;
    font-weight: 700;
    letter-spacing: 2.6px;
    fill: #FFFFFF;
    text-transform: uppercase;
}

.sau-seal-core {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: linear-gradient(135deg, #C94B5C, #9B3F8F);
    box-shadow: 0 0 20px rgba(201, 75, 92, 0.6);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #FFFFFF;
    font-size: 14px;
    transition: transform 0.4s ease;
}

.sau-floating-seal:hover .sau-seal-core {
    transform: translate(-50%, -50%) rotate(45deg) scale(1.1);
}

/* Floating Badge 2: Frosted Glass Metric Chip */
.sau-floating-chip {
    position: absolute;
    bottom: -4px;
    left: 6px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 14px;
    background: rgba(22, 11, 32, 0.88);
    border: 1px solid rgba(216, 185, 226, 0.28);
    border-radius: 12px;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    box-shadow: 0 16px 36px rgba(0, 0, 0, 0.45);
    z-index: 5;
    opacity: 0;
    animation: sauBadgePop 1s cubic-bezier(0.34, 1.56, 0.64, 1) 1.1s forwards;
    transition: transform 0.4s ease, border-color 0.4s ease;
}

.sau-floating-chip:hover {
    transform: translateY(-4px);
    border-color: rgba(201, 75, 92, 0.6);
}

.sau-chip-icon {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    background: rgba(201, 75, 92, 0.2);
    border: 1px solid rgba(201, 75, 92, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #E77A88;
    font-size: 15px;
}

.sau-chip-text strong {
    display: block;
    font-family: "Urbanist", sans-serif;
    font-size: 13px;
    font-weight: 800;
    letter-spacing: 0.5px;
    color: #FFFFFF;
}

.sau-chip-text small {
    display: block;
    font-family: "Montserrat", sans-serif;
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: #C9B8D0;
}

/* =========================================================
   KEYFRAME ANIMATIONS
========================================================= */
@keyframes sauHeroFadeDown {
    from {
        opacity: 0;
        transform: translateY(-16px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes sauHeroFadeUp {
    from {
        opacity: 0;
        transform: translateY(22px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes sauHeroTextReveal {
    to {
        transform: translateY(0);
    }
}

@keyframes sauHeroLineDraw {
    to {
        transform: scaleX(1);
    }
}

@keyframes sauVisualReveal {
    from {
        opacity: 0;
        transform: translateY(35px) scale(0.94) rotate(2deg);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1) rotate(2deg);
    }
}

@keyframes sauBadgePop {
    from {
        opacity: 0;
        transform: scale(0.4) rotate(-30deg);
    }

    to {
        opacity: 1;
        transform: scale(1) rotate(0deg);
    }
}

@keyframes sauSealSpin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

/* =========================================================
   RESPONSIVE ADAPTATION
========================================================= */
@media (max-width: 1199.98px) {
    .sau-hero-visual-container {
        max-height: 350px;
    }

    .sau-hero-heading {
        font-size: 46px;
    }
}

@media (max-width: 991.98px) {
    .sowkar-about-hero {
        height: auto;
        min-height: auto;
        max-height: none;
        padding: 55px 0 65px;
    }

    .sau-hero-left {
        max-width: 100%;
        text-align: center;
        align-items: center;
        margin-bottom: 40px;
    }

    .sau-hero-accent-line {
        margin: 12px auto 14px;
    }

    .sau-hero-actions {
        justify-content: center;
    }

    .sau-hero-visual-container {
        max-width: 380px;
        height: 320px;
        margin: 0 auto;
    }
}

@media (max-width: 575.98px) {
    .sowkar-about-hero {
        padding: 40px 0 50px;
    }

    .sau-hero-heading {
        font-size: 32px;
        letter-spacing: -1px;
    }

    .sau-hero-actions {
        flex-direction: column;
        width: 100%;
    }

    .sau-hero-btn-primary,
    .sau-hero-btn-glass {
        width: 100%;
        justify-content: center;
    }

    .sau-hero-visual-container {
        height: 270px;
    }

    .sau-visual-frame {
        border-radius: 28px 65px 28px 65px;
    }

    .sau-visual-halo {
        border-radius: 32px 75px 32px 75px;
    }

    .sau-floating-seal {
        width: 76px;
        height: 76px;
        top: -6px;
        right: 0;
    }

    .sau-seal-core {
        width: 32px;
        height: 32px;
        font-size: 11px;
    }

    .sau-floating-chip {
        left: 0;
        bottom: -6px;
        padding: 6px 10px;
    }
}

/* =========================================================
   SECTION 2: WHO WE ARE
   Bespoke Theme: Atelier Alabaster & Warm Quartz Rose
   Typography: Harmonized with Sowkar Products Section
========================================================= */
.sowkar-whoweare-section {
    position: relative;
    width: 100%;
    padding: 95px 0 90px;
    overflow: hidden;
    isolation: isolate;
    /* Luminous pure white base */
    background: #FFFFFF;
    border-top: 1px solid rgba(53, 18, 79, 0.08);
    border-bottom: 1px solid rgba(53, 18, 79, 0.06);
}

/* Ambient glows */
.sww-ambient-glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(60px);
    pointer-events: none;
    z-index: 0;
}

.sww-glow-top {
    top: -60px;
    right: 8%;
    width: 380px;
    height: 380px;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.09) 0%, rgba(155, 63, 143, 0.04) 50%, transparent 70%);
}

.sww-glow-bottom {
    bottom: -60px;
    left: 5%;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(104, 26, 102, 0.07) 0%, rgba(201, 75, 92, 0.03) 50%, transparent 70%);
}

/* Subtle luxury background watermark */
.sww-watermark-text {
    position: absolute;
    right: -2%;
    bottom: -5%;
    font-family: "Urbanist", sans-serif;
    font-size: clamp(140px, 18vw, 240px);
    font-weight: 900;
    letter-spacing: -6px;
    color: rgba(53, 18, 79, 0.025);
    line-height: 1;
    user-select: none;
    pointer-events: none;
    z-index: 0;
}

.sowkar-whoweare-section .container {
    position: relative;
    z-index: 2;
}

/* Left Content Panel */
.sww-content-panel {
    display: flex;
    flex-direction: column;
    justify-content: center;
}

/* Kicker & Heading Mark matching Products Section (Animated with sauHeroFadeDown when visible) */
.sww-kicker-wrapper {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 14px;
    opacity: 0;
}

.sowkar-whoweare-section.is-visible .sww-kicker-wrapper {
    animation: sauHeroFadeDown 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.15s forwards;
}

.sww-eyebrow {
    display: inline-block;
    font-family: "Montserrat", sans-serif;
    font-size: 11.5px;
    line-height: 1;
    font-weight: 700;
    letter-spacing: 3.5px;
    text-transform: uppercase;
    color: var(--sowkar-red);
}

.sww-heading-mark {
    display: flex;
    align-items: center;
    gap: 6px;
}

.sww-heading-mark span {
    display: block;
    width: 24px;
    height: 1px;
    background: var(--sowkar-red);
    opacity: 0.45;
}

.sww-heading-mark i {
    display: block;
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--sowkar-red);
}

/* Main Heading (Light 300 + Bold 800 with sauHeroTextReveal Line Masks matching Hero Section) */
.sww-main-heading {
    width: 600px;
    margin: 0 0 20px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(32px, 3.8vw, 52px);
    line-height: 1.05;
    letter-spacing: -1.5px;
    text-transform: uppercase;
}

.sww-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 3px;
}

.sww-heading-line>span {
    display: inline-block;
    transform: translateY(110%);
}

.sww-heading-line:nth-child(1)>span {
    font-weight: 400;
    color: var(--sowkar-navy);
}

.sww-heading-line:nth-child(2)>span {
    margin-top: 4px;
    font-weight: 800;
    color: var(--sowkar-red);
}

.sowkar-whoweare-section.is-visible .sww-heading-line>span {
    animation: sauHeroTextReveal 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.sowkar-whoweare-section.is-visible .sww-heading-line:nth-child(1)>span {
    animation-delay: 0.25s;
}

.sowkar-whoweare-section.is-visible .sww-heading-line:nth-child(2)>span {
    animation-delay: 0.4s;
}

/* Body Copy */
.sww-body-copy {
    margin-bottom: 26px;
}

.sww-body-copy p {
    margin: 0 0 16px;
    font-family: "Montserrat", sans-serif;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.8;
    letter-spacing: 0.15px;
    color: var(--sowkar-text);
    opacity: 0;
}

.sowkar-whoweare-section.is-visible .sww-body-copy p {
    animation: sauHeroFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.sowkar-whoweare-section.is-visible .sww-body-copy p:nth-child(1) {
    animation-delay: 0.48s;
}

.sowkar-whoweare-section.is-visible .sww-body-copy p:nth-child(2) {
    animation-delay: 0.62s;
    margin-bottom: 0;
}

.sww-body-copy p strong {
    color: var(--sowkar-navy);
    font-weight: 600;
}

.sww-body-copy p em {
    font-style: normal;
    font-weight: 600;
    color: var(--sowkar-navy);
}

/* 3-Pillar / Sector Strip */
.sww-pillars-strip {
    display: inline-flex;
    align-items: center;
    /* gap: 12px; */
    flex-wrap: wrap;
    padding: 8px 16px;
    background: rgba(201, 75, 92, 0.08);
    border: 1px solid rgba(201, 75, 92, 0.18);
    border-radius: 30px;
    opacity: 0;
}

.sowkar-whoweare-section.is-visible .sww-pillars-strip {
    animation: sauHeroFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.75s forwards;
}

.sww-pillar-tag {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 20px;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
    transition: all 0.3s ease;
    cursor: default;
}

.sww-pillar-tag i {
    color: var(--sowkar-red);
    font-size: 13px;
    transition: transform 0.3s ease;
}

.sww-pillar-tag:hover {
    color: var(--sowkar-red);
    background: rgba(201, 75, 92, 0.08);
    transform: translateY(-2px);
}

.sww-pillar-tag:hover i {
    transform: scale(1.25) rotate(-8deg);
}

.sww-pillar-divider {
    color: var(--sowkar-red);
    opacity: 0.5;
    font-size: 10px;
}

/* =========================================================
   RIGHT VISUAL ARCHITECTURE (Bespoke Sculptural Design)
========================================================= */
.sww-visual-wrapper {
    position: relative;
    width: 100%;
    min-height: 480px;
    display: flex;
    align-items: center;
    justify-content: center;
    perspective: 1000px;
}

/* Glass Chassis Backdrop */
.sww-glass-chassis {
    position: absolute;
    width: 90%;
    height: 92%;
    border-radius: 36px 8px 36px 8px;
    border: 1.5px dashed rgba(201, 75, 92, 0.35);
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.6) 0%, rgba(248, 238, 247, 0.4) 100%);
    transform: rotate(-2.5deg);
    transition: transform 0.7s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.4s ease;
    pointer-events: none;
    z-index: 1;
}

.sww-visual-wrapper:hover .sww-glass-chassis {
    transform: rotate(-4deg) scale(1.02);
    border-color: rgba(201, 75, 92, 0.65);
}

/* Diagonal Accent Ribbon */
.sww-ribbon-line {
    position: absolute;
    top: 20px;
    right: 8%;
    width: 60px;
    height: 60px;
    border-top: 2px solid rgba(201, 75, 92, 0.7);
    border-right: 2px solid rgba(201, 75, 92, 0.7);
    z-index: 4;
    pointer-events: none;
}

/* Main Image Sculpture */
.sww-image-sculpture {
    position: relative;
    width: 86%;
    height: 420px;
    border-radius: 28px;
    overflow: hidden;
    box-shadow:
        0 25px 60px rgba(53, 18, 79, 0.16),
        0 0 0 1px rgba(255, 255, 255, 0.8);
    transform: rotate(1.5deg);
    transition: transform 0.7s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.7s ease;
    z-index: 2;
}

.sww-visual-wrapper:hover .sww-image-sculpture {
    transform: rotate(0deg) scale(1.02);
    box-shadow: 0 35px 80px rgba(53, 18, 79, 0.24);
}

.sww-image-sculpture img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transform: scale(1.06);
    transition: transform 1.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.sww-visual-wrapper:hover .sww-image-sculpture img {
    transform: scale(1.01);
}

.sww-image-vignette {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(36, 16, 47, 0.05) 0%, transparent 40%, rgba(36, 16, 47, 0.35) 100%);
    pointer-events: none;
