/* =========================================================
   WHO WE ARE: SCULPTURAL VISUAL ANIMATIONS
========================================================= */
.sowkar-whoweare-section .sww-visual-wrapper {
    opacity: 0;
    transform: translateY(28px);
}

.sowkar-whoweare-section.is-visible .sww-visual-wrapper {
    animation: sauVisualReveal 1.1s cubic-bezier(0.16, 1, 0.3, 1) 0.2s forwards;
}

.sowkar-whoweare-section .sww-floating-craft-label {
    opacity: 0;
    transform: scale(0.65) translateY(12px);
}

.sowkar-whoweare-section.is-visible .sww-floating-craft-label {
    animation: swwBadgePop 0.9s cubic-bezier(0.34, 1.56, 0.64, 1) 0.55s forwards;
}

.sowkar-whoweare-section .sww-floating-tri-chip {
    opacity: 0;
    transform: scale(0.65) translateY(12px);
}

.sowkar-whoweare-section.is-visible .sww-floating-tri-chip {
    animation: swwBadgePop 0.9s cubic-bezier(0.34, 1.56, 0.64, 1) 0.7s forwards;
}

.sww-tri-indicator span {
    animation: swwEqualizer 1.8s ease-in-out infinite alternate;
}

.sww-tri-indicator span:nth-child(1) {
    animation-delay: 0.1s;
}

.sww-tri-indicator span:nth-child(2) {
    animation-delay: 0.35s;
}

.sww-tri-indicator span:nth-child(3) {
    animation-delay: 0.6s;
}

@keyframes swwFadeDown {
    from {
        opacity: 0;
        transform: translateY(-16px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes swwFadeUp {
    from {
        opacity: 0;
        transform: translateY(22px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes swwVisualReveal {
    from {
        opacity: 0;
        transform: translateY(28px) scale(0.96);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@keyframes swwBadgePop {
    from {
        opacity: 0;
        transform: scale(0.65) translateY(12px);
    }

    to {
        opacity: 1;
        transform: scale(1) translateY(0);
    }
}

@keyframes swwEqualizer {
    0% {
        transform: scaleY(0.7);
    }

    100% {
        transform: scaleY(1.3);
    }
}

