/* =========================================================
   MINIMALIST LUXURY SUPPLIER LOGO PEDESTAL CARDS
   Pure Logo Focus, Zero Text Clutter, Ultra-Refined Finish
========================================================= */
.ss-logo-card {
    position: relative;
    background: #FFFFFF;
    border: 1.5px solid rgba(53, 18, 79, 0.10);
    border-radius: 16px;
    padding: 20px 24px;
    height: 120px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow:
        0 10px 26px -4px rgba(53, 18, 79, 0.06),
        0 2px 6px -1px rgba(53, 18, 79, 0.03),
        inset 0 1px 0 rgba(255, 255, 255, 0.95);
    overflow: hidden;
    transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s ease, border-color 0.4s ease;
    opacity: 0;
    transform: translateY(22px);
    cursor: pointer;
}

/* Diagonal Interactive Light Sheen Sweep */
.ss-logo-card::after {
    content: "";
    position: absolute;
    top: 0;
    left: -140%;
    width: 70%;
    height: 100%;
    background: linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.8) 50%, transparent 100%);
    transform: skewX(-25deg);
    transition: left 0.85s cubic-bezier(0.16, 1, 0.3, 1);
    pointer-events: none;
    z-index: 5;
}

.ss-logo-card:hover::after {
    left: 180%;
}

/* Tailor Corner Accent Marks (Top-Left) */
.ss-logo-card::before {
    content: "";
    position: absolute;
    top: 8px;
    left: 8px;
    width: 10px;
    height: 10px;
    border-top: 1.5px solid rgba(201, 75, 92, 0.35);
    border-left: 1.5px solid rgba(201, 75, 92, 0.35);
    pointer-events: none;
    transition: border-color 0.35s ease, transform 0.35s ease;
    z-index: 2;
}

/* Tailor Corner Accent Marks (Bottom-Right) */
.ss-card-accent-br {
    position: absolute;
    bottom: 8px;
    right: 8px;
    width: 10px;
    height: 10px;
    border-bottom: 1.5px solid rgba(201, 75, 92, 0.35);
    border-right: 1.5px solid rgba(201, 75, 92, 0.35);
    pointer-events: none;
    transition: border-color 0.35s ease, transform 0.35s ease;
    z-index: 2;
}

/* Luminous Bottom Glow Edge */
.ss-card-glow-edge {
    position: absolute;
    bottom: 0;
    left: 20%;
    right: 20%;
    height: 2.5px;
    background: linear-gradient(90deg, transparent, var(--sowkar-red), transparent);
    opacity: 0;
    transition: opacity 0.4s ease, left 0.4s ease, right 0.4s ease;
    pointer-events: none;
}

/* HOVER STATES */
.ss-logo-card:hover {
    transform: translateY(-7px) scale(1.02);
    border-color: rgba(201, 75, 92, 0.45);
    box-shadow:
        0 22px 48px -8px rgba(53, 18, 79, 0.14),
        0 0 25px rgba(201, 75, 92, 0.14),
        inset 0 1px 0 rgba(255, 255, 255, 1);
}

.ss-logo-card:hover::before {
    border-color: var(--sowkar-red);
    transform: translate(-1px, -1px);
}

.ss-logo-card:hover .ss-card-accent-br {
    border-color: var(--sowkar-red);
    transform: translate(1px, 1px);
}

.ss-logo-card:hover .ss-card-glow-edge {
    left: 0;
    right: 0;
    opacity: 1;
}

.ss-logo-card img {
    max-width: 88%;
    max-height: 100px;
    width: auto;
    height: auto;
    object-fit: contain;
    filter: contrast(105%);
    transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), filter 0.4s ease;
    position: relative;
    z-index: 1;
}

.ss-logo-card:hover img {
    transform: scale(1.08);
    filter: contrast(110%);
}

/* Entrance Animations on .is-visible */
.sowkar-suppliers-section.is-visible .ss-card-1 {
    animation: sauHeroFadeUp 0.75s cubic-bezier(0.16, 1, 0.3, 1) 0.38s forwards;
}

.sowkar-suppliers-section.is-visible .ss-card-2 {
