}

.sowkar-suppliers-section.is-visible .ss-card-5 {
    animation: sauHeroFadeUp 0.75s cubic-bezier(0.16, 1, 0.3, 1) 0.62s forwards;
}

.sowkar-suppliers-section.is-visible .ss-card-6 {
    animation: sauHeroFadeUp 0.75s cubic-bezier(0.16, 1, 0.3, 1) 0.68s forwards;
}

.sowkar-suppliers-section.is-visible .ss-card-7 {
