/* =========================================================
   =========================================================
   SOWKAR TEXTILES – CLIENTS PAGE STYLES
   Bespoke Hero, Logo Showcase with Filters, Trust Band,
   Testimonials Page & CTA Section
   =========================================================
========================================================= */

/* =========================================================
   SECTION 0 – CLIENTS HERO (REIMAGINED)
   Left text, right abstract shape grid — unique for clients
========================================================= */
.sowkar-clients-hero {
    position: relative;
    width: 100%;
    min-height: 75vh;
    padding: 55px 0 60px;
    overflow: hidden;
    isolation: isolate;
    display: flex;
    align-items: center;
    background:
        radial-gradient(circle at 85% 20%, rgba(155, 63, 143, 0.22), transparent 40%),
        radial-gradient(circle at 15% 80%, rgba(201, 75, 92, 0.18), transparent 42%),
        linear-gradient(145deg, #0c0612 0%, #1a0b22 45%, #22102c 100%);
}

/* Woven grid – subtle texture */
.sowkar-clients-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(to right, rgba(234, 220, 240, 0.04) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(234, 220, 240, 0.04) 1px, transparent 1px);
    background-size: 52px 52px;
    mask-image: radial-gradient(ellipse at 60% 45%, black 30%, transparent 75%);
    -webkit-mask-image: radial-gradient(ellipse at 60% 45%, black 30%, transparent 75%);
    pointer-events: none;
    z-index: 1;
}

/* Soft aura pulse */
.sowkar-clients-hero::after {
    content: "";
    position: absolute;
    top: -12%;
    right: 5%;
    width: 700px;
    height: 700px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.12) 0%, rgba(155, 63, 143, 0.05) 45%, transparent 72%);
    filter: blur(70px);
    pointer-events: none;
    z-index: 1;
    animation: heroAuraPulse 12s ease-in-out infinite alternate;
}

@keyframes heroAuraPulse {
    0% {
        transform: scale(1);
        opacity: .5;
    }

    100% {
        transform: scale(1.15);
        opacity: 1;
    }
}

.sowkar-clients-hero .container {
    position: relative;
    z-index: 10;
}

/* ---- Split layout ---- */
.ch-hero-split {
    display: grid;
    grid-template-columns: 1.12fr 0.88fr;
    gap: 48px;
    align-items: center;
}

/* ---- Left column ---- */
.ch-left {
    max-width: 620px;
}

/* Top Meta: Breadcrumb + Kicker Inline */
.ch-top-meta {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
    margin-bottom: 14px;
    flex-wrap: wrap;
    opacity: 0;
    animation: chFadeDown .8s cubic-bezier(.16, 1, .3, 1) .15s forwards;
}

/* Breadcrumb */
.ch-crumb {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 5px 16px;
    margin: 0;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 40px;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}

.ch-crumb-item {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.75);
}

.ch-crumb-item a {
    color: rgba(255, 255, 255, 0.75);
    display: inline-flex;
    align-items: center;
    transition: color .3s;
}

.ch-crumb-item a:hover {
    color: #E77A88;
}

.ch-crumb-sep {
    color: rgba(201, 75, 92, 0.6);
    font-size: 11px;
}

.ch-crumb-item.active {
    color: #E77A88;
    font-weight: 700;
}

/* Kicker inline */
.ch-label {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin: 0;
}

.ch-label-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #C94B5C;
    box-shadow: 0 0 10px #C94B5C;
    animation: chDotGlow 2s infinite ease-in-out;
}

@keyframes chDotGlow {

    0%,
    100% {
        transform: scale(1);
        opacity: .8;
        box-shadow: 0 0 6px #C94B5C;
    }

    50% {
        transform: scale(1.25);
        opacity: 1;
        box-shadow: 0 0 16px #E77A88;
    }
}

.ch-label-text {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.85);
}

.ch-label-line {
    width: 48px;
    height: 1.5px;
    background: linear-gradient(90deg, #C94B5C, #C98BC2);
}

/* Heading with line reveal */
.ch-heading {
    margin: 0 0 6px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(38px, 4.2vw, 62px);
    font-weight: 900;
    line-height: .96;
    letter-spacing: -2.5px;
    text-transform: uppercase;
    color: #ffffff;
    max-width: 620px;
}

.ch-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 4px;
}

.ch-heading-line>span {
    display: inline-block;
    transform: translateY(115%);
    animation: chTextReveal .95s cubic-bezier(.16, 1, .3, 1) forwards;
}

.ch-heading-line:nth-child(1)>span {
    animation-delay: .40s;
}

.ch-heading-line:nth-child(2)>span {
    animation-delay: .55s;
}

.ch-text-gradient {
    background: linear-gradient(135deg, #ffffff 15%, #C98BC2 55%, #E77A88 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.ch-text-highlight {
    color: #E77A88;
    font-family: "Playfair Display", serif;
    font-style: italic;
    font-weight: 600;
    text-transform: capitalize;
    letter-spacing: -2px;
    -webkit-text-fill-color: initial;
}

/* Tagline */
.ch-tagline {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 14px;
    font-family: "Montserrat", sans-serif;
    font-size: 11.5px;
    font-weight: 600;
    letter-spacing: 2.4px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.85);
    opacity: 0;
    animation: chFadeUp .8s cubic-bezier(.16, 1, .3, 1) .72s forwards;
}

.ch-tagline-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #C94B5C;
}

.ch-tagline em {
    font-style: normal;
    color: #E77A88;
    font-weight: 700;
}

/* Sub-copy */
.ch-subcopy {
    max-width: 540px;
    margin: 0 0 26px;
    font-family: "Montserrat", sans-serif;
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.72;
    color: #C9B8D0;
    opacity: 0;
    animation: chFadeUp .8s cubic-bezier(.16, 1, .3, 1) .88s forwards;
