    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
    opacity: 0;
    animation: chFadeUp .8s cubic-bezier(.16, 1, .3, 1) 1.02s forwards;
}

.ch-btn-primary {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 24px;
    background: linear-gradient(100deg, #9B3F8F, #C94B5C);
    border: 1px solid rgba(255, 255, 255, 0.18);
