.ch-btn-glass {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 22px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 4px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 1.4px;
    text-transform: uppercase;
    text-decoration: none;
    white-space: nowrap;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: background .3s, border-color .3s, transform .3s;
}

.ch-btn-glass:hover {
    color: #ffffff;
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(201, 75, 92, 0.4);
    transform: translateY(-3px);
}

/* ---- Right column – abstract shape grid (unique visual) ---- */
.ch-right {
    position: relative;
    height: clamp(340px, 40vh, 410px);
    max-width: 480px;
    width: 100%;
    margin-left: auto;
    opacity: 0;
    animation: chFadeUp 1s cubic-bezier(.16, 1, .3, 1) .6s forwards;
}

.ch-shape-grid {
    position: relative;
    width: 100%;
    height: 100%;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 12px;
}

/* Individual shape tiles — abstract, distinct */
.ch-shape {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    overflow: hidden;
    transition: transform .5s cubic-bezier(.16, 1, .3, 1), background .5s ease, border-color .5s ease, box-shadow .5s ease;
    cursor: default;
}

.ch-shape:hover {
    background: rgba(155, 63, 143, 0.12);
    border-color: rgba(201, 75, 92, 0.35);
    transform: translateY(-6px) scale(1.02);
    box-shadow: 0 20px 45px rgba(201, 75, 92, 0.15);
    z-index: 2;
}

.ch-shape i {
    font-size: 28px;
    color: rgba(255, 255, 255, 0.5);
    transition: color .4s ease, transform .4s ease;
}

.ch-shape:hover i {
    color: #E77A88;
    transform: scale(1.15);
}

/* Different shape styles per tile */
.ch-shape-1 {
    grid-column: span 2;
    grid-row: span 2;
    border-radius: 28px 28px 28px 28px;
    background: linear-gradient(145deg, rgba(155, 63, 143, 0.12), rgba(201, 75, 92, 0.06));
    border: 1px solid rgba(201, 75, 92, 0.18);
    flex-direction: column;
    gap: 6px;
