    transform: translateY(26px) scale(.96);
    transition: opacity .85s cubic-bezier(.16, 1, .3, 1),
        transform .5s cubic-bezier(.16, 1, .3, 1),
        box-shadow .5s ease;
}

.sowkar-trust-band.is-visible .tb-strip-frame:nth-child(1),
.sowkar-trust-band.in-view .tb-strip-frame:nth-child(1) {
    opacity: 1;
    transform: translateY(0) scale(1);
    transition-delay: .32s, 0s, 0s;
}

.sowkar-trust-band.is-visible .tb-strip-frame:nth-child(2),
.sowkar-trust-band.in-view .tb-strip-frame:nth-child(2) {
    opacity: 1;
    transform: translateY(0) scale(1);
    transition-delay: .45s, 0s, 0s;
}

.sowkar-trust-band.is-visible .tb-strip-frame:nth-child(3),
.sowkar-trust-band.in-view .tb-strip-frame:nth-child(3) {
    opacity: 1;
    transform: translateY(0) scale(1);
    transition-delay: .58s, 0s, 0s;
}

.tb-strip-frame::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(36, 16, 47, 0.05) 0%, transparent 40%, rgba(36, 16, 47, 0.35) 100%);
    pointer-events: none;
    z-index: 2;
    transition: opacity .4s ease;
}

.tb-strip-frame:hover {
    transform: translateY(-4px) scale(1);
    box-shadow: 0 20px 45px rgba(53, 18, 79, 0.14);
}

.tb-strip-frame:hover::after {
    opacity: 0.6;
}

.tb-strip-frame img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transform: scale(1.04);
    transition: transform 1.2s cubic-bezier(.16, 1, .3, 1);
}

.tb-strip-frame:hover img {
    transform: scale(1.01);
}

.tb-strip-frame.tall {
    grid-row: span 2;
}

.tb-frame-tag {
    position: absolute;
    bottom: 14px;
    left: 14px;
    z-index: 3;
    padding: 5px 12px;
    background: rgba(36, 16, 47, 0.82);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 30px;
    font-family: "Montserrat", sans-serif;
    font-size: 8.5px;
    font-weight: 700;
    letter-spacing: 1.6px;
    text-transform: uppercase;
    color: #ffffff;
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
}

.tb-chips {
    display: flex;
    flex-direction: column;
    gap: 14px;
    height: 440px;
    justify-content: space-between;
}

.tb-chip {
    position: relative;
    flex: 1;
    display: grid;
    grid-template-columns: 60px 1fr 34px;
    gap: 20px;
    align-items: center;
    padding: 18px 22px;
    background: #ffffff;
    border: 1px solid rgba(53, 18, 79, 0.10);
    border-radius: 14px;
    overflow: hidden;
    opacity: 0;
    transform: translateX(28px);
    transition: opacity .8s cubic-bezier(.16, 1, .3, 1),
        transform .4s cubic-bezier(.16, 1, .3, 1),
        box-shadow .4s ease,
        border-color .4s ease;
}

.sowkar-trust-band.is-visible .tb-chip:nth-child(1),
.sowkar-trust-band.in-view .tb-chip:nth-child(1) {
    opacity: 1;
    transform: translateX(0);
    transition-delay: .36s, 0s, 0s, 0s;
}

.sowkar-trust-band.is-visible .tb-chip:nth-child(2),
.sowkar-trust-band.in-view .tb-chip:nth-child(2) {
    opacity: 1;
    transform: translateX(0);
    transition-delay: .48s, 0s, 0s, 0s;
}

.sowkar-trust-band.is-visible .tb-chip:nth-child(3),
.sowkar-trust-band.in-view .tb-chip:nth-child(3) {
    opacity: 1;
    transform: translateX(0);
    transition-delay: .60s, 0s, 0s, 0s;
}

.sowkar-trust-band.is-visible .tb-chip:nth-child(4),
.sowkar-trust-band.in-view .tb-chip:nth-child(4) {
    opacity: 1;
    transform: translateX(0);
    transition-delay: .72s, 0s, 0s, 0s;
}

.tb-chip::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 3px;
    height: 100%;
    background: linear-gradient(180deg, var(--sowkar-red), var(--sowkar-purple));
    opacity: 0;
    transition: opacity .35s ease;
}

.tb-chip:hover {
    transform: translateX(6px);
    border-color: rgba(201, 75, 92, 0.35);
    box-shadow: 0 16px 40px rgba(53, 18, 79, 0.10);
}

.tb-chip:hover::before {
    opacity: 1;
}

.tb-chip-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 54px;
    height: 54px;
    border-radius: 14px;
    background: rgba(201, 75, 92, 0.08);
    border: 1px solid rgba(201, 75, 92, 0.18);
    color: var(--sowkar-red);
    font-size: 22px;
    transition: background .4s ease, color .4s ease, transform .4s ease, border-color .4s ease;
    flex-shrink: 0;
}

.tb-chip:hover .tb-chip-icon {
    background: linear-gradient(135deg, var(--sowkar-red), var(--sowkar-purple));
    color: #ffffff;
    border-color: transparent;
    transform: rotate(-8deg) scale(1.06);
}

.tb-chip-text h4 {
    margin: 0 0 4px;
    font-family: "Urbanist", sans-serif;
    font-size: 16px;
    font-weight: 700;
    letter-spacing: 0.2px;
    color: var(--sowkar-navy);
    line-height: 1.25;
    transition: color .3s ease;
}

.tb-chip:hover .tb-chip-text h4 {
    color: var(--sowkar-red);
}

.tb-chip-text p {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 11.5px;
    font-weight: 400;
    line-height: 1.55;
    color: var(--sowkar-muted);
}

.tb-chip-arrow {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    border: 1px solid rgba(53, 18, 79, 0.12);
    color: var(--sowkar-muted);
    font-size: 13px;
    transition: transform .4s ease, background .4s ease, color .4s ease, border-color .4s ease;
}

.tb-chip:hover .tb-chip-arrow {
    background: var(--sowkar-red);
    border-color: var(--sowkar-red);
    color: #ffffff;
    transform: rotate(45deg);
}

.tb-footer {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 20px;
    margin-top: 50px;
    opacity: 0;
    transform: translateY(18px);
    transition: opacity .8s cubic-bezier(.16, 1, .3, 1) .82s, transform .8s cubic-bezier(.16, 1, .3, 1) .82s;
}

.sowkar-trust-band.is-visible .tb-footer,
.sowkar-trust-band.in-view .tb-footer {
    opacity: 1;
    transform: translateY(0);
}

.tb-footer-line {
    width: 80px;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--sowkar-red), transparent);
    transform-origin: center;
    transform: scaleX(0);
    transition: transform .6s cubic-bezier(.16, 1, .3, 1) .92s;
}

.sowkar-trust-band.is-visible .tb-footer-line,
.sowkar-trust-band.in-view .tb-footer-line {
    transform: scaleX(1);
}

.tb-footer p {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 2.6px;
    text-transform: uppercase;
    color: var(--sowkar-muted);
}

.tb-footer p strong {
    color: var(--sowkar-navy);
    font-weight: 700;
}

/* =========================================================
   SECTION 3 – TESTIMONIALS (CLIENTS PAGE)
========================================================= */
.sowkar-testimonials-page {
