}

.tp-heading {
    margin: 0 0 16px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(36px, 4.2vw, 58px);
    font-weight: 300;
    line-height: 1.05;
    letter-spacing: -1.8px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

.tp-heading em {
    font-style: normal;
    font-weight: 800;
