}

.tp-intro {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.8;
    color: var(--sowkar-muted);
}

.tp-carousel-wrap {
    position: relative;
    opacity: 0;
    transform: translateY(26px);
    transition: opacity .85s cubic-bezier(.16, 1, .3, 1) .35s, transform .85s cubic-bezier(.16, 1, .3, 1) .35s;
}

.sowkar-testimonials-page.is-visible .tp-carousel-wrap,
.sowkar-testimonials-page.in-view .tp-carousel-wrap {
