    padding: 25px 20px 35px;
    margin: -25px -20px -35px;
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-stage {
    display: flex;
    align-items: center;
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-item {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 10px 8px 20px;
}

.tp-card {
    position: relative;
    width: 100%;
    min-height: 380px;
    display: flex;
    flex-direction: column;
    padding: 40px 36px 34px;
    background: #ffffff;
    border-radius: 18px;
    box-shadow: 0 20px 55px rgba(53, 18, 79, 0.10);
    overflow: hidden;
