}

.tp-quote {
    height: 52px;
    font-family: Georgia, serif;
    font-size: 88px;
    font-weight: 700;
    line-height: 0.75;
    color: #ECA0AA;
}

.tp-text {
    flex: 1;
    display: flex;
    align-items: flex-start;
    margin-top: 12px;
}

.tp-text p {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 14.5px;
    font-weight: 400;
