    background: var(--sowkar-red);
    border-radius: 3px;
}

.tp-author {
    margin-top: auto;
}

.tp-author h4 {
    margin: 0 0 4px;
    font-family: "Urbanist", sans-serif;
    font-size: 16px;
    font-weight: 700;
    color: var(--sowkar-navy);
    line-height: 1.3;
}

.tp-author span {
    display: block;
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--sowkar-muted);
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-nav {
    position: absolute;
    top: 50%;
    left: -60px;
    right: -60px;
    transform: translateY(-50%);
    display: flex;
    justify-content: space-between;
    pointer-events: none;
    margin: 0;
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-nav button.owl-prev,
.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-nav button.owl-next {
    width: 52px;
    height: 52px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0;
    border: 2px solid var(--sowkar-navy) !important;
    border-radius: 50%;
    background: #ffffff !important;
    color: var(--sowkar-navy) !important;
    font-size: 20px !important;
    line-height: 1;
    pointer-events: auto;
    transition: background .3s ease, color .3s ease, border-color .3s ease, transform .3s ease;
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-nav button:hover {
    background: var(--sowkar-red) !important;
    border-color: var(--sowkar-red) !important;
