}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-dots {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    margin-top: 25px;
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-dots .owl-dot {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    padding: 0;
    border: 0;
    background: transparent !important;
    cursor: pointer;
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-dots .owl-dot span {
    display: block;
    width: 8px;
    height: 8px;
    margin: 0;
    border-radius: 50%;
    background: #D5BFCB;
    transition: width .3s ease, background .3s ease, border-radius .3s ease;
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-dots .owl-dot.active span {
    width: 26px;
    border-radius: 20px;
    background: var(--sowkar-red);
}

.sowkar-testimonials-page .sowkar-testimonial-carousel .owl-dots .owl-dot:hover span {
    background: var(--sowkar-red);
}

/* =========================================================
   SECTION 4 – CLIENTS CTA
========================================================= */
.sowkar-clients-cta {
    position: relative;
    width: 100%;
    padding: 100px 0;
    background: #fbf8f5;
    overflow: hidden;
    isolation: isolate;
}

.sowkar-clients-cta .sowkar-cta-content {
    position: relative;
    z-index: 2;
