    color: #50506c;
    overflow: hidden;
}

.sowkar-clients-cta .sowkar-cta-text>span {
    display: inline-block;
    transform: translateY(115%);
    transition: transform 0.85s cubic-bezier(0.16, 1, 0.3, 1);
