/* In-View & Is-Visible Animation Triggers for CTA */
.sowkar-clients-cta.is-visible .sowkar-cta-label>span,
.sowkar-clients-cta.in-view .sowkar-cta-label>span {
    transform: translateY(0);
    transition-delay: 0.1s;
}

.sowkar-clients-cta.is-visible .sowkar-cta-line,
.sowkar-clients-cta.in-view .sowkar-cta-line {
    transform: scaleX(1);
    transition-delay: 0.25s;
}

.sowkar-clients-cta.is-visible .sowkar-cta-heading .scrub-heading-line:nth-child(1)>span,
.sowkar-clients-cta.in-view .sowkar-cta-heading .scrub-heading-line:nth-child(1)>span {
    transform: translateY(0);
