/* =========================================================
   CONTACT US PAGE STYLES (sowkar-textiles-contacts.html)
========================================================= */

/* SECTION 0 – CONTACT HERO */
.sowkar-contact-hero {
    position: relative;
    width: 100%;
    min-height: 75vh;
    padding: clamp(40px, 5vh, 65px) 0;
    display: flex;
    align-items: center;
    overflow: hidden;
    isolation: isolate;
    background:
        radial-gradient(circle at 80% 30%, rgba(155, 63, 143, 0.24), transparent 42%),
        radial-gradient(circle at 20% 80%, rgba(201, 75, 92, 0.20), transparent 40%),
        linear-gradient(140deg, #0c0612 0%, #1a0b22 50%, #22102c 100%);
}

.sowkar-contact-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(to right, rgba(234, 220, 240, 0.04) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(234, 220, 240, 0.04) 1px, transparent 1px);
    background-size: 52px 52px;
    mask-image: radial-gradient(ellipse at 50% 50%, black 30%, transparent 78%);
    -webkit-mask-image: radial-gradient(ellipse at 50% 50%, black 30%, transparent 78%);
    pointer-events: none;
    z-index: 1;
}

.sowkar-contact-hero::after {
    content: "";
    position: absolute;
    top: -10%;
    right: 0%;
    width: 720px;
    height: 720px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.13) 0%, rgba(155, 63, 143, 0.05) 45%, transparent 72%);
    filter: blur(70px);
    pointer-events: none;
    z-index: 1;
    animation: cHeroAura 12s ease-in-out infinite alternate;
}

@keyframes cHeroAura {
    0% {
        transform: scale(1);
        opacity: .5;
    }

    100% {
        transform: scale(1.14);
        opacity: 1;
    }
}

.sowkar-contact-hero .container {
    position: relative;
    z-index: 10;
}

.c-hero-inner {
    max-width: 820px;
    margin: 0 auto;
    text-align: center;
}

/* Breadcrumb */
.c-crumb {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 5px 16px;
    margin-bottom: 14px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 40px;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    opacity: 0;
    animation: cFadeDown .8s cubic-bezier(.16, 1, .3, 1) .15s forwards;
}

.c-crumb-item {
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.75);
}

.c-crumb-item a {
    color: rgba(255, 255, 255, 0.75);
    transition: color .3s;
}

.c-crumb-item a:hover {
    color: #E77A88;
}

.c-crumb-sep {
    color: rgba(201, 75, 92, 0.6);
    font-size: 11px;
}

.c-crumb-item.active {
    color: #E77A88;
    font-weight: 700;
}

/* Kicker */
.c-label {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    opacity: 0;
    animation: cFadeDown .8s cubic-bezier(.16, 1, .3, 1) .28s forwards;
}

.c-label-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #C94B5C;
    box-shadow: 0 0 12px #C94B5C;
    animation: cDotGlow 2s infinite ease-in-out;
}

@keyframes cDotGlow {

    0%,
    100% {
        transform: scale(1);
        opacity: .8;
        box-shadow: 0 0 6px #C94B5C;
    }

    50% {
        transform: scale(1.25);
        opacity: 1;
        box-shadow: 0 0 16px #E77A88;
    }
}

.c-label-text {
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 3.6px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.72);
}

.c-label-line {
    width: 52px;
    height: 1px;
    background: linear-gradient(90deg, #C94B5C, #C98BC2);
}

/* Heading */
.c-heading {
    margin: 0 auto 6px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(38px, 4.6vw, 70px);
    font-weight: 900;
    line-height: .96;
    letter-spacing: -2.5px;
    text-transform: uppercase;
    color: #ffffff;
    max-width: 820px;
}

.c-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 4px;
}

.c-heading-line>span {
    display: inline-block;
    transform: translateY(115%);
    animation: cTextReveal .95s cubic-bezier(.16, 1, .3, 1) forwards;
}

.c-heading-line:nth-child(1)>span {
    animation-delay: .40s;
}

.c-heading-line:nth-child(2)>span {
    animation-delay: .55s;
}

.c-text-gradient {
    background: linear-gradient(135deg, #ffffff 15%, #C98BC2 55%, #E77A88 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.c-text-highlight {
    color: #E77A88;
    font-family: "Playfair Display", serif;
    font-style: italic;
    font-weight: 600;
    text-transform: capitalize;
    letter-spacing: -2px;
    -webkit-text-fill-color: initial;
}

/* Sub copy */
.c-subcopy {
    max-width: 580px;
    margin: 0 auto 24px;
    font-family: "Montserrat", sans-serif;
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.65;
    color: #C9B8D0;
    opacity: 0;
    animation: cFadeUp .8s cubic-bezier(.16, 1, .3, 1) .78s forwards;
}

/* Quick contact chips */
.c-quick-chips {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 12px;
    opacity: 0;
    animation: cFadeUp .8s cubic-bezier(.16, 1, .3, 1) .95s forwards;
}

.c-chip {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 10px 20px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.13);
    border-radius: 40px;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 1.4px;
    text-transform: uppercase;
    color: #ffffff;
    text-decoration: none;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: background .35s, border-color .35s, transform .35s;
}

.c-chip i {
    color: #E77A88;
    font-size: 15px;
    transition: transform .35s;
}

.c-chip:hover {
    color: #ffffff;
    background: rgba(201, 75, 92, 0.16);
    border-color: rgba(201, 75, 92, 0.45);
    transform: translateY(-3px);
}

.c-chip:hover i {
    transform: scale(1.15);
}

/* Corner decorations */
.c-corner {
    position: absolute;
    width: 90px;
    height: 90px;
    z-index: 5;
    pointer-events: none;
    opacity: 0;
    animation: cFadeIn 1.2s cubic-bezier(.16, 1, .3, 1) 1.4s forwards;
}

.c-corner-tl {
    top: 34px;
    left: 34px;
    border-top: 1px solid rgba(234, 220, 240, 0.32);
    border-left: 1px solid rgba(234, 220, 240, 0.32);
}

.c-corner-tr {
    top: 34px;
    right: 34px;
    border-top: 1px solid rgba(234, 220, 240, 0.32);
    border-right: 1px solid rgba(201, 75, 92, 0.55);
}

.c-corner-bl {
    bottom: 34px;
    left: 34px;
    border-bottom: 1px solid rgba(234, 220, 240, 0.32);
    border-left: 1px solid rgba(201, 75, 92, 0.55);
}

.c-corner-br {
    bottom: 34px;
    right: 34px;
    border-bottom: 1px solid rgba(234, 220, 240, 0.32);
    border-right: 1px solid rgba(234, 220, 240, 0.32);
}

.c-corner-dot {
    position: absolute;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #E77A88;
    box-shadow: 0 0 0 5px rgba(231, 122, 136, 0.14);
}

.c-corner-tr .c-corner-dot {
    top: 14px;
    right: 14px;
}

.c-corner-bl .c-corner-dot {
    bottom: 14px;
    left: 14px;
}

@keyframes cFadeIn {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

@keyframes cFadeDown {
    from {
        opacity: 0;
        transform: translateY(-16px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes cFadeUp {
    from {
        opacity: 0;
        transform: translateY(24px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes cTextReveal {
    to {
        transform: translateY(0);
    }
}

/* SECTION 1 – CONTACT INFO CARDS */
.sowkar-contact-cards {
    position: relative;
    width: 100%;
    padding: 100px 0 90px;
    background: #ffffff;
    overflow: hidden;
