}

.cc-heading {
    margin: 0 0 16px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(34px, 4vw, 54px);
    font-weight: 300;
    line-height: 1.06;
    letter-spacing: -1.6px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

.cc-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 4px;
}

.cc-heading-line>span {
    display: inline-block;
    transform: translateY(115%);
}

.sowkar-contact-cards.is-visible .cc-heading-line>span,
.sowkar-contact-cards.in-view .cc-heading-line>span {
    animation: cTextReveal .95s cubic-bezier(.16, 1, .3, 1) .35s forwards;
}

.cc-heading em {
    font-style: normal;
    font-weight: 800;
    color: var(--sowkar-red);
}

.cc-intro {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.8;
    color: var(--sowkar-muted);
    opacity: 0;
    transform: translateY(22px);
}

.sowkar-contact-cards.is-visible .cc-intro,
.sowkar-contact-cards.in-view .cc-intro {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .50s forwards;
}

.cc-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 22px;
}

.cc-card {
    position: relative;
    display: flex;
    flex-direction: column;
    padding: 38px 32px 32px;
    background: #ffffff;
    border: 1px solid rgba(53, 18, 79, 0.10);
    border-radius: 18px;
    overflow: hidden;
    opacity: 0;
    transform: translateY(28px);
    transition: transform .45s cubic-bezier(.16, 1, .3, 1), box-shadow .45s ease, border-color .45s ease;
}

.sowkar-contact-cards.is-visible .cc-card:nth-child(1),
.sowkar-contact-cards.in-view .cc-card:nth-child(1) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .60s forwards;
}

.sowkar-contact-cards.is-visible .cc-card:nth-child(2),
.sowkar-contact-cards.in-view .cc-card:nth-child(2) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .72s forwards;
}

.sowkar-contact-cards.is-visible .cc-card:nth-child(3),
.sowkar-contact-cards.in-view .cc-card:nth-child(3) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .84s forwards;
}

.cc-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 60px;
    height: 4px;
    background: linear-gradient(90deg, var(--sowkar-red), var(--sowkar-purple));
    border-radius: 0 0 4px 0;
    transition: width .5s cubic-bezier(.16, 1, .3, 1);
}

.cc-card:hover {
    transform: translateY(-8px);
    border-color: rgba(201, 75, 92, 0.35);
    box-shadow: 0 24px 55px rgba(53, 18, 79, 0.13);
}

.cc-card:hover::before {
    width: 130px;
}

.cc-card-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 62px;
    height: 62px;
    border-radius: 16px;
    background: rgba(201, 75, 92, 0.08);
    border: 1px solid rgba(201, 75, 92, 0.20);
    color: var(--sowkar-red);
    font-size: 26px;
    margin-bottom: 22px;
    transition: background .4s ease, color .4s ease, transform .4s ease, border-color .4s ease;
}

.cc-card:hover .cc-card-icon {
    background: linear-gradient(135deg, var(--sowkar-red), var(--sowkar-purple));
    color: #ffffff;
    border-color: transparent;
    transform: rotate(-8deg) scale(1.06);
}

.cc-card h3 {
    margin: 0 0 12px;
    font-family: "Urbanist", sans-serif;
    font-size: 19px;
    font-weight: 700;
    letter-spacing: 0.2px;
    color: var(--sowkar-navy);
    transition: color .3s ease;
}

.cc-card:hover h3 {
    color: var(--sowkar-red);
}

.cc-card p {
    margin: 0 0 16px;
    font-family: "Montserrat", sans-serif;
    font-size: 12.5px;
    font-weight: 400;
    line-height: 1.7;
    color: var(--sowkar-muted);
}

.cc-card-links {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-top: auto;
}

.cc-card-links a {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    font-family: "Montserrat", sans-serif;
    font-size: 12.5px;
    font-weight: 600;
    color: var(--sowkar-navy);
    text-decoration: none;
    transition: color .3s ease, gap .3s ease;
}

.cc-card-links a i {
    font-size: 12px;
    color: var(--sowkar-red);
    transition: transform .3s ease;
}

.cc-card-links a:hover {
    color: var(--sowkar-red);
    gap: 13px;
}

.cc-card-links a:hover i {
    transform: translateX(3px);
}

.cc-card-hours {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-top: auto;
}

.cc-hours-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 9px 0;
    border-bottom: 1px dashed rgba(53, 18, 79, 0.10);
    font-family: "Montserrat", sans-serif;
    font-size: 12px;
}

.cc-hours-row:last-child {
    border-bottom: 0;
}

.cc-hours-row span {
    font-weight: 500;
    color: var(--sowkar-muted);
}

.cc-hours-row strong {
    font-weight: 700;
    color: var(--sowkar-navy);
}

.cc-hours-row.closed strong {
    color: var(--sowkar-red);
}

/* SECTION 2 – FORM + MAP SPLIT */
.sowkar-contact-form-section {
    position: relative;
    width: 100%;
    padding: 100px 0 110px;
    background: linear-gradient(180deg, #FBF8F5 0%, #F5EBF2 50%, #FBF8F5 100%);
    overflow: hidden;
    isolation: isolate;
}

.sowkar-contact-form-section::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(rgba(53, 18, 79, 0.03) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
    z-index: 0;
}

.cf-glow-left,
.cf-glow-right {
    position: absolute;
    border-radius: 50%;
    filter: blur(90px);
    pointer-events: none;
    z-index: 0;
}

.cf-glow-left {
    top: 0%;
    left: -140px;
    width: 460px;
    height: 460px;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.08) 0%, transparent 70%);
}

.cf-glow-right {
    bottom: 0%;
    right: -140px;
    width: 460px;
    height: 460px;
    background: radial-gradient(circle, rgba(155, 63, 143, 0.08) 0%, transparent 70%);
}

.cf-watermark {
    position: absolute;
    right: -2%;
    bottom: 4%;
    font-family: "Urbanist", sans-serif;
    font-size: clamp(140px, 17vw, 240px);
    font-weight: 900;
    letter-spacing: -8px;
    color: rgba(53, 18, 79, 0.020);
    line-height: 1;
    user-select: none;
    pointer-events: none;
    z-index: 0;
}

.sowkar-contact-form-section .container {
    position: relative;
    z-index: 2;
}

.cf-head {
    text-align: center;
    max-width: 680px;
    margin: 0 auto 55px;
}

.cf-kicker {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.cf-kicker-line {
    width: 30px;
    height: 1px;
    background: var(--sowkar-red);
    opacity: .55;
    transform-origin: center;
    transform: scaleX(0);
}

.sowkar-contact-form-section.is-visible .cf-kicker-line,
.sowkar-contact-form-section.in-view .cf-kicker-line {
    transform: scaleX(1);
    transition: transform .6s cubic-bezier(.16, 1, .3, 1) .25s;
}

.cf-eyebrow {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3.6px;
    text-transform: uppercase;
    color: var(--sowkar-red);
    opacity: 0;
    transform: translateY(-14px);
}

.sowkar-contact-form-section.is-visible .cf-eyebrow,
.sowkar-contact-form-section.in-view .cf-eyebrow {
    animation: cFadeDown .75s cubic-bezier(.16, 1, .3, 1) .15s forwards;
}

.cf-heading {
    margin: 0 0 16px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(34px, 4vw, 54px);
    font-weight: 300;
    line-height: 1.06;
    letter-spacing: -1.6px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

.cf-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 4px;
}

.cf-heading-line>span {
    display: inline-block;
    transform: translateY(115%);
}

.sowkar-contact-form-section.is-visible .cf-heading-line>span,
.sowkar-contact-form-section.in-view .cf-heading-line>span {
    animation: cTextReveal .95s cubic-bezier(.16, 1, .3, 1) .35s forwards;
}

.cf-heading em {
    font-style: normal;
    font-weight: 800;
    color: var(--sowkar-red);
}

.cf-intro {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.8;
    color: var(--sowkar-muted);
    opacity: 0;
    transform: translateY(22px);
}

.sowkar-contact-form-section.is-visible .cf-intro,
.sowkar-contact-form-section.in-view .cf-intro {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .50s forwards;
}

.cf-split {
    display: grid;
    grid-template-columns: 1.15fr 1fr;
    gap: 30px;
    align-items: stretch;
}

/* Form card */
.cf-form-card {
    position: relative;
    padding: 45px 42px 42px;
    background: #ffffff;
    border: 1px solid rgba(53, 18, 79, 0.10);
    border-radius: 20px;
    box-shadow: 0 24px 60px rgba(53, 18, 79, 0.09);
    overflow: hidden;
    opacity: 0;
    transform: translateY(28px);
}

.sowkar-contact-form-section.is-visible .cf-form-card,
.sowkar-contact-form-section.in-view .cf-form-card {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .62s forwards;
}

.cf-form-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 80px;
    height: 4px;
    background: linear-gradient(90deg, var(--sowkar-red), var(--sowkar-purple));
    border-radius: 0 0 4px 0;
}

.cf-form-title {
    margin: 0 0 8px;
    font-family: "Urbanist", sans-serif;
    font-size: 22px;
    font-weight: 700;
    color: var(--sowkar-navy);
}

.cf-form-sub {
    margin: 0 0 30px;
    font-family: "Montserrat", sans-serif;
    font-size: 12.5px;
    line-height: 1.7;
    color: var(--sowkar-muted);
}

.cf-form-sub span {
    color: var(--sowkar-red);
}

.cf-form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
}

.cf-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.cf-field.full {
    grid-column: 1 / -1;
}

.cf-field label {
    font-family: "Montserrat", sans-serif;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

.cf-field label span {
    color: var(--sowkar-red);
}

.cf-field input,
.cf-field select,
.cf-field textarea {
    width: 100%;
    padding: 14px 16px;
    background: #FBF8F5;
    border: 1px solid rgba(53, 18, 79, 0.12);
    border-radius: 10px;
    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    font-weight: 500;
    color: var(--sowkar-text);
    outline: none;
    transition: border-color .3s ease, background .3s ease, box-shadow .3s ease;
    -webkit-appearance: none;
    appearance: none;
}

.cf-field select {
    background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3e%3cpath fill='none' stroke='%23817485' stroke-linecap='round' stroke-linejoin='round' stroke-width='2' d='m2 5 6 6 6-6'/%3e%3c/svg%3e");
    background-repeat: no-repeat;
    background-position: right 16px center;
    background-size: 13px;
    padding-right: 42px;
    cursor: pointer;
}

.cf-field textarea {
    min-height: 130px;
    resize: vertical;
    line-height: 1.7;
}

.cf-field input::placeholder,
.cf-field textarea::placeholder {
    color: #B4A8B8;
    font-weight: 400;
}

.cf-field input:focus,
.cf-field select:focus,
.cf-field textarea:focus {
    background: #ffffff;
    border-color: var(--sowkar-red);
    box-shadow: 0 0 0 4px rgba(201, 75, 92, 0.10);
}

/* =====================================================
   CONTACT FORM CAPTCHA (CHECKBOX STYLE)
===================================================== */
.cf-captcha-field {
    margin-top: 4px;
    margin-bottom: 4px;
}

.cf-captcha-card {
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    width: 302px;
    max-width: 100%;
    min-height: 76px;
    padding: 10px 14px;
    background: #f9f9f9;
    border: 1px solid #d3d3d3;
    border-radius: 4px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
    cursor: pointer;
    user-select: none;
    position: relative;
    box-sizing: border-box;
    transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;
}

.cf-captcha-card:hover {
    border-color: #c1c1c1;
    background: #fafafa;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.10);
}

.cf-captcha-card:focus-visible {
    outline: 2px solid #4285F4;
    outline-offset: 2px;
}

.cf-captcha-card.is-verified {
    border-color: #2e7d32;
    background: #fdfdfd;
    cursor: default;
}

.cf-captcha-card.has-error {
    border-color: #d32f2f;
    box-shadow: 0 0 0 3px rgba(211, 47, 47, 0.15);
}

#cfCaptchaCheckbox {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
    pointer-events: none;
    margin: 0;
}

.cf-captcha-left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.cf-captcha-checkbox-box {
    width: 26px;
    height: 26px;
    background: #ffffff;
    border: 2px solid #c1c1c1;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    flex-shrink: 0;
    transition: border-color .2s ease, background .2s ease;
}

.cf-captcha-card:hover .cf-captcha-checkbox-box {
    border-color: #a6a6a6;
}

.cf-captcha-spinner {
    display: none;
    width: 20px;
    height: 20px;
    border: 2.5px solid rgba(66, 133, 244, 0.2);
    border-top-color: #4285F4;
    border-radius: 50%;
    animation: cfCaptchaSpin 0.75s linear infinite;
}

.cf-captcha-card.is-verifying .cf-captcha-spinner {
    display: block;
}

.cf-captcha-card.is-verifying .cf-captcha-checkbox-box {
    border-color: transparent;
    background: transparent;
}

.cf-captcha-check-icon {
    display: none;
    color: #0f9d58;
    font-size: 22px;
    line-height: 1;
    font-weight: bold;
}

.cf-captcha-card.is-verified .cf-captcha-check-icon {
    display: block;
    animation: cfCaptchaPop .25s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.cf-captcha-card.is-verified .cf-captcha-checkbox-box {
    border-color: #0f9d58;
    background: #ffffff;
}

.cf-captcha-label {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
    font-size: 14px !important;
    font-weight: 500 !important;
    color: #222222 !important;
    letter-spacing: 0 !important;
    text-transform: none !important;
    cursor: pointer;
    margin: 0;
    user-select: none;
}

.cf-captcha-card.is-verified .cf-captcha-label {
    cursor: default;
}

.cf-captcha-right {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding-left: 10px;
    text-align: center;
    gap: 2px;
}

.cf-captcha-logo {
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 0;
}

.cf-captcha-brand {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1px;
}

.cf-captcha-brand-title {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    font-size: 9.5px;
    font-weight: 700;
    color: #555555;
    letter-spacing: 0.2px;
    line-height: 1.1;
}

.cf-captcha-terms {
    display: flex;
    align-items: center;
    gap: 4px;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    font-size: 8.5px;
    color: #777777;
    line-height: 1;
}

.cf-captcha-terms a {
    color: #555555;
    text-decoration: none;
    transition: text-decoration .15s ease;
}

.cf-captcha-terms a:hover {
    text-decoration: underline;
}

.cf-captcha-error-msg {
    display: none;
    font-family: "Montserrat", sans-serif;
    font-size: 11.5px;
    font-weight: 600;
    color: #d32f2f;
    margin-top: 6px;
    padding-left: 2px;
}

@keyframes cfCaptchaSpin {
    0% {
        transform: rotate(0deg);
    }

    100% {
        transform: rotate(360deg);
    }
}

@keyframes cfCaptchaPop {
    0% {
        transform: scale(0.4);
        opacity: 0;
    }

    100% {
        transform: scale(1);
        opacity: 1;
    }
}

.cf-form-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    flex-wrap: wrap;
    margin-top: 28px;
}

.cf-form-note {
    display: flex;
    align-items: center;
    gap: 9px;
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 500;
    color: var(--sowkar-muted);
    /* max-width: 300px; */
    line-height: 1.55;
}

.cf-form-note i {
    color: var(--sowkar-red);
    font-size: 14px;
    flex-shrink: 0;
}

.cf-submit-btn {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 15px 32px;
    background: linear-gradient(100deg, var(--sowkar-red), var(--sowkar-purple));
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 6px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    cursor: pointer;
    overflow: hidden;
    box-shadow: 0 14px 32px rgba(201, 75, 92, 0.28);
    transition: transform .35s ease, box-shadow .35s ease;
}

.cf-submit-btn::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, var(--sowkar-purple), var(--sowkar-red));
    opacity: 0;
    transition: opacity .4s ease;
    z-index: 1;
}

.cf-submit-btn span,
.cf-submit-btn i {
    position: relative;
    z-index: 2;
    transition: transform .3s ease;
}

.cf-submit-btn:hover {
    transform: translateY(-3px);
    box-shadow: 0 20px 44px rgba(201, 75, 92, 0.42);
}

.cf-submit-btn:hover::before {
    opacity: 1;
}

.cf-submit-btn:hover i {
    transform: translate(3px, -3px);
}

/* Form success message */
.cf-form-success {
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 40px 20px;
    min-height: 380px;
}

.cf-form-success.is-visible {
    display: flex;
}

.cf-form-card.is-submitted .cf-form-inner {
    display: none;
}

.cf-success-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: rgba(201, 75, 92, 0.10);
    border: 1px solid rgba(201, 75, 92, 0.25);
    color: var(--sowkar-red);
    font-size: 36px;
    margin-bottom: 22px;
}

.cf-form-success h3 {
    margin: 0 0 10px;
    font-family: "Urbanist", sans-serif;
    font-size: 24px;
    font-weight: 700;
    color: var(--sowkar-navy);
}

.cf-form-success p {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    line-height: 1.75;
    color: var(--sowkar-muted);
    max-width: 360px;
}

/* Map card */
.cf-map-card {
    position: relative;
    display: flex;
    flex-direction: column;
    border-radius: 20px;
    overflow: hidden;
    border: 1px solid rgba(53, 18, 79, 0.10);
    box-shadow: 0 24px 60px rgba(53, 18, 79, 0.09);
    background: #ffffff;
    opacity: 0;
    transform: translateY(28px);
}

.sowkar-contact-form-section.is-visible .cf-map-card,
.sowkar-contact-form-section.in-view .cf-map-card {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .76s forwards;
}

/* Map Header with Tabs */
.cf-map-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    padding: 14px 20px;
    background: linear-gradient(135deg, #1f0b2a 0%, #35124f 100%);
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    position: relative;
    z-index: 5;
}

.cf-map-title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-family: "Urbanist", sans-serif;
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 0.5px;
    color: #ffffff;
}

.cf-map-title i {
    color: var(--sowkar-red-light);
    font-size: 15px;
}

.cf-map-tabs {
    display: inline-flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.08);
    padding: 4px;
    border-radius: 30px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    gap: 4px;
}

.cf-map-tab {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 7px 16px;
    border-radius: 20px;
    border: 0;
    background: transparent;
    color: rgba(255, 255, 255, 0.75);
    font-family: "Montserrat", sans-serif;
    font-size: 11.5px;
    font-weight: 600;
    cursor: pointer;
    transition: all .25s ease;
    white-space: nowrap;
    outline: none;
    user-select: none;
}

.cf-map-tab em {
    font-style: normal;
    font-size: 10px;
    opacity: 0.75;
    font-weight: 500;
}

.cf-map-tab .cf-map-tab-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.35);
    transition: all .25s ease;
}

.cf-map-tab:hover {
    color: #ffffff;
    background: rgba(255, 255, 255, 0.12);
}

.cf-map-tab.active {
    background: linear-gradient(135deg, var(--sowkar-red), #df5b6e);
    color: #ffffff;
    box-shadow: 0 4px 14px rgba(201, 75, 92, 0.40);
}

.cf-map-tab.active .cf-map-tab-dot {
    background: #ffffff;
    box-shadow: 0 0 6px rgba(255, 255, 255, 0.9);
}

.cf-map-frame {
    position: relative;
    flex: 1;
    min-height: 340px;
    background: #EFE6EE;
    overflow: hidden;
}

.cf-map-panel {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity .35s ease, visibility .35s ease;
}

.cf-map-panel.active {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    z-index: 2;
}

.cf-map-panel iframe {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    border: 0;
    filter: saturate(0.9) contrast(1.02);
}

.cf-map-overlay {
    position: absolute;
    bottom: 18px;
    left: 18px;
    right: 18px;
    z-index: 3;
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 16px 20px;
    background: rgba(22, 11, 32, 0.88);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 14px;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

.cf-map-overlay-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    border-radius: 12px;
    background: linear-gradient(135deg, var(--sowkar-red), var(--sowkar-purple));
    color: #ffffff;
    font-size: 18px;
    flex-shrink: 0;
}

.cf-map-overlay-text {
    flex: 1;
    min-width: 0;
}

.cf-map-overlay-text strong {
    display: block;
    font-family: "Urbanist", sans-serif;
    font-size: 14px;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 2px;
}

.cf-map-overlay-text span {
    display: block;
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 400;
    line-height: 1.5;
    color: rgba(255, 255, 255, 0.72);
}

.cf-map-overlay-link {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.10);
    border: 1px solid rgba(255, 255, 255, 0.18);
    color: #ffffff;
    font-size: 15px;
    flex-shrink: 0;
    transition: background .3s ease, transform .3s ease, color .3s ease;
}

.cf-map-overlay-link:hover {
    background: var(--sowkar-red);
    color: #ffffff;
    transform: rotate(45deg);
}

.cf-map-info {
    padding: 22px 24px;
    background: #ffffff;
    border-top: 1px solid rgba(53, 18, 79, 0.08);
}

.cf-map-info-content {
    display: none;
    animation: cFadeIn .35s ease forwards;
}

.cf-map-info-content.active {
    display: block;
}

@keyframes cFadeIn {
    from {
        opacity: 0;
        transform: translateY(4px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.cf-map-info-row {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 11px 0;
    border-bottom: 1px dashed rgba(53, 18, 79, 0.10);
}

.cf-map-info-row:last-child {
    border-bottom: 0;
}

.cf-map-info-row:first-child {
    padding-top: 0;
}

.cf-map-info-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: rgba(201, 75, 92, 0.08);
    border: 1px solid rgba(201, 75, 92, 0.18);
    color: var(--sowkar-red);
    font-size: 15px;
    flex-shrink: 0;
}

.cf-map-info-text strong {
    display: block;
    font-family: "Montserrat", sans-serif;
    font-size: 9.5px;
    font-weight: 700;
    letter-spacing: 1.6px;
    text-transform: uppercase;
    color: var(--sowkar-muted);
    margin-bottom: 3px;
}

.cf-map-info-text p,
.cf-map-info-text a {
    display: block;
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 12.5px;
    font-weight: 600;
    line-height: 1.55;
    color: var(--sowkar-navy);
    text-decoration: none;
    transition: color .3s ease;
}

.cf-map-info-text a:hover {
    color: var(--sowkar-red);
}

/* SECTION 3 – FAQ */
.sowkar-contact-faq {
    position: relative;
    width: 100%;
    padding: 100px 0 110px;
    background: #ffffff;
    overflow: hidden;
    isolation: isolate;
}

.sowkar-contact-faq::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(rgba(53, 18, 79, 0.03) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
    z-index: 0;
}

.faq-glow-left,
.faq-glow-right {
    position: absolute;
    border-radius: 50%;
    filter: blur(80px);
    pointer-events: none;
    z-index: 0;
}

.faq-glow-left {
    top: 10%;
    left: -130px;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(155, 63, 143, 0.06) 0%, transparent 70%);
}

.faq-glow-right {
    bottom: 5%;
    right: -130px;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.06) 0%, transparent 70%);
}

.sowkar-contact-faq .container {
    position: relative;
    z-index: 2;
}

.faq-layout {
    display: grid;
    grid-template-columns: 0.85fr 1.15fr;
    gap: 60px;
    align-items: start;
}

.faq-side {
    position: sticky;
    top: 110px;
}

.faq-kicker {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.faq-kicker-line {
    width: 30px;
    height: 1px;
    background: var(--sowkar-red);
    opacity: .55;
    transform-origin: left;
    transform: scaleX(0);
}

.sowkar-contact-faq.is-visible .faq-kicker-line,
.sowkar-contact-faq.in-view .faq-kicker-line {
    transform: scaleX(1);
    transition: transform .6s cubic-bezier(.16, 1, .3, 1) .25s;
}

.faq-eyebrow {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3.6px;
    text-transform: uppercase;
    color: var(--sowkar-red);
    opacity: 0;
    transform: translateY(-14px);
}

.sowkar-contact-faq.is-visible .faq-eyebrow,
.sowkar-contact-faq.in-view .faq-eyebrow {
    animation: cFadeDown .75s cubic-bezier(.16, 1, .3, 1) .15s forwards;
}

.faq-heading {
    margin: 0 0 20px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(30px, 3.4vw, 46px);
    font-weight: 300;
    line-height: 1.08;
    letter-spacing: -1.5px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

.faq-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 4px;
}

.faq-heading-line>span {
    display: inline-block;
    transform: translateY(115%);
}

.sowkar-contact-faq.is-visible .faq-heading-line>span,
.sowkar-contact-faq.in-view .faq-heading-line>span {
    animation: cTextReveal .95s cubic-bezier(.16, 1, .3, 1) .35s forwards;
}

.faq-heading em {
    font-style: normal;
    font-weight: 800;
    color: var(--sowkar-red);
}

.faq-side p {
    margin: 0 0 26px;
    font-family: "Montserrat", sans-serif;
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.8;
    color: var(--sowkar-muted);
    opacity: 0;
    transform: translateY(22px);
}

.sowkar-contact-faq.is-visible .faq-side p,
.sowkar-contact-faq.in-view .faq-side p {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .50s forwards;
}

.faq-side-cta {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 13px 24px;
    background: linear-gradient(100deg, var(--sowkar-navy), var(--sowkar-deep));
    border: 1px solid rgba(53, 18, 79, 0.20);
    border-radius: 6px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    text-decoration: none;
    opacity: 0;
    transform: translateY(22px);
    transition: transform .35s ease, box-shadow .35s ease, background .35s ease;
}

.sowkar-contact-faq.is-visible .faq-side-cta,
.sowkar-contact-faq.in-view .faq-side-cta {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .62s forwards;
}

.faq-side-cta i {
    transition: transform .3s ease;
}

.faq-side-cta:hover {
    color: #ffffff;
    transform: translateY(-3px);
    background: linear-gradient(100deg, var(--sowkar-red), var(--sowkar-purple));
    box-shadow: 0 18px 40px rgba(201, 75, 92, 0.32);
}

.faq-side-cta:hover i {
    transform: translate(3px, -3px);
}

.faq-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.faq-item {
    position: relative;
    background: #ffffff;
    border: 1px solid rgba(53, 18, 79, 0.10);
    border-radius: 14px;
    overflow: hidden;
    opacity: 0;
    transform: translateY(24px);
    transition: border-color .4s ease, box-shadow .4s ease, transform .4s ease;
}

.sowkar-contact-faq.is-visible .faq-item:nth-child(1),
.sowkar-contact-faq.in-view .faq-item:nth-child(1) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .45s forwards;
}

.sowkar-contact-faq.is-visible .faq-item:nth-child(2),
.sowkar-contact-faq.in-view .faq-item:nth-child(2) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .55s forwards;
}

.sowkar-contact-faq.is-visible .faq-item:nth-child(3),
.sowkar-contact-faq.in-view .faq-item:nth-child(3) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .65s forwards;
}

.sowkar-contact-faq.is-visible .faq-item:nth-child(4),
.sowkar-contact-faq.in-view .faq-item:nth-child(4) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .75s forwards;
}

.sowkar-contact-faq.is-visible .faq-item:nth-child(5),
.sowkar-contact-faq.in-view .faq-item:nth-child(5) {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .85s forwards;
}

.faq-item:hover {
    border-color: rgba(201, 75, 92, 0.30);
    box-shadow: 0 14px 36px rgba(53, 18, 79, 0.08);
}

.faq-item.is-open {
    border-color: rgba(201, 75, 92, 0.40);
    box-shadow: 0 18px 44px rgba(53, 18, 79, 0.10);
}

.faq-item::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 3px;
    height: 100%;
    background: linear-gradient(180deg, var(--sowkar-red), var(--sowkar-purple));
    opacity: 0;
    transition: opacity .35s ease;
}

.faq-item.is-open::before,
.faq-item:hover::before {
    opacity: 1;
}

.faq-question {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    width: 100%;
    padding: 22px 26px;
    background: transparent;
    border: 0;
    text-align: left;
    cursor: pointer;
    font-family: "Urbanist", sans-serif;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.4;
    color: var(--sowkar-navy);
    transition: color .3s ease;
}

.faq-item:hover .faq-question,
.faq-item.is-open .faq-question {
    color: var(--sowkar-red);
}

.faq-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: rgba(201, 75, 92, 0.08);
    border: 1px solid rgba(201, 75, 92, 0.20);
    color: var(--sowkar-red);
    font-size: 15px;
    flex-shrink: 0;
    transition: background .4s ease, color .4s ease, transform .4s ease, border-color .4s ease;
}

.faq-item.is-open .faq-icon {
    background: linear-gradient(135deg, var(--sowkar-red), var(--sowkar-purple));
    color: #ffffff;
    border-color: transparent;
    transform: rotate(180deg);
}

.faq-answer {
    max-height: 0;
    overflow: hidden;
    transition: max-height .5s cubic-bezier(.16, 1, .3, 1);
}

.faq-answer-inner {
    padding: 0 26px 24px;
    font-family: "Montserrat", sans-serif;
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.85;
    color: var(--sowkar-muted);
    border-top: 1px dashed rgba(53, 18, 79, 0.10);
    padding-top: 18px;
}

/* SECTION 4 – CTA BANNER */
.sowkar-contact-cta {
    position: relative;
    width: 100%;
    padding: 0 0 110px;
    background: #ffffff;
}

.sowkar-contact-cta .container {
    position: relative;
    z-index: 2;
}

.cta-box {
    position: relative;
    display: grid;
    grid-template-columns: 1.4fr 1fr;
    gap: 40px;
    align-items: center;
    padding: 60px 60px;
    background:
        radial-gradient(circle at 90% 20%, rgba(155, 63, 143, 0.24), transparent 45%),
        radial-gradient(circle at 10% 90%, rgba(201, 75, 92, 0.22), transparent 42%),
        linear-gradient(140deg, #0c0612 0%, #1a0b22 50%, #22102c 100%);
    border-radius: 24px;
    overflow: hidden;
    isolation: isolate;
    box-shadow: 0 30px 70px rgba(53, 18, 79, 0.25);
    opacity: 0;
    transform: translateY(30px);
}

.sowkar-contact-cta.is-visible .cta-box,
.sowkar-contact-cta.in-view .cta-box {
    animation: cFadeUp .95s cubic-bezier(.16, 1, .3, 1) .10s forwards;
}

.cta-box::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(to right, rgba(234, 220, 240, 0.04) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(234, 220, 240, 0.04) 1px, transparent 1px);
    background-size: 48px 48px;
    mask-image: radial-gradient(ellipse at 50% 50%, black 30%, transparent 80%);
    -webkit-mask-image: radial-gradient(ellipse at 50% 50%, black 30%, transparent 80%);
    pointer-events: none;
    z-index: 1;
}

.cta-content {
    position: relative;
    z-index: 3;
}

.cta-kicker {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    opacity: 0;
    transform: translateY(-14px);
}

.sowkar-contact-cta.is-visible .cta-kicker,
.sowkar-contact-cta.in-view .cta-kicker {
    animation: cFadeDown .75s cubic-bezier(.16, 1, .3, 1) .25s forwards;
}

.cta-kicker-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #C94B5C;
    box-shadow: 0 0 12px #C94B5C;
    animation: cDotGlow 2s infinite ease-in-out;
}

.cta-kicker-text {
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 3.2px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.72);
}

.cta-title {
    margin: 0 0 14px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(28px, 3.2vw, 44px);
    font-weight: 300;
    line-height: 1.1;
    letter-spacing: -1.4px;
    text-transform: uppercase;
    color: #ffffff;
}

.cta-title-line {
    display: block;
    overflow: hidden;
    padding-bottom: 4px;
}

.cta-title-line>span {
    display: inline-block;
    transform: translateY(115%);
}

.sowkar-contact-cta.is-visible .cta-title-line>span,
.sowkar-contact-cta.in-view .cta-title-line>span {
    animation: cTextReveal .95s cubic-bezier(.16, 1, .3, 1) .40s forwards;
}

.cta-title em {
    font-style: normal;
    font-weight: 800;
    color: #E77A88;
}

.cta-text {
    margin: 0;
    max-width: 480px;
    font-family: "Montserrat", sans-serif;
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.8;
    color: #C9B8D0;
    opacity: 0;
    transform: translateY(22px);
}

.sowkar-contact-cta.is-visible .cta-text,
.sowkar-contact-cta.in-view .cta-text {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .55s forwards;
}

.cta-buttons {
    position: relative;
    z-index: 3;
    display: flex;
    flex-direction: column;
    gap: 12px;
    align-items: stretch;
    opacity: 0;
    transform: translateY(22px);
}

.sowkar-contact-cta.is-visible .cta-buttons,
.sowkar-contact-cta.in-view .cta-buttons {
    animation: cFadeUp .85s cubic-bezier(.16, 1, .3, 1) .70s forwards;
}

.cta-btn-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 16px 28px;
    background: linear-gradient(100deg, var(--sowkar-red), var(--sowkar-purple));
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 6px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    text-decoration: none;
    box-shadow: 0 14px 32px rgba(0, 0, 0, 0.30);
    transition: transform .35s ease, box-shadow .35s ease;
}

.cta-btn-primary i {
    transition: transform .3s ease;
}

.cta-btn-primary:hover {
    color: #ffffff;
    transform: translateY(-3px);
    box-shadow: 0 20px 44px rgba(201, 75, 92, 0.42);
}

.cta-btn-primary:hover i {
    transform: translate(3px, -3px);
}

.cta-btn-glass {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 16px 28px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 6px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    text-decoration: none;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: background .3s ease, border-color .3s ease, transform .3s ease;
}

.cta-btn-glass:hover {
    color: #ffffff;
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(201, 75, 92, 0.45);
    transform: translateY(-3px);
