/* SECTION 1: GALLERY HERO — LEFT TEXT + RIGHT SHAPED IMAGE */
.sowkar-gal-hero {
    position: relative;
    width: 100%;
    height: clamp(520px, 75vh, 660px);
    min-height: 520px;
    max-height: 75vh;
    padding: 30px 0;
    display: flex;
    align-items: center;
    overflow: hidden;
    isolation: isolate;
    background:
        radial-gradient(circle at 85% 25%, rgba(155, 63, 143, 0.22), transparent 42%),
        radial-gradient(circle at 12% 82%, rgba(201, 75, 92, 0.18), transparent 40%),
        linear-gradient(140deg, #0c0612 0%, #1a0b22 50%, #22102c 100%);
}

.sowkar-gal-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(to right, rgba(234, 220, 240, 0.04) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(234, 220, 240, 0.04) 1px, transparent 1px);
    background-size: 52px 52px;
    -webkit-mask-image: radial-gradient(ellipse at 60% 45%, black 30%, transparent 78%);
    mask-image: radial-gradient(ellipse at 60% 45%, black 30%, transparent 78%);
    pointer-events: none;
    z-index: 1;
}

.sowkar-gal-hero::after {
    content: "";
    position: absolute;
    top: -12%;
    right: 5%;
    width: 720px;
    height: 720px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.13) 0%, rgba(155, 63, 143, 0.05) 45%, transparent 72%);
    filter: blur(70px);
    pointer-events: none;
    z-index: 1;
    animation: sghAmbientShift 12s ease-in-out infinite alternate;
}

@keyframes sghAmbientShift {
    0% {
        transform: scale(1) translate(0, 0);
        opacity: .55;
    }

    100% {
        transform: scale(1.15) translate(-40px, 30px);
        opacity: 1;
    }
}

.sowkar-gal-hero .container {
    position: relative;
    z-index: 10;
}

.sgh-split {
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    gap: clamp(30px, 4vw, 55px);
    align-items: center;
}

.sgh-left {
    max-width: 620px;
}

.sgh-breadcrumb {
    display: inline-block;
    margin-bottom: 14px;
    opacity: 0;
    animation: sghFadeDown 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.15s forwards;
}

.sgh-crumb-list {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 6px 18px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 40px;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    list-style: none;
    margin: 0;
}

.sgh-crumb-item {
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
}

.sgh-crumb-item a {
