}

.sgh-hero-label {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    opacity: 0;
    animation: sghFadeDown 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.3s forwards;
}

.sgh-label-pill {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #C94B5C;
    box-shadow: 0 0 10px #C94B5C;
    animation: sghDotGlow 2s infinite ease-in-out;
}

@keyframes sghDotGlow {

    0%,
    100% {
        transform: scale(1);
        opacity: 0.8;
        box-shadow: 0 0 6px #C94B5C;
    }

    50% {
        transform: scale(1.3);
        opacity: 1;
        box-shadow: 0 0 14px #E77A88;
    }
}

.sgh-label-text {
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 3.6px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.72);
}

.sgh-label-line {
    width: 52px;
    height: 1px;
    background: linear-gradient(90deg, #C94B5C, #C98BC2);
}

.sgh-hero-heading {
    margin: 0 0 6px;
    max-width: 620px;
