}

.sgh-hero-actions {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
    opacity: 0;
    animation: sghFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) 1.02s forwards;
}

.sgh-btn-primary {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 13px 26px;
    background: linear-gradient(100deg, #9B3F8F, #C94B5C);
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 4px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 1.9px;
    text-transform: uppercase;
    text-decoration: none;
    box-shadow: 0 14px 32px rgba(0, 0, 0, 0.32);
    transition: transform .35s ease, box-shadow .35s ease;
    overflow: hidden;
}

.sgh-btn-primary::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, #C94B5C, #E77A88);
    opacity: 0;
    transition: opacity .4s ease;
    z-index: 1;
}

.sgh-btn-primary span,
.sgh-btn-primary i {
    position: relative;
    z-index: 2;
    transition: transform .3s ease;
}

.sgh-btn-primary:hover {
    color: #ffffff;
    transform: translateY(-3px);
    box-shadow: 0 20px 44px rgba(201, 75, 92, 0.42);
}

.sgh-btn-primary:hover::before {
    opacity: 1;
}

.sgh-btn-primary:hover i {
    transform: translate(3px, -3px);
}

.sgh-btn-glass {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 13px 24px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 4px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 1.6px;
    text-transform: uppercase;
    text-decoration: none;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: background .3s, border-color .3s, transform .3s;
}

.sgh-btn-glass:hover {
    color: #ffffff;
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(201, 75, 92, 0.4);
    transform: translateY(-3px);
}

.sgh-right {
    position: relative;
    height: clamp(320px, 38vh, 420px);
    max-width: 480px;
    width: 100%;
    margin-left: auto;
    opacity: 0;
    animation: sghFadeUp 1s cubic-bezier(0.16, 1, 0.3, 1) 0.6s forwards;
}

.sgh-visual {
    position: relative;
    width: 100%;
    height: 100%;
}

.sgh-main-shape {
    position: absolute;
    top: 0;
    left: 5%;
    width: 78%;
    height: 78%;
    border-radius: 62% 38% 55% 45% / 55% 48% 52% 45%;
    overflow: hidden;
    box-shadow: 0 30px 70px rgba(0, 0, 0, 0.45);
    animation: sghShapeMorph 14s ease-in-out infinite alternate;
    z-index: 2;
}

@keyframes sghShapeMorph {
    0% {
        border-radius: 62% 38% 55% 45% / 55% 48% 52% 45%;
        transform: rotate(0deg) scale(1);
    }

    50% {
        border-radius: 48% 52% 42% 58% / 52% 60% 40% 48%;
        transform: rotate(-2deg) scale(1.02);
    }

    100% {
        border-radius: 55% 45% 60% 40% / 45% 55% 45% 55%;
        transform: rotate(2deg) scale(1.01);
    }
}

.sgh-main-shape img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transform: scale(1.05);
    animation: sghImageZoom 16s ease-in-out infinite alternate;
}

@keyframes sghImageZoom {
    0% {
        transform: scale(1.05);
    }

    100% {
        transform: scale(1.15);
    }
}

.sgh-main-shape::after {
    content: "";
    position: absolute;
    inset: 0;
    background:
        linear-gradient(200deg, rgba(155, 63, 143, 0.22) 0%, transparent 45%),
        linear-gradient(20deg, rgba(201, 75, 92, 0.22) 0%, transparent 50%);
    pointer-events: none;
    z-index: 3;
    mix-blend-mode: overlay;
}

.sgh-secondary-shape {
    position: absolute;
    bottom: 4%;
    right: 2%;
    width: 42%;
    height: 42%;
    border-radius: 50%;
    overflow: hidden;
    border: 4px solid rgba(255, 255, 255, 0.10);
    box-shadow: 0 25px 55px rgba(0, 0, 0, 0.40);
    animation: sghFloat 6s ease-in-out infinite;
    z-index: 4;
}

@keyframes sghFloat {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-14px);
    }
}

.sgh-secondary-shape img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
}

.sgh-ring {
    position: absolute;
    top: 8%;
    left: 50%;
    transform: translateX(-50%);
    width: 92%;
    height: 92%;
    border-radius: 50%;
    border: 1px dashed rgba(201, 75, 92, 0.28);
    animation: sghRingSpin 40s linear infinite;
    z-index: 1;
    pointer-events: none;
}

@keyframes sghRingSpin {
    0% {
        transform: translateX(-50%) rotate(0deg);
    }

    100% {
        transform: translateX(-50%) rotate(360deg);
    }
}

.sgh-accent-dot {
    position: absolute;
    top: 8%;
    right: 8%;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: #E77A88;
    box-shadow:
        0 0 0 8px rgba(231, 122, 136, 0.14),
        0 0 24px rgba(231, 122, 136, 0.55);
    animation: sghDotGlow 2.5s infinite ease-in-out;
    z-index: 5;
}

.sgh-stats-badge {
    position: absolute;
