}

.sgh-stats-badge-text span {
    font-family: "Montserrat", sans-serif;
    font-size: 8.5px;
    font-weight: 600;
    letter-spacing: 1.6px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.62);
}

.sgh-corner {
    position: absolute;
    width: 90px;
    height: 90px;
    z-index: 5;
    pointer-events: none;
    opacity: 0;
    animation: sghFadeIn 1.2s cubic-bezier(0.16, 1, 0.3, 1) 1.4s forwards;
}

.sgh-corner-tl {
    top: 34px;
    left: 34px;
    border-top: 1px solid rgba(234, 220, 240, 0.32);
    border-left: 1px solid rgba(234, 220, 240, 0.32);
}

.sgh-corner-tr {
    top: 34px;
    right: 34px;
    border-top: 1px solid rgba(234, 220, 240, 0.32);
    border-right: 1px solid rgba(201, 75, 92, 0.55);
}

.sgh-corner-bl {
    bottom: 34px;
    left: 34px;
    border-bottom: 1px solid rgba(234, 220, 240, 0.32);
    border-left: 1px solid rgba(201, 75, 92, 0.55);
}

.sgh-corner-br {
    bottom: 34px;
    right: 34px;
    border-bottom: 1px solid rgba(234, 220, 240, 0.32);
    border-right: 1px solid rgba(234, 220, 240, 0.32);
}

.sgh-corner-dot {
    position: absolute;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #E77A88;
    box-shadow: 0 0 0 5px rgba(231, 122, 136, 0.14);
}

.sgh-corner-tr .sgh-corner-dot {
    top: 14px;
    right: 14px;
}

.sgh-corner-bl .sgh-corner-dot {
    bottom: 14px;
    left: 14px;
}

@keyframes sghFadeIn {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

@keyframes sghFadeDown {
    from {
        opacity: 0;
        transform: translateY(-16px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes sghFadeUp {
    from {
        opacity: 0;
        transform: translateY(24px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes sghTextReveal {
    to {
        transform: translateY(0);
    }
}

/* SECTION 2: MASONRY GALLERY — SPACED GRID, FULL-BLEED IMAGES */
.sowkar-gal-grid-section {
    position: relative;
    width: 100%;
    padding: 70px 0 110px;
    background: #FFFFFF;
    overflow: hidden;
}

.sowkar-gal-grid-section .container {
    position: relative;
    z-index: 2;
}

.gal-intro-line {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    margin-bottom: 50px;
    text-align: center;
    opacity: 0;
    transform: translateY(-16px);
}

.sowkar-gal-grid-section.is-visible .gal-intro-line {
    animation: sghFadeDown 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.15s forwards;
}

.gal-intro-line .line {
    width: 60px;
    height: 1px;
    background: linear-gradient(90deg, transparent, #C94B5C, transparent);
    transform-origin: center;
    transform: scaleX(0);
    transition: transform 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.25s;
}

.sowkar-gal-grid-section.is-visible .gal-intro-line .line {
    transform: scaleX(1);
}

.gal-intro-line .text {
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 3.2px;
    text-transform: uppercase;
    color: #817485;
}

.gal-intro-line .text strong {
    color: #35124F;
    font-weight: 800;
}

/* Masonry grid with natural aspect ratios */
.gal-masonry {
    column-count: 3;
    column-gap: 20px;
    display: block;
}

.gal-masonry-single {
    display: flex;
    justify-content: center;
    align-items: center;
    max-width: 860px;
    margin: 0 auto;
}

.gal-masonry-single .gal-masonry-item {
    width: auto;
    max-width: 100%;
    height: auto;
    margin-bottom: 0;
    display: inline-block;
}

.gal-masonry-single .gal-masonry-item img {
    width: 100%;
    max-width: 860px;
    height: auto;
    display: block;
}

.sowkar-gal-grid-section-alt {
    padding-top: 30px;
    padding-bottom: 90px;
    border-top: 1px solid rgba(53, 18, 79, 0.06);
}

.gal-masonry-item {
    position: relative;
    overflow: hidden;
    border-radius: 14px;
    background: #160B20;
    opacity: 0;
    transform: translateY(24px) scale(0.97);
    cursor: pointer;
    box-shadow: 0 12px 30px -14px rgba(53, 18, 79, 0.25);
    transition: box-shadow 0.5s ease, transform 0.4s ease;
    display: inline-block;
    width: 100%;
    margin-bottom: 20px;
    break-inside: avoid;
    -webkit-column-break-inside: avoid;
    page-break-inside: avoid;
}

.gal-masonry-item:hover {
    box-shadow: 0 24px 55px -18px rgba(53, 18, 79, 0.42);
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item {
    animation: galMasonryReveal 0.85s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(1) {
    animation-delay: 0.04s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(2) {
    animation-delay: 0.08s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(3) {
    animation-delay: 0.12s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(4) {
    animation-delay: 0.16s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(5) {
    animation-delay: 0.20s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(6) {
    animation-delay: 0.24s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(7) {
    animation-delay: 0.28s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(8) {
    animation-delay: 0.32s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(9) {
    animation-delay: 0.36s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(10) {
    animation-delay: 0.40s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(11) {
    animation-delay: 0.44s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(12) {
    animation-delay: 0.48s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(13) {
    animation-delay: 0.52s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(14) {
    animation-delay: 0.56s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(15) {
    animation-delay: 0.60s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(16) {
    animation-delay: 0.64s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(17) {
    animation-delay: 0.68s;
}

.sowkar-gal-grid-section.is-visible .gal-masonry-item:nth-child(18) {
    animation-delay: 0.72s;
}

@keyframes galMasonryReveal {
    from {
        opacity: 0;
        transform: translateY(24px) scale(0.97);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.gal-masonry-item img {
    display: block;
    width: 100%;
    height: auto;
    transition:
        transform 1.1s cubic-bezier(0.16, 1, 0.3, 1),
        filter 0.6s ease;
    filter: brightness(0.97) saturate(1.02);
}

.gal-masonry-item:hover img {
    transform: scale(1.06);
    filter: brightness(1.03) saturate(1.08);
}

/* Subtle gradient overlay for depth & hover */
.gal-masonry-item::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(11, 5, 16, 0.05) 0%, rgba(11, 5, 16, 0.3) 50%, rgba(11, 5, 16, 0.85) 100%);
    opacity: 0;
    transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    pointer-events: none;
    z-index: 2;
}

.gal-masonry-item:hover::after {
    opacity: 1;
}

.gal-item-badge {
    position: absolute;
    top: 14px;
    right: 14px;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.18);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.32);
    color: #FFFFFF;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    opacity: 0;
    transform: scale(0.7) translateY(-6px);
    transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    z-index: 4;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);
}

.gal-masonry-item:hover .gal-item-badge {
    opacity: 1;
    transform: scale(1) translateY(0);
}

.gal-masonry-item:hover .gal-item-badge:hover {
    background: #C94B5C;
    border-color: #C94B5C;
    transform: scale(1.1);
}

.gal-item-caption {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: 24px 16px 14px;
    color: #FFFFFF;
    font-family: "Montserrat", sans-serif;
    font-size: 11.5px;
    font-weight: 600;
    letter-spacing: 0.4px;
    line-height: 1.35;
    z-index: 4;
    opacity: 0;
    transform: translateY(10px);
    transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.7);
}

.gal-masonry-item:hover .gal-item-caption {
    opacity: 1;
    transform: translateY(0);
}

/* SECTION 3: IMAGE PREVIEW MODAL / LIGHTBOX WINDOW */
.sowkar-lightbox {
    position: fixed;
    inset: 0;
    z-index: 99999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    padding: 20px;
    transition: opacity 0.35s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.35s;
}

.sowkar-lightbox.is-open {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
}

.slb-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(8, 3, 13, 0.92);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    cursor: pointer;
}

.slb-dialog {
    position: relative;
    z-index: 2;
    width: min(92vw, 840px);
    max-height: 90vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #12071a;
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 16px;
    box-shadow:
        0 30px 90px rgba(0, 0, 0, 0.85),
        0 0 0 1px rgba(201, 75, 92, 0.3);
    overflow: hidden;
    transform: scale(0.93) translateY(20px);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-lightbox.is-open .slb-dialog {
    transform: scale(1) translateY(0);
}

.slb-media-wrap {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #0d0413;
}

.slb-img {
    display: block;
    width: 100%;
    height: auto;
    max-height: 86vh;
    object-fit: cover;
    opacity: 0;
    transform: scale(0.97);
    transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.slb-img.is-loaded {
    opacity: 1;
    transform: scale(1);
}

.slb-loader {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s;
    z-index: 5;
}

.slb-loader.is-loading {
    opacity: 1;
}

.slb-close-btn {
    position: absolute;
    top: 16px;
    right: 16px;
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: rgba(12, 6, 18, 0.75);
    border: 1px solid rgba(255, 255, 255, 0.25);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    color: #FFFFFF;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 17px;
    cursor: pointer;
    z-index: 20;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
    transition: all 0.25s ease;
}

.slb-close-btn:hover {
    background: #C94B5C;
    border-color: #C94B5C;
    transform: rotate(90deg) scale(1.1);
    color: #FFFFFF;
}

.slb-nav-btn {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: rgba(12, 6, 18, 0.72);
    border: 1px solid rgba(255, 255, 255, 0.22);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    color: #FFFFFF;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    cursor: pointer;
    z-index: 15;
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.45);
}

.slb-prev {
    left: 18px;
}

.slb-next {
    right: 18px;
}

.slb-nav-btn:hover {
    background: linear-gradient(135deg, #9B3F8F, #C94B5C);
    border-color: rgba(255, 255, 255, 0.5);
    transform: translateY(-50%) scale(1.12);
    color: #FFFFFF;
}

/* SECTION 4: GALLERY PAGE CTA SECTION SCROLL REVEAL */
.sowkar-gal-cta {
    position: relative;
}

.sowkar-gal-cta .sowkar-cta-content {
    position: relative;
    z-index: 2;
}

.sowkar-gal-cta .sowkar-cta-label {
    opacity: 0;
    transform: translateY(-16px);
}

.sowkar-gal-cta .sowkar-cta-line {
    transform: scaleX(0);
    transform-origin: center;
}

.sowkar-gal-cta .sowkar-cta-heading .cta-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 4px;
}

.sowkar-gal-cta .sowkar-cta-heading .cta-heading-line>span {
    display: inline-block;
    transform: translateY(115%);
}

.sowkar-gal-cta .sowkar-cta-heading .cta-title-line {
    color: #35124f;
}

.sowkar-gal-cta .sowkar-cta-heading .cta-title-line.cta-highlight {
    color: #c94b5c;
}

.sowkar-gal-cta .sowkar-cta-text {
    opacity: 0;
    transform: translateY(24px);
}

.sowkar-gal-cta .sowkar-cta-buttons {
    opacity: 0;
    transform: translateY(24px);
}

.sowkar-gal-cta.in-view .sowkar-cta-label,
.sowkar-gal-cta.is-visible .sowkar-cta-label {
    animation: sghFadeDown 0.75s cubic-bezier(0.16, 1, 0.3, 1) 0.15s forwards;
}

.sowkar-gal-cta.in-view .sowkar-cta-line,
.sowkar-gal-cta.is-visible .sowkar-cta-line {
    transform: scaleX(1);
    transition: transform 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.25s;
}

.sowkar-gal-cta.in-view .sowkar-cta-heading .cta-heading-line:nth-child(1)>span,
.sowkar-gal-cta.is-visible .sowkar-cta-heading .cta-heading-line:nth-child(1)>span {
    animation: sghTextReveal 0.95s cubic-bezier(0.16, 1, 0.3, 1) 0.38s forwards;
}

.sowkar-gal-cta.in-view .sowkar-cta-heading .cta-heading-line:nth-child(2)>span,
.sowkar-gal-cta.is-visible .sowkar-cta-heading .cta-heading-line:nth-child(2)>span {
    animation: sghTextReveal 0.95s cubic-bezier(0.16, 1, 0.3, 1) 0.52s forwards;
}

.sowkar-gal-cta.in-view .sowkar-cta-text,
.sowkar-gal-cta.is-visible .sowkar-cta-text {
    animation: sghFadeUp 0.85s cubic-bezier(0.16, 1, 0.3, 1) 0.68s forwards;
}

.sowkar-gal-cta.in-view .sowkar-cta-buttons,
.sowkar-gal-cta.is-visible .sowkar-cta-buttons {
    animation: sghFadeUp 0.85s cubic-bezier(0.16, 1, 0.3, 1) 0.84s forwards;
}

