    .gal-intro-line .text {
        font-size: 9px;
        letter-spacing: 2.2px;
    }

    .gal-masonry {
        grid-template-columns: repeat(2, 1fr);
        grid-auto-rows: 150px;
        gap: 12px;
    }

    /* Mobile — clean, solid layout */
    .gal-masonry-item:nth-child(n) {
        grid-column: span 1;
        grid-row: span 2;
    }

    .gal-masonry-item:nth-child(1),
    .gal-masonry-item:nth-child(18) {
        grid-column: span 2;
        grid-row: span 2;
    }
