/* SECTION 1 – HERO */
.sowkar-infra-hero {
    position: relative;
    width: 100%;
    height: 75vh;
    min-height: 520px;
    max-height: 780px;
    overflow: hidden;
    isolation: isolate;
    background:
        radial-gradient(circle at 72% 38%, rgba(155, 63, 143, 0.22), transparent 40%),
        radial-gradient(circle at 88% 18%, rgba(201, 75, 92, 0.18), transparent 30%),
        radial-gradient(circle at 12% 85%, rgba(104, 26, 102, 0.24), transparent 36%),
        linear-gradient(135deg, #0e0714 0%, #1b0c23 48%, #25102d 100%);
}

.sowkar-infra-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(to right, rgba(234, 220, 240, 0.035) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(234, 220, 240, 0.035) 1px, transparent 1px);
    background-size: 46px 46px;
    mask-image: radial-gradient(ellipse at 68% 50%, black 30%, transparent 78%);
    -webkit-mask-image: radial-gradient(ellipse at 68% 50%, black 30%, transparent 78%);
    pointer-events: none;
    z-index: 1;
}

.sowkar-infra-hero::after {
    content: "";
    position: absolute;
    top: -12%;
    right: 24%;
    width: 560px;
    height: 560px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.13) 0%, rgba(155, 63, 143, 0.06) 45%, transparent 70%);
    filter: blur(50px);
    pointer-events: none;
    z-index: 1;
    animation: infraAuraPulse 10s ease-in-out infinite alternate;
}

@keyframes infraAuraPulse {
    0% {
        transform: scale(1) translate(0, 0);
        opacity: .6;
    }

    100% {
