}

.welcome-body p em {
    font-style: normal;
    color: var(--sowkar-red);
    font-weight: 600;
}

.welcome-features {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px 18px;
    margin: 28px 0 34px;
}

.welcome-feature-item {
    position: relative;
    display: flex;
    align-items: center;
    gap: 12px;
