        color .35s ease;
}

.sowkar-welcome-infra.is-visible .welcome-feature-item:nth-child(1) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .72s, 0s, 0s, 0s, 0s, 0s;
}

.sowkar-welcome-infra.is-visible .welcome-feature-item:nth-child(2) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .78s, 0s, 0s, 0s, 0s, 0s;
}

.sowkar-welcome-infra.is-visible .welcome-feature-item:nth-child(3) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .84s, 0s, 0s, 0s, 0s, 0s;
}

.sowkar-welcome-infra.is-visible .welcome-feature-item:nth-child(4) {
    opacity: 1;
    transform: translateY(0);
