}

.sowkar-welcome-infra.is-visible .welcome-feature-item:nth-child(5) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .96s, 0s, 0s, 0s, 0s, 0s;
}

.sowkar-welcome-infra.is-visible .welcome-feature-item:nth-child(6) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 1.02s, 0s, 0s, 0s, 0s, 0s;
}

.sowkar-welcome-infra.is-visible .welcome-feature-item:hover {
    transform: translateX(6px);
    background: linear-gradient(90deg, rgba(201, 75, 92, 0.08) 0%, rgba(155, 63, 143, 0.03) 100%);
    border-color: rgba(201, 75, 92, 0.20);
    box-shadow: 0 4px 18px rgba(201, 75, 92, 0.08);
