    transition: transform .35s cubic-bezier(.16, 1, .3, 1), background .35s ease, color .35s ease, box-shadow .35s ease;
}

.welcome-feature-item:hover i {
    transform: scale(1.2) rotate(8deg);
    background: var(--sowkar-red);
    color: #ffffff;
    box-shadow: 0 3px 10px rgba(201, 75, 92, 0.35);
}

.welcome-cta {
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
    min-width: 240px;
    height: 54px;
    padding: 0 8px 0 26px;
    background: var(--sowkar-navy);
