.sowkar-welcome-infra.is-visible .welcome-cta {
    opacity: 1;
    transform: translateY(0);
}

.welcome-cta::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, var(--sowkar-purple-dark), var(--sowkar-red));
    transform: translateX(-101%);
    transition: transform .5s cubic-bezier(.16, 1, .3, 1);
    z-index: 1;
}

.welcome-cta span,
.welcome-cta i {
    position: relative;
    z-index: 2;
}

.welcome-cta i {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    background: #ffffff;
    border-radius: 3px;
    color: var(--sowkar-navy);
    font-size: 16px;
    transition: transform .4s ease;
}

.welcome-cta:hover {
    color: #ffffff;
    transform: translateY(-4px);
    box-shadow: 0 20px 40px rgba(53, 18, 79, 0.22);
}

.welcome-cta:hover::before {
    transform: translateX(0);
}

.welcome-cta:hover i {
    transform: rotate(45deg);
}

/* SECTION 3 – FACILITY HIGHLIGHTS */
.sowkar-highlights {
    position: relative;
    width: 100%;
    padding: 110px 0 105px;
    background: #FBF8F5;
    overflow: hidden;
    isolation: isolate;
}

.sowkar-highlights::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(rgba(53, 18, 79, 0.03) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
    z-index: 0;
}

.hl-glow-left,
.hl-glow-right {
    position: absolute;
    border-radius: 50%;
    filter: blur(80px);
    pointer-events: none;
    z-index: 0;
}

.hl-glow-left {
    top: 15%;
    left: -120px;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.06) 0%, transparent 70%);
}

.hl-glow-right {
    bottom: 10%;
