}

.sowkar-highlights.is-visible .hl-kicker-line {
    transform: scaleX(1);
}

.hl-eyebrow {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3.6px;
    text-transform: uppercase;
    color: var(--sowkar-red);
}

.hl-heading {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(36px, 4vw, 56px);
