    line-height: 1.05;
    letter-spacing: -1.6px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

.hl-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 3px;
}

.hl-heading-line>span {
    display: inline-block;
    transform: translateY(110%);
    transition: transform .9s cubic-bezier(.16, 1, .3, 1);
}

.sowkar-highlights.is-visible .hl-heading-line:nth-child(1)>span {
    transform: translateY(0);
    transition-delay: .25s;
}

.sowkar-highlights.is-visible .hl-heading-line:nth-child(2)>span {
    transform: translateY(0);
    transition-delay: .40s;
}

.hl-heading em {
    font-style: normal;
    font-weight: 800;
    color: var(--sowkar-red);
}

.hl-split {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: center;
}

/* ============ LEFT: IMAGE COLLAGE ============ */
.hl-collage {
    position: relative;
    width: 100%;
    height: 620px;
}

.hl-collage-main {
    position: absolute;
    top: 0;
    left: 0;
    width: 70%;
    height: 78%;
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 30px 70px rgba(53, 18, 79, 0.16);
    z-index: 3;
    opacity: 0;
    transform: translateY(28px) scale(.97);
    transition: opacity .9s cubic-bezier(.16, 1, .3, 1) .30s, transform .9s cubic-bezier(.16, 1, .3, 1) .30s, box-shadow .7s ease;
}

.sowkar-highlights.is-visible .hl-collage-main {
    opacity: 1;
    transform: translateY(0) scale(1);
}

.hl-collage-main:hover {
    transform: translateY(-6px);
    box-shadow: 0 40px 90px rgba(53, 18, 79, 0.22);
}

.hl-collage-main img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transform: scale(1.04);
    transition: transform 1.2s cubic-bezier(.16, 1, .3, 1);
}

.hl-collage-main:hover img {
    transform: scale(1.01);
}

.hl-collage-small {
    position: absolute;
    bottom: 0;
    right: 0;
    width: 55%;
    height: 50%;
    border-radius: 20px;
    overflow: hidden;
    border: 6px solid #FBF8F5;
    box-shadow: 0 20px 55px rgba(53, 18, 79, 0.18);
    z-index: 4;
    opacity: 0;
    transform: translate(15px, 20px) scale(.96);
    transition: opacity .9s cubic-bezier(.16, 1, .3, 1) .50s, transform .9s cubic-bezier(.16, 1, .3, 1) .50s, box-shadow .7s ease;
}

.sowkar-highlights.is-visible .hl-collage-small {
    opacity: 1;
    transform: translate(0, 0) scale(1);
}

.hl-collage-small:hover {
    transform: translate(-6px, -6px);
    box-shadow: 0 30px 70px rgba(53, 18, 79, 0.24);
}

.hl-collage-small img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transform: scale(1.04);
    transition: transform 1.2s cubic-bezier(.16, 1, .3, 1);
}

.hl-collage-small:hover img {
    transform: scale(1.01);
}

.hl-collage-badge {
    position: absolute;
    top: 22%;
    right: 4%;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
    padding: 16px 22px;
    background: #24102F;
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 14px;
    box-shadow: 0 20px 50px rgba(22, 11, 32, 0.32);
    z-index: 5;
    opacity: 0;
    transform: scale(.6) translateY(12px);
    transition: opacity .85s cubic-bezier(.34, 1.56, .64, 1) .75s, transform .85s cubic-bezier(.34, 1.56, .64, 1) .75s;
}

.sowkar-highlights.is-visible .hl-collage-badge {
    opacity: 1;
    transform: scale(1) translateY(0);
}

.hl-collage-badge:hover {
    transform: translateY(-5px);
}

.hl-collage-badge strong {
    font-family: "Urbanist", sans-serif;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    line-height: 1;
}

.hl-collage-badge span {
    font-family: "Montserrat", sans-serif;
    font-size: 8.5px;
    font-weight: 600;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    color: #E77A88;
}

.hl-collage::before {
    content: "";
    position: absolute;
    top: -20px;
    right: -10px;
    width: 100px;
    height: 100px;
    border-radius: 50%;
    border: 1.5px dashed rgba(201, 75, 92, 0.35);
    z-index: 1;
    animation: welcomeShapeSpin 45s linear infinite;
}

.hl-collage::after {
    content: "";
    position: absolute;
    bottom: 8%;
    left: 4%;
    width: 80px;
    height: 80px;
    border-radius: 18px;
    background: linear-gradient(135deg, rgba(201, 75, 92, 0.16), rgba(155, 63, 143, 0.10));
    transform: rotate(28deg);
    z-index: 1;
    transition: transform .7s ease;
}

.hl-collage:hover::after {
    transform: rotate(48deg) scale(1.1);
}

/* ============ RIGHT: CAPABILITY LIST ============ */
.hl-list {
    position: relative;
}

.hl-item {
    position: relative;
    display: grid;
    grid-template-columns: 68px 1fr 40px;
