.sowkar-highlights.is-visible .hl-item:nth-child(1) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .35s;
}

.sowkar-highlights.is-visible .hl-item:nth-child(2) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .48s;
}

.sowkar-highlights.is-visible .hl-item:nth-child(3) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .60s;
}

.sowkar-highlights.is-visible .hl-item:nth-child(4) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .72s;
