/* SECTION 4 – CERTIFICATIONS & STANDARDS */
.sowkar-standards {
    position: relative;
    width: 100%;
    padding: 100px 0 90px;
    background: linear-gradient(180deg, #FFFFFF 0%, #FBF8F5 100%);
    overflow: hidden;
    isolation: isolate;
}

.sowkar-standards::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(rgba(53, 18, 79, 0.03) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
    z-index: 0;
}

.std-glow-left,
.std-glow-right {
    position: absolute;
    border-radius: 50%;
    filter: blur(80px);
    pointer-events: none;
    z-index: 0;
}

.std-glow-left {
    top: 20%;
    left: -100px;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(201, 75, 92, 0.06) 0%, transparent 70%);
}

.std-glow-right {
    bottom: 10%;
    right: -100px;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(155, 63, 143, 0.06) 0%, transparent 70%);
}

.sowkar-standards .container {
    position: relative;
    z-index: 2;
}

/* ---- Section heading ---- */
.std-head {
    text-align: center;
    max-width: 720px;
    margin: 0 auto 55px;
}

.std-kicker {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    opacity: 0;
    transform: translateY(-16px);
    transition: opacity .7s cubic-bezier(.16, 1, .3, 1) .15s, transform .7s cubic-bezier(.16, 1, .3, 1) .15s;
}

.sowkar-standards.is-visible .std-kicker {
    opacity: 1;
    transform: translateY(0);
}

.std-kicker-line {
    width: 30px;
    height: 1px;
    background: var(--sowkar-red);
    opacity: .55;
    transform-origin: left;
    transform: scaleX(0);
    transition: transform .6s cubic-bezier(.16, 1, .3, 1) .35s;
}

.sowkar-standards.is-visible .std-kicker-line {
    transform: scaleX(1);
}

.std-eyebrow {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3.6px;
    text-transform: uppercase;
    color: var(--sowkar-red);
}

.std-heading {
    margin: 0 0 14px;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(34px, 4vw, 52px);
    font-weight: 300;
    line-height: 1.06;
    letter-spacing: -1.6px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

.std-heading-line {
    display: block;
    overflow: hidden;
    padding-bottom: 3px;
}

.std-heading-line>span {
    display: inline-block;
    transform: translateY(110%);
    transition: transform .9s cubic-bezier(.16, 1, .3, 1);
}

.sowkar-standards.is-visible .std-heading-line:nth-child(1)>span {
    transform: translateY(0);
    transition-delay: .25s;
}

.sowkar-standards.is-visible .std-heading-line:nth-child(2)>span {
    transform: translateY(0);
    transition-delay: .40s;
}

.std-heading em {
    font-style: normal;
    font-weight: 800;
    color: var(--sowkar-red);
}

.std-intro {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.8;
    color: var(--sowkar-muted);
    opacity: 0;
    transform: translateY(22px);
    transition: opacity .8s cubic-bezier(.16, 1, .3, 1) .52s, transform .8s cubic-bezier(.16, 1, .3, 1) .52s;
}

.sowkar-standards.is-visible .std-intro {
    opacity: 1;
    transform: translateY(0);
}

/* ---- Cards grid ---- */
.std-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 22px;
}

.std-card {
    position: relative;
    display: flex;
    flex-direction: column;
    padding: 36px 26px 30px;
    background: #ffffff;
    border: 1px solid rgba(53, 18, 79, 0.10);
    border-radius: 18px;
    text-align: center;
    overflow: hidden;
    opacity: 0;
    transform: translateY(28px);
    transition: opacity .75s cubic-bezier(.16, 1, .3, 1), transform .75s cubic-bezier(.16, 1, .3, 1), border-color .45s ease, box-shadow .45s ease;
}

.sowkar-standards.is-visible .std-card:nth-child(1) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .40s;
}

.sowkar-standards.is-visible .std-card:nth-child(2) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .52s;
}

.sowkar-standards.is-visible .std-card:nth-child(3) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .64s;
}

.sowkar-standards.is-visible .std-card:nth-child(4) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .76s;
}

.std-card:hover {
    transform: translateY(-8px);
    border-color: rgba(201, 75, 92, 0.35);
    box-shadow:
        0 25px 55px rgba(53, 18, 79, 0.10),
        0 0 25px rgba(201, 75, 92, 0.08);
}

/* Top accent line */
.std-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--sowkar-red), var(--sowkar-purple));
    transition: width .5s cubic-bezier(.16, 1, .3, 1);
}

.std-card:hover::before {
    width: 60%;
}

/* Icon orb */
.std-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 66px;
    height: 66px;
    margin: 0 auto 22px;
    border-radius: 50%;
    background: linear-gradient(135deg, rgba(201, 75, 92, 0.10), rgba(155, 63, 143, 0.08));
    border: 1px solid rgba(201, 75, 92, 0.18);
    color: var(--sowkar-red);
    font-size: 26px;
    transition: transform .4s ease, background .4s ease, color .4s ease, box-shadow .4s ease;
}

.std-card:hover .std-icon {
    background: linear-gradient(135deg, var(--sowkar-red), var(--sowkar-purple));
    color: #ffffff;
    transform: scale(1.08) rotate(-6deg);
    box-shadow: 0 14px 32px rgba(201, 75, 92, 0.32);
}

.std-card h3 {
    margin: 0 0 8px;
    font-family: "Urbanist", sans-serif;
    font-size: 16px;
    font-weight: 700;
    letter-spacing: 0.3px;
    color: var(--sowkar-navy);
    line-height: 1.3;
    transition: color .3s ease;
}

.std-card:hover h3 {
    color: var(--sowkar-red);
}

.std-card p {
    margin: 0;
    font-family: "Montserrat", sans-serif;
    font-size: 12px;
    font-weight: 400;
    line-height: 1.7;
    color: var(--sowkar-muted);
}

/* Bottom badge */
.std-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 20px auto 0;
    padding: 6px 14px;
    background: rgba(201, 75, 92, 0.08);
    border: 1px solid rgba(201, 75, 92, 0.20);
    border-radius: 30px;
    font-family: "Montserrat", sans-serif;
    font-size: 9.5px;
    font-weight: 700;
    letter-spacing: 1.6px;
    text-transform: uppercase;
    color: var(--sowkar-red);
    transition: background .3s ease, color .3s ease, border-color .3s ease;
}

.std-card:hover .std-badge {
    background: var(--sowkar-red);
    border-color: var(--sowkar-red);
    color: #ffffff;
}

.std-badge i {
    font-size: 10px;
}

/* ---- Bottom trust strip ---- */
.std-trust-strip {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 40px;
    flex-wrap: wrap;
    margin-top: 60px;
    padding-top: 45px;
    border-top: 1px solid rgba(53, 18, 79, 0.10);
    opacity: 0;
    transform: translateY(22px);
    transition: opacity .8s cubic-bezier(.16, 1, .3, 1) .70s, transform .8s cubic-bezier(.16, 1, .3, 1) .70s;
}

.sowkar-standards.is-visible .std-trust-strip {
    opacity: 1;
    transform: translateY(0);
}

.std-trust-item {
    display: flex;
    align-items: center;
    gap: 12px;
    opacity: 0;
    transform: translateY(18px);
    transition: opacity .6s cubic-bezier(.16, 1, .3, 1), transform .6s cubic-bezier(.16, 1, .3, 1);
}

.sowkar-standards.is-visible .std-trust-item:nth-child(1) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .75s;
}

.sowkar-standards.is-visible .std-trust-item:nth-child(2) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .85s;
}

.sowkar-standards.is-visible .std-trust-item:nth-child(3) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: .95s;
}

.sowkar-standards.is-visible .std-trust-item:nth-child(4) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 1.05s;
}

.std-trust-item:hover {
    transform: translateY(-3px);
}

.std-trust-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: #ffffff;
    border: 1px solid rgba(53, 18, 79, 0.10);
    color: var(--sowkar-red);
    font-size: 16px;
    box-shadow: 0 6px 18px rgba(53, 18, 79, 0.05);
    transition: background .3s ease, color .3s ease, border-color .3s ease;
}

.std-trust-item:hover .std-trust-icon {
    background: linear-gradient(135deg, var(--sowkar-red), var(--sowkar-purple));
    color: #ffffff;
    border-color: transparent;
}

.std-trust-item span {
    font-family: "Montserrat", sans-serif;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    color: var(--sowkar-navy);
}

/* SECTION 5 – CTA BANNER (INFRASTRUCTURE) */
.sowkar-infra-cta {
    position: relative;
    padding: 105px 0 110px;
    background:
        radial-gradient(ellipse at 12% 20%, rgba(155, 63, 143, 0.055) 0%, transparent 55%),
        radial-gradient(ellipse at 88% 80%, rgba(201, 75, 92, 0.05) 0%, transparent 50%),
        radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.6) 0%, transparent 70%),
        linear-gradient(135deg, #fcf9f6 0%, #f9f2f8 50%, #faf3f1 100%);
    border-top: 1px solid rgba(53, 18, 79, 0.06);
    overflow: hidden;
    isolation: isolate;
}

.sowkar-infra-cta::before {
    content: "";
    position: absolute;
    width: 480px;
    height: 480px;
    left: -140px;
    top: -120px;
    border-radius: 48% 52% 68% 32% / 36% 44% 56% 64%;
    background: linear-gradient(140deg, rgba(155, 63, 143, 0.085) 0%, rgba(53, 18, 79, 0.035) 55%, transparent 100%);
    border: 1.5px dashed rgba(155, 63, 143, 0.2);
    box-shadow: inset 0 0 50px rgba(155, 63, 143, 0.04), 0 24px 60px rgba(53, 18, 79, 0.035);
    transform: rotate(-18deg);
    pointer-events: none;
    z-index: 1;
    animation: ctaMorphShape1 20s ease-in-out infinite alternate;
}

.sowkar-infra-cta::after {
    content: "";
    position: absolute;
    width: 520px;
    height: 520px;
    right: -150px;
    bottom: -130px;
    border-radius: 35% 65% 42% 58% / 54% 38% 62% 46%;
    background: linear-gradient(320deg, rgba(201, 75, 92, 0.075) 0%, rgba(231, 122, 136, 0.04) 55%, transparent 100%);
    border: 1.5px solid rgba(201, 75, 92, 0.16);
    box-shadow: inset 0 0 50px rgba(201, 75, 92, 0.03), 0 28px 70px rgba(201, 75, 92, 0.04);
    transform: rotate(22deg);
    pointer-events: none;
    z-index: 1;
    animation: ctaMorphShape2 24s ease-in-out infinite alternate-reverse;
}

.sowkar-infra-cta .sowkar-cta-content {
    position: relative;
    z-index: 2;
}

.sowkar-infra-cta .sowkar-cta-label {
    display: inline-block;
    margin-bottom: 17px;
    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 6px;
    line-height: 1.4;
    color: #35124f;
    opacity: 0;
    transform: translateY(-16px);
    transition: opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1), transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-infra-cta .sowkar-cta-line {
    width: 108px;
    height: 4px;
    margin: 0 auto 36px;
    background: #c94b5c;
    transform-origin: center;
    transform: scaleX(0);
    transition: transform 0.75s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-infra-cta .sowkar-cta-heading {
    margin: 0;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(48px, 5.4vw, 82px);
    font-weight: 500;
    line-height: 1.05;
    letter-spacing: -2.5px;
    color: #35124f;
}

.sowkar-infra-cta .sowkar-cta-text {
    max-width: 850px;
    margin: 30px auto 0;
    font-family: "Montserrat", sans-serif;
    font-size: 17px;
    font-weight: 400;
    line-height: 1.8;
    color: #50506c;
    opacity: 0;
    transform: translateY(22px);
    transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-infra-cta .sowkar-cta-buttons {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 22px;
    margin-top: 48px;
    opacity: 0;
    transform: translateY(22px);
    transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-infra-cta.is-visible .sowkar-cta-label,
.sowkar-infra-cta.in-view .sowkar-cta-label {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.1s;
}

.sowkar-infra-cta.is-visible .sowkar-cta-line,
.sowkar-infra-cta.in-view .sowkar-cta-line {
    transform: scaleX(1);
    transition-delay: 0.25s;
}

.sowkar-infra-cta.is-visible .sowkar-cta-text,
.sowkar-infra-cta.in-view .sowkar-cta-text {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.65s;
}

.sowkar-infra-cta.is-visible .sowkar-cta-buttons,
.sowkar-infra-cta.in-view .sowkar-cta-buttons {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.8s;
}

