    color: var(--sowkar-red, #c94b5c);
}

.sowkar-hospitality-page .scrub-specs-accent-line {
    width: 78px;
    height: 2px;
    margin: 14px auto 18px;
    background: linear-gradient(90deg, #C94B5C, #C98BC2);
