    transform: scaleX(0);
    transition: transform 0.75s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-hospitality-page .scrub-specs-heading p {
    max-width: 600px;
    margin: 0 auto;
    font-family: "Montserrat", sans-serif;
