}

.sowkar-hospitality-page .scrub-specs-heading.in-view .scrub-heading-line:nth-child(2)>span {
    transform: translateY(0);
    transition-delay: 0.4s;
}

.sowkar-hospitality-page .scrub-specs-heading.in-view .scrub-specs-accent-line {
    transform: scaleX(1);
    transition-delay: 0.55s;
}

.sowkar-hospitality-page .scrub-specs-heading.in-view p {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.7s;
}

/* ---------- SPEC ROW ---------- */
.sowkar-hospitality-page .scrub-spec-row {
    display: flex;
    align-items: stretch;
    gap: 0;
    min-height: 500px;
    margin-bottom: 28px;
