    transition: opacity 0.35s ease, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-hospitality-page .scrub-spec-image img {
    object-fit: cover;
    object-position: center top;
}

.sowkar-hospitality-page .scrub-spec-row:hover .scrub-spec-image svg,
.sowkar-hospitality-page .scrub-spec-row:hover .scrub-spec-image img {
