    font-family: "Montserrat", sans-serif;
    font-size: 12.5px;
    font-weight: 500;
    color: var(--sowkar-navy, #35124f);
    opacity: 0;
    transform: translateY(14px);
    transition: opacity 0.5s cubic-bezier(0.16, 1, 0.3, 1), transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-hospitality-page .scrub-spec-list li i {
    color: var(--sowkar-red, #c94b5c);
    font-size: 13px;
    flex-shrink: 0;
}

.sowkar-hospitality-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(1) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.48s;
}

.sowkar-hospitality-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(2) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.53s;
}

.sowkar-hospitality-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(3) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.58s;
}

.sowkar-hospitality-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(4) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.63s;
}

.sowkar-hospitality-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(5) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.68s;
}

.sowkar-hospitality-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(6) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.73s;
}

