.sowkar-industry-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(3) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.58s;
}

.sowkar-industry-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(4) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.63s;
}

.sowkar-industry-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(5) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.68s;
}

.sowkar-industry-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(6) {
