/* ---------- CTA SECTION ---------- */
.sowkar-industry-cta,
.sowkar-industry-page .sowkar-cta {
    position: relative;
    padding: 105px 0 110px;
    background:
        radial-gradient(ellipse at 12% 20%, rgba(155, 63, 143, 0.055) 0%, transparent 55%),
        radial-gradient(ellipse at 88% 80%, rgba(201, 75, 92, 0.05) 0%, transparent 50%),
        radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.6) 0%, transparent 70%),
        linear-gradient(135deg, #fcf9f6 0%, #f9f2f8 50%, #faf3f1 100%);
    border-top: 1px solid rgba(53, 18, 79, 0.06);
    overflow: hidden;
    isolation: isolate;
}

.sowkar-industry-cta::before,
.sowkar-industry-page .sowkar-cta::before {
    content: "";
    position: absolute;
    width: 480px;
    height: 480px;
    left: -140px;
    top: -120px;
    border-radius: 48% 52% 68% 32% / 36% 44% 56% 64%;
    background: linear-gradient(140deg, rgba(155, 63, 143, 0.085) 0%, rgba(53, 18, 79, 0.035) 55%, transparent 100%);
    border: 1.5px dashed rgba(155, 63, 143, 0.2);
    box-shadow: inset 0 0 50px rgba(155, 63, 143, 0.04), 0 24px 60px rgba(53, 18, 79, 0.035);
    transform: rotate(-18deg);
    pointer-events: none;
    z-index: 1;
    animation: ctaMorphShape1 20s ease-in-out infinite alternate;
}

.sowkar-industry-cta::after,
.sowkar-industry-page .sowkar-cta::after {
    content: "";
    position: absolute;
    width: 520px;
    height: 520px;
    right: -150px;
    bottom: -130px;
    border-radius: 35% 65% 42% 58% / 54% 38% 62% 46%;
    background: linear-gradient(320deg, rgba(201, 75, 92, 0.075) 0%, rgba(231, 122, 136, 0.04) 55%, transparent 100%);
    border: 1.5px solid rgba(201, 75, 92, 0.16);
    box-shadow: inset 0 0 50px rgba(201, 75, 92, 0.03), 0 28px 70px rgba(201, 75, 92, 0.04);
    transform: rotate(22deg);
    pointer-events: none;
    z-index: 1;
    animation: ctaMorphShape2 24s ease-in-out infinite alternate-reverse;
}

.sowkar-industry-cta .sowkar-cta-content,
.sowkar-industry-page .sowkar-cta .sowkar-cta-content {
    position: relative;
    z-index: 2;
}

.sowkar-industry-cta .sowkar-cta-label,
.sowkar-industry-page .sowkar-cta .sowkar-cta-label {
    display: inline-block;
    margin-bottom: 17px;
    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 6px;
    line-height: 1.4;
    color: #35124f;
    opacity: 0;
    transform: translateY(-16px);
    transition: opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1), transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-industry-cta .sowkar-cta-line,
.sowkar-industry-page .sowkar-cta .sowkar-cta-line {
    width: 108px;
    height: 4px;
    margin: 0 auto 36px;
    background: #c94b5c;
    transform-origin: center;
    transform: scaleX(0);
    transition: transform 0.75s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-industry-cta .sowkar-cta-heading,
.sowkar-industry-page .sowkar-cta .sowkar-cta-heading {
    margin: 0;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(48px, 5.4vw, 82px);
