}

.sowkar-lab-coats-page .scrub-specs-heading.in-view .scrub-heading-line:nth-child(1)>span {
    transform: translateY(0);
    transition-delay: 0.25s;
}

.sowkar-lab-coats-page .scrub-specs-heading.in-view .scrub-heading-line:nth-child(2)>span {
    transform: translateY(0);
    transition-delay: 0.4s;
}

.sowkar-lab-coats-page .scrub-specs-heading.in-view .scrub-specs-accent-line {
    transform: scaleX(1);
    transition-delay: 0.55s;
}

.sowkar-lab-coats-page .scrub-specs-heading.in-view p {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.7s;
}

/* ---------- SPEC ROW ---------- */
.sowkar-lab-coats-page .scrub-spec-row {
    display: flex;
    align-items: stretch;
    gap: 0;
    min-height: 500px;
    margin-bottom: 28px;
    background: #FFFFFF;
    border: 1px solid rgba(53, 18, 79, 0.08);
    border-radius: 16px;
    overflow: hidden;
    box-shadow: 0 8px 28px rgba(53, 18, 79, 0.06);
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
        transform 0.8s cubic-bezier(0.16, 1, 0.3, 1),
        box-shadow 0.4s ease,
        border-color 0.4s ease;
}

.sowkar-lab-coats-page .scrub-spec-row.in-view {
    opacity: 1;
    transform: translateY(0);
}

.sowkar-lab-coats-page .scrub-spec-row.in-view:hover {
    transform: translateY(-4px);
    border-color: rgba(201, 75, 92, 0.25);
    box-shadow: 0 18px 40px rgba(53, 18, 79, 0.12);
}

/* alternating layout */
.sowkar-lab-coats-page .scrub-spec-row--reverse {
    flex-direction: row-reverse;
}

/* image pane */
.sowkar-lab-coats-page .scrub-spec-image {
    flex: 0 0 44%;
    height: 500px;
    min-height: 500px;
    overflow: hidden;
    background: #fbf7fb;
    position: relative;
    opacity: 0;
    transform: scale(0.96);
    transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    align-items: center;
    justify-content: center;
}

.sowkar-lab-coats-page .scrub-spec-row.in-view .scrub-spec-image {
    opacity: 1;
    transform: scale(1);
    transition-delay: 0.15s;
}

.sowkar-lab-coats-page .scrub-spec-image svg,
.sowkar-lab-coats-page .scrub-spec-image img {
    width: 100%;
    height: 100%;
    display: block;
    transition: opacity 0.35s ease, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.sowkar-lab-coats-page .scrub-spec-image img {
    object-fit: cover;
    object-position: center top;
}

.sowkar-lab-coats-page .scrub-spec-row:hover .scrub-spec-image svg,
.sowkar-lab-coats-page .scrub-spec-row:hover .scrub-spec-image img {
    transform: scale(1.02);
}

/* =========================================================
   PRODUCT IMAGE CAROUSEL (MALE / FEMALE SLIDES)
   ========================================================= */
.sowkar-lab-coats-page .scrub-carousel-image-frame {
