.sowkar-lab-coats-page .scrub-color-dot.active {
    transform: scale(1.08);
    box-shadow: 0 0 0 1.5px #ffffff, 0 0 0 3px var(--sowkar-red), 0 3px 8px rgba(201, 75, 92, 0.25);
}

.sowkar-lab-coats-page .scrub-color-dot.active::after {
    content: "";
    position: absolute;
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #ffffff;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
    pointer-events: none;
}

.sowkar-lab-coats-page .scrub-spec-list {
