    transform: translateY(0);
    transition-delay: 0.48s;
}

.sowkar-lab-coats-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(2) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.53s;
}

.sowkar-lab-coats-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(3) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.58s;
}

.sowkar-lab-coats-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(4) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.63s;
}

.sowkar-lab-coats-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(5) {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.68s;
}

.sowkar-lab-coats-page .scrub-spec-row.in-view .scrub-spec-list li:nth-child(6) {
    opacity: 1;
    transform: translateY(0);
