    transform: rotate(-18deg);
    pointer-events: none;
    z-index: 1;
    animation: ctaMorphShape1 20s ease-in-out infinite alternate;
}

.sowkar-ot-gown-cta::after,
.sowkar-ot-gown-page .sowkar-cta::after {
    content: "";
    position: absolute;
    width: 520px;
    height: 520px;
    right: -150px;
    bottom: -130px;
    border-radius: 35% 65% 42% 58% / 54% 38% 62% 46%;
