    transform: rotate(-18deg);
    pointer-events: none;
    z-index: 1;
    animation: ctaMorphShape1 20s ease-in-out infinite alternate;
}

.sowkar-patient-gown-cta::after,
.sowkar-patient-gown-page .sowkar-cta::after {
    content: "";
    position: absolute;
