}

.sowkar-testimonials-page .th-heading-line:nth-child(2)>span {
    animation-delay: .55s;
}

.sowkar-testimonials-page .th-heading-line:nth-child(3)>span {
    animation-delay: .70s;
}

.sowkar-testimonials-page .th-text-gradient {
    background: linear-gradient(135deg, #ffffff 15%, #C98BC2 55%, #E77A88 100%);
