}

.sowkar-testimonials-page .th-stars-row {
    display: inline-flex;
    gap: 4px;
}

.sowkar-testimonials-page .th-stars-row i {
    color: #E77A88;
    font-size: 13px;
    filter: drop-shadow(0 0 6px rgba(231, 122, 136, 0.55));
}

.sowkar-testimonials-page .th-stars-text {
    font-family: "Montserrat", sans-serif;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 2.2px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.72);
}

.sowkar-testimonials-page .th-subcopy {
    max-width: 500px;
    margin: 0 0 22px;
    font-family: "Montserrat", sans-serif;
    font-size: 13px;
    font-weight: 400;
    line-height: 1.65;
    color: #C9B8D0;
    opacity: 0;
    animation: thFadeUp .8s cubic-bezier(.16, 1, .3, 1) .94s forwards;
}

.sowkar-testimonials-page .th-actions {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
    opacity: 0;
    animation: thFadeUp .8s cubic-bezier(.16, 1, .3, 1) 1.06s forwards;
}

.sowkar-testimonials-page .th-btn-primary {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 24px;
    background: linear-gradient(100deg, #9B3F8F, #C94B5C);
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 4px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    text-decoration: none;
