.sowkar-testimonials-page .th-btn-primary::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, #C94B5C, #E77A88);
    opacity: 0;
    transition: opacity .4s ease;
    z-index: 1;
}

.sowkar-testimonials-page .th-btn-primary span,
.sowkar-testimonials-page .th-btn-primary i {
    position: relative;
