}

.sowkar-testimonials-page .th-btn-primary:hover {
    color: #ffffff;
    transform: translateY(-3px);
    box-shadow: 0 20px 44px rgba(201, 75, 92, 0.42);
}

.sowkar-testimonials-page .th-btn-primary:hover::before {
    opacity: 1;
}

.sowkar-testimonials-page .th-btn-primary:hover i {
    transform: translate(3px, 3px);
}

.sowkar-testimonials-page .th-btn-glass {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 22px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 4px;
    color: #ffffff;
    font-family: "Montserrat", sans-serif;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    text-decoration: none;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: background .3s, border-color .3s, transform .3s;
}

.sowkar-testimonials-page .th-btn-glass:hover {
    color: #ffffff;
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(201, 75, 92, 0.4);
    transform: translateY(-3px);
}

/* ---------- RIGHT: Quote Constellation ---------- */
.sowkar-testimonials-page .th-right {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    height: 440px;
    opacity: 0;
    animation: thRightReveal 1.1s cubic-bezier(.16, 1, .3, 1) .45s forwards;
}

@keyframes thRightReveal {
    from {
        opacity: 0;
        transform: translateX(50px) scale(.94);
    }

    to {
        opacity: 1;
        transform: translateX(0) scale(1);
    }
}

.sowkar-testimonials-page .th-orbit {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 440px;
    height: 440px;
    border-radius: 50%;
    border: 1.5px dashed rgba(216, 185, 226, 0.28);
    animation: thOrbitSpin 60s linear infinite;
    pointer-events: none;
    z-index: 0;
}

@keyframes thOrbitSpin {
    from {
        transform: translate(-50%, -50%) rotate(0deg);
    }

    to {
        transform: translate(-50%, -50%) rotate(360deg);
    }
}

.sowkar-testimonials-page .th-orbit-inner {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 320px;
    height: 320px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(155, 63, 143, 0.10) 0%, rgba(201, 75, 92, 0.06) 55%, transparent 75%);
    filter: blur(20px);
    pointer-events: none;
    z-index: 0;
    animation: thOrbitPulse 7s ease-in-out infinite alternate;
}

@keyframes thOrbitPulse {
    0% {
        transform: translate(-50%, -50%) scale(1);
        opacity: .7;
    }

    100% {
        transform: translate(-50%, -50%) scale(1.1);
        opacity: 1;
    }
}

.sowkar-testimonials-page .th-mosaic {
    position: relative;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 11px;
    width: 100%;
    max-width: 390px;
    z-index: 3;
}

.sowkar-testimonials-page .th-tile {
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    aspect-ratio: 1 / 1;
    padding: 13px 11px 11px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 15px;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    overflow: hidden;
    transition: transform .5s cubic-bezier(.16, 1, .3, 1), background .4s ease, border-color .4s ease, box-shadow .5s ease;
    animation: thTileFloat 6s ease-in-out infinite;
    will-change: transform;
}

.sowkar-testimonials-page .th-tile:nth-child(1) {
    animation-delay: 0s;
}

.sowkar-testimonials-page .th-tile:nth-child(2) {
    animation-delay: .4s;
}

.sowkar-testimonials-page .th-tile:nth-child(3) {
    animation-delay: .8s;
}

.sowkar-testimonials-page .th-tile:nth-child(4) {
    animation-delay: .2s;
}

.sowkar-testimonials-page .th-tile:nth-child(5) {
    animation-delay: .6s;
}

.sowkar-testimonials-page .th-tile:nth-child(6) {
    animation-delay: 1s;
}

.sowkar-testimonials-page .th-tile:nth-child(7) {
    animation-delay: .3s;
}

.sowkar-testimonials-page .th-tile:nth-child(8) {
    animation-delay: .7s;
}

.sowkar-testimonials-page .th-tile:nth-child(9) {
    animation-delay: 1.1s;
}

@keyframes thTileFloat {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-5px);
    }
}

.sowkar-testimonials-page .th-tile::after {
    content: "";
    position: absolute;
    top: 0;
    left: -140%;
    width: 70%;
    height: 100%;
    background: linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.20) 50%, transparent 100%);
    transform: skewX(-25deg);
    transition: left .9s cubic-bezier(.16, 1, .3, 1);
    pointer-events: none;
    z-index: 3;
}

.sowkar-testimonials-page .th-tile:hover::after {
    left: 180%;
}

.sowkar-testimonials-page .th-tile:hover {
    background: rgba(255, 255, 255, 0.10);
    border-color: rgba(201, 75, 92, 0.5);
    box-shadow:
        0 16px 35px rgba(0, 0, 0, 0.30),
        0 0 20px rgba(201, 75, 92, 0.20);
    transform: translateY(-6px) scale(1.03);
    animation-play-state: paused;
}

.sowkar-testimonials-page .th-tile-quote {
    font-family: Georgia, serif;
    font-size: 28px;
    font-weight: 700;
    line-height: .8;
    color: #ECA0AA;
    opacity: .75;
    transition: opacity .3s ease, color .3s ease;
}

.sowkar-testimonials-page .th-tile:hover .th-tile-quote {
    opacity: 1;
    color: #E77A88;
}

.sowkar-testimonials-page .th-tile-text {
    font-family: "Montserrat", sans-serif;
    font-size: 8.5px;
    font-weight: 500;
    line-height: 1.35;
    color: rgba(255, 255, 255, 0.85);
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-align: left;
}

.sowkar-testimonials-page .th-tile-stars {
    display: inline-flex;
    gap: 2px;
    margin-top: auto;
    padding-top: 5px;
}

.sowkar-testimonials-page .th-tile-stars i {
    font-size: 7.5px;
    color: #E77A88;
    opacity: 0.85;
}

.sowkar-testimonials-page .th-tile-dot {
    position: absolute;
    top: 8px;
    right: 8px;
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #E77A88;
    box-shadow: 0 0 0 4px rgba(231, 122, 136, 0.14);
    opacity: 0;
    transition: opacity .4s ease;
    z-index: 4;
}

.sowkar-testimonials-page .th-tile:hover .th-tile-dot {
    opacity: 1;
}

.sowkar-testimonials-page .th-float-badge {
    position: absolute;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 7px 14px;
    background: rgba(36, 16, 47, 0.92);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 50px;
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    box-shadow: 0 16px 36px rgba(0, 0, 0, 0.35);
    z-index: 5;
    transition: transform .5s cubic-bezier(.16, 1, .3, 1), background .4s ease;
}

.sowkar-testimonials-page .th-float-badge:hover {
    transform: translateY(-4px) scale(1.03);
    background: #1B0C23;
}

.sowkar-testimonials-page .th-float-badge-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: linear-gradient(135deg, #C94B5C, #9B3F8F);
    color: #ffffff;
    font-size: 11px;
    flex-shrink: 0;
}

.sowkar-testimonials-page .th-float-badge-text {
    font-family: "Montserrat", sans-serif;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.3px;
    text-transform: uppercase;
    color: #ffffff;
    white-space: nowrap;
}

.sowkar-testimonials-page .th-badge-1 {
    top: 3%;
    left: -4%;
    opacity: 0;
    animation: thBadgePop .9s cubic-bezier(.34, 1.56, .64, 1) 1.30s forwards;
}

.sowkar-testimonials-page .th-badge-2 {
    bottom: 3%;
    right: -4%;
    opacity: 0;
    animation: thBadgePop .9s cubic-bezier(.34, 1.56, .64, 1) 1.45s forwards;
}

@keyframes thBadgePop {
    from {
        opacity: 0;
        transform: scale(.65) translateY(12px);
    }

    to {
        opacity: 1;
        transform: scale(1) translateY(0);
    }
}

.sowkar-testimonials-page .th-corner {
    position: absolute;
    width: 60px;
    height: 60px;
    z-index: 4;
    pointer-events: none;
    opacity: 0;
    animation: thFadeIn 1.2s cubic-bezier(.16, 1, .3, 1) 1.5s forwards;
}

.sowkar-testimonials-page .th-corner-tl {
    top: 10px;
    left: 10px;
    border-top: 1px solid rgba(234, 220, 240, 0.32);
    border-left: 1px solid rgba(234, 220, 240, 0.32);
}

.sowkar-testimonials-page .th-corner-br {
    bottom: 10px;
    right: 10px;
    border-bottom: 1px solid rgba(201, 75, 92, 0.55);
    border-right: 1px solid rgba(201, 75, 92, 0.55);
}

@keyframes thFadeIn {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

.sowkar-testimonials-page .th-seal {
    position: absolute;
    top: -18px;
    right: -12px;
    width: 82px;
    height: 82px;
    z-index: 6;
    opacity: 0;
    animation: thBadgePop 1s cubic-bezier(.34, 1.56, .64, 1) 1.6s forwards;
}

.sowkar-testimonials-page .th-seal-svg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    animation: thSealSpin 22s linear infinite;
}

.sowkar-testimonials-page .th-right:hover .th-seal-svg {
    animation-duration: 10s;
}

.sowkar-testimonials-page .th-seal-svg text {
    font-family: "Montserrat", sans-serif;
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 2.4px;
    fill: #ffffff;
    text-transform: uppercase;
}

.sowkar-testimonials-page .th-seal-core {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: linear-gradient(135deg, #C94B5C, #9B3F8F);
    box-shadow: 0 0 20px rgba(201, 75, 92, 0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #ffffff;
    font-size: 12px;
    transition: transform .4s ease;
}

.sowkar-testimonials-page .th-seal:hover .th-seal-core {
    transform: translate(-50%, -50%) rotate(45deg) scale(1.1);
}

@keyframes thSealSpin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

.sowkar-testimonials-page .th-hero-corner {
    position: absolute;
    width: 90px;
    height: 90px;
    z-index: 5;
    pointer-events: none;
    opacity: 0;
    animation: thFadeIn 1.2s cubic-bezier(.16, 1, .3, 1) 1.7s forwards;
}

.sowkar-testimonials-page .th-hero-corner.tl {
    top: 30px;
    left: 30px;
    border-top: 1px solid rgba(234, 220, 240, 0.32);
    border-left: 1px solid rgba(234, 220, 240, 0.32);
}

.sowkar-testimonials-page .th-hero-corner.bl {
    bottom: 30px;
    left: 30px;
    border-bottom: 1px solid rgba(234, 220, 240, 0.32);
    border-left: 1px solid rgba(201, 75, 92, 0.55);
}

@keyframes thFadeDown {
    from {
        opacity: 0;
        transform: translateY(-16px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes thFadeUp {
    from {
        opacity: 0;
        transform: translateY(24px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes thTextReveal {
    to {
        transform: translateY(0);
    }
}

