}

.sowkar-testimonials-page .sowkar-testimonials-showcase.in-view .ts-wall-card:nth-child(3) {
    transition-delay: .30s;
}

.sowkar-testimonials-page .sowkar-testimonials-showcase.in-view .ts-wall-card:nth-child(4) {
    transition-delay: .40s;
}

.sowkar-testimonials-page .sowkar-testimonials-showcase.in-view .ts-wall-card:nth-child(5) {
