}

.sowkar-testimonials-page .ts-wall-card::after {
    content: "";
    position: absolute;
    top: 0;
    left: 32px;
    width: 34px;
    height: 3px;
    background: linear-gradient(90deg, var(--sowkar-red), var(--sowkar-purple));
    border-radius: 0 0 3px 3px;
    transition: width .5s cubic-bezier(.16, 1, .3, 1);
}

.sowkar-testimonials-page .ts-wall-card:hover::after {
    width: 100px;
}

.sowkar-testimonials-page .ts-wall-card:hover {
    transform: translateY(-8px);
    border-color: rgba(201, 75, 92, 0.28);
    box-shadow: 0 24px 55px rgba(53, 18, 79, 0.14);
}

.sowkar-testimonials-page .ts-wall-quote {
