/* ---------- SECTION 4 – CTA (TESTIMONIALS) ---------- */
.sowkar-testimonials-cta.sowkar-cta {
    padding: 100px 0;
}

.sowkar-testimonials-cta .sowkar-cta-label {
    opacity: 0;
